(window.GIM_TS=window.GIM_TS||{})["Moed Katan.0"]={"from":0,"a":[["\u0003משקין\u0004 את \u0003בית השלחין\u0004 (שדה הזקוק להשקיית עזר, בנוסף למי הגשמים) \u0003ב\u0004חול ה\u0003מועד ו\u0004כן \u0003בשביעית\u0004 (בשנת השמיטה), \u0003בין ממעיין שיצא בתחילה,\u0004 שרק עכשיו, בתוך ימי המועד, התחיל לזרום שם, \u0003בין ממעיין שלא יצא בתחילה\u0004 והיה עובר שם מזמן. \u0003אבל אין משקין לא ממי הגשמים\u0004 שצריך לטרוח לדלותם ממקומם ולהשקות בהם, \u0003ולא ממי הקילון\u0004 מים ששואבים בדלי להשקיה.","\u0003ו\u0004כן \u0003אין עושין עוגיות\u0004 (גומות עגולות סביב) \u0003לגפנים\u0004 בחול המועד. \u0003ר' אלעזר בן עזריה אומר: אין עושין את האמה\u0004 (תעלת המים) שלא היתה קודם לכן \u0003בתחילה במועד ובשביעית, וחכמים אומרים: עושין את האמה בתחילה בשביעית, ומתקנין את\u0004 אמות המים \u0003המקולקלות במועד. ו\u0004עוד אמרו, שחול המועד הוא זמן קבוע לתקן כמה מצרכי הרבים:","\u0003מתקנין את קלקולי המים\u0004 (תעלות שנתקלקלו) \u0003שברשות הרבים, וחוטטין אותן\u0004 (מחטטים ומוציאים את העפר והליכלוך שנצטברו בהן) \u0003ומתקנין את הדרכים ואת הרחובות ואת מקוות המים\u0004 שטובלים בהם, \u0003ועושין כל צורכי הרבים\u0004 האחרים, \u0003ו\u0004כן \u0003מציינין את הקברות\u0004 מסמנים מקומות שבהם קבורים בני אדם, להודיע שיש שם טומאה, \u0003ויוצאין אף על הכלאים\u0004 לעקור את שתילי הכלאים שצמחו בין הזרעים במשך תקופת הגשמים.","תחילה תוהים על סגנון המשנה: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003יש לומר ממעיין שיצא בתחילה, דאתי לאינפולי\u0004 \u0005[שבא\u0006 שעלול \u0005ליפול]\u0006 לפי שאין עדיין למים אפיק יציב, ויתכן שהאדמה תיפול לתוך האפיק הזה, וייסתם, ויצטרך לטרוח לתקנו, ובכל זאת אמרנו ש\u0003משקין\u0004 אותו בחול המועד — \u0003ממעיין שלא יצא בתחילה, דלא אתי לאינפולי\u0004 \u0005[שאינו בא,\u0006 עלול \u0005ליפול]\u0006 שהרי יש לו אפיק קבוע \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006","ומשיבים: \u0003אמרי\u0004 \u0005[אומרים],\u0006 \u0003אצטריך\u0004 \u0005[נצרך]\u0006 הדבר להיאמר, שכן, \u0003אי תנא\u0004 \u0005[אם\u0006 היה \u0005שונה]\u0006 רק \u0003מעיין שיצא בתחילה, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 במקרה זה \u0003הוא\u0004 ש\u0003בית השלחין — אין\u0004 \u0005[כן]\u0006 ואילו \u0003בית הבעל\u0004 שדה שמסתפק במי גשמים בלבד — \u0003לא, משום דאתי לאינפולי\u0004 \u0005[שבא\u0006 שעלול \u0005ליפול],\u0006 \u0003אבל מעיין שלא יצא בתחילה, דלא אתי לאינפולי\u0004 \u0005[שאינו בא,\u0006 עלול \u0005ליפול]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003אפילו בית הבעל נמי\u0004 \u0005[גם כן]\u0006 מותר להשקותו השקיית עזר,","על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003מעיין שיצא בתחילה ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003מעיין שלא יצא בתחילה, בית השלחין — אין\u0004 \u0005[כן]\u0006 משקים אותו בחול המועד, \u0003בית הבעל —\u0004 אפילו ממעין שלא יצא בתחילה, גם כן \u0003לא\u0004 משקים אותו.","ועוד בירור לשוני: \u0003ומאי משמע דהאי\u0004 \u0005[ומה,\u0006 מהיכן, \u0005המשמעות שזה]\u0006 \u0003\"בית השלחין\" לישנא דצחותא\u0004 \u0005[לשון צמאון]\u0006 \u0003היא,\u0004 לומר שצריך הוא להשקיית עזר — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואתה עיף ויגע\"\u0004 (דברים כה, ב), \u0003ומתרגמינן\u0004 \u0005[ואנו מתרגמים]\u0006 זאת בתרגום המקובל: \u0003ואת משלהי ולאי\u0004 \u0005[ואתה צמא ועייף]\u0006 שתרגום \"עייף\", במובן צמא, הוא משלהי. ואף \"שלחין\" (בחילוף ה\"א=חי\"ת) פירושו צימאון.","\u0003ומאי משמע\u0004 \u0005[ומה,\u0006 מהיכן נובעת \u0005משמעות]\u0006 \u0003דהאי\u0004 \u0005[שזה]\u0006 \u0003\"בית הבעל\" לישנא דמייתבותא\u0004 \u0005[לשון ישוב]\u0006 \u0003היא,\u0004 כלומר, דבר מיושב ומבוסס שאינו נזקק כל כך — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי יבעל בחור בתולה\u0004 יבעלוך בניך\u0003\"\u0004 (ישעיהו סב, ה) \u0003ומתרגמינן\u0004 \u0005[ואנו מתרגמים]:\u0006 \u0003ארי כמה דמיתותב עולם עם בתולתא יתייתבון בגויך בנייך\u0004 \u0005[כמו שמתיישב עלם עם בתולה יתיישבו בתוכך בניך].\u0006","ומכאן לבירור שיטת המשנה. ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 ה\u0003תנא\u0004 של משנתנו הסבור \u0003דפסידא\u0004 \u0005[ש\u0006דבר שיש בו \u0005הפסד]\u0006 אם לא יעשהו במועד — \u0003אין\u0004 \u0005[כן]\u0006 מותר במועד, כמו השקיית בית השלחין, ואילו \u0003הרווחה\u0004 ותוספת — \u0003לא?\u0004 ויותר מכן אפשר ללמוד כי \u0003ואפילו במקום פסידא\u0004 \u0005[הפסד] —\u0006 \u0003מיטרח נמי לא טרחינן\u0004 \u0005[לטרוח גם כן איננו טורחים],\u0006 שהרי אסר להשקות ממי גשמים בכל מקרה, מפני הטירחה שבדבר.","\u0003אמר רב הונא:\u0004 שיטת \u0003ר' אליעזר בן יעקב היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר:\u0004 בתוך שדה מלא אילנות \u0003מושכין את המים\u0004 בתעלות \u0003מאילן לאילן, ובלבד שלא ישקה\u0004 אגב כך \u0003את השדה כולה,\u0004 הרי שהוא אוסר לעשות במועד דבר של הרווחה.","ועל ההשוואה הזו מקשים: \u0003אימור דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003ר' אליעזר\u0004 בן יעקב שסבור שדבר של \u0003הרווחה\u0004 הוא ש\u0003לא\u0004 יעשה במועד, אבל האם גם \u0003טירחא במקום פסידא\u0004 \u0005[הפסד]\u0006 \u0003מי שמעת ליה\u0004 \u0005[האם שמעת אותו]\u0006 שהוא אוסר? וצד זה של ההלכה במשנתנו לא נתבאר כלל בדברי ר' אליעזר בן יעקב.","\u0003אלא אמר רב פפא: הא מני\u0004 \u0005[זו,\u0006 משנתנו, כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' יהודה היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעיין היוצא בתחילה — משקין ממנו אפילו שדה בית הבעל,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: אין משקין אלא שדה בית השלחין שחרבה\u0004 (יבשה) וזקוקה למים. \u0003ר' אלעזר בן עזריה אומר: לא כך ולא כך. יתר על כן אמר ר' יהודה: לא יפנה אדם אמת המים\u0004 מתעלתה הקבועה ויעשה לה נתיב אחר \u0003וישקה לגינתו ולחורבתו בחולו של מועד.\u0004","ומתחילה מבררים את לשון הברייתא. \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חרבה\"\u0004 שנאמר בה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003חרבה ממש\u0004 ועכשיו הכל יבש בה, אם כן \u0003למה לי\u0004 \u0005[לו]\u0006 \u0003דמשקי לה\u0004 \u0005[שישקה אותה],\u0006 שאם כבר נבלו הצמחים מה תועיל ההשקיה? \u0003אמר אביי:\u0004 הכוונה \u0003שחרבה ממעיין זה\u0004 שהיה בה עד עכשיו \u0003ויצא לה\u0004 בינתיים \u0003מעיין אחר\u0004 ואם לא ישקו ממנו יהיה הפסד.","ועוד מבארים: מה ש\u0003ר' אלעזר בן עזריה אומר לא כך ולא כך,\u0004 כוונתו: \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם \u0003חרב מעיינה ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם \u0003לא חרב מעיינה,\u0004 הכלל הוא: \u0003מעיין שיצא בתחילה — לא\u0004 ישקו ממנו אפילו בית השלחין. ולמדנו מדברי ר' יהודה שאף במקום הפסד (בית השלחין שחרבה) אסור לטרוח טירחה יתירה.","ושואלים: \u0003וממאי\u0004 \u0005[וממה]\u0006 מסיק אתה שמשנתנו כדברי ר' יהודה? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' יהודה: בית השלחין — אין\u0004 \u0005[כן]\u0006 משקים אותו בחול המועד ו\u0003בית הבעל — לא, אלא\u0004 לגבי \u0003מעיין שיצא בתחילה\u0004 שממנו אין להשקות"],["\u0003דלמא אתי לאינפולי\u0004 \u0005[שמא יבוא,\u0006 עלול \u0005ליפול],\u0006 \u0003אבל מעיין שלא יצא בתחילה דלא אתי לאינפולי\u0004 \u0005[שאינו יבוא,\u0006 עלול \u0005ליפול]\u0006 שכבר נתייצב, \u0003אפילו בית הבעל נמי\u0004 \u0005[גם כן]\u0006 מותר להשקות ממנו!","ואומרים: \u0003אם כן,\u0004 אם אתה סבור כך — \u0003מתניתין אמאן תרמייה\u0004 \u0005[משנתנו על מי תשליך אותה]?\u0006 ולדעת איזה חכם תשייך אותה? שהרי לפירוש זה אין משנתנו זהה לשום שיטה, ואילו כפי שפירשנו הריהי כדעת ר' יהודה. \u0003אלא\u0004 יש לומר: \u0003ל\u0004שיטת \u0003ר' יהודה לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003מעיין שיצא בתחילה, ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003מעיין שלא יצא בתחילה, בית השלחין — אין\u0004 \u0005[כן]\u0006 משקים, \u0003בית הבעל — לא. והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 בברייתא את המחלוקת ב\u0003מעיין שיצא בתחילה,\u0004 הרי זה \u0003להודיעך כחו\u0004 של \u0003ר' מאיר\u0004 כמה הוא מיקל, ש\u0003אפילו מעיין היוצא בתחילה משקין ממנו, אפילו\u0004 את \u0003שדה הבעל.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו האמוראים בשאלה הבאה: \u0003המנכש\u0004 את העשבים הרעים מתוך הצמחים שרוצה בהם, או \u0003המשקה מים לזרעים בשבת, משום מאי\u0004 \u0005[מה]\u0006 \u0003מתרינן ביה\u0004 \u0005[מתרים אנו בו]?\u0006 שהלא אין עונשים ללא התראה, וכאשר מתרים בעבריין צריך לומר לו גם מה היא העבירה שהוא עובר עליה, ובשבת — על איזה אב מלאכה הוא עובר. \u0003רבה אמר:\u0004 מתרים בו \u0003משום\u0004 מלאכת \u0003חורש,\u0004 שמעשהו הוא מעין מלאכת חרישה. \u0003רב יוסף אמר: משום\u0004 מלאכת \u0003זורע.\u0004","\u0003אמר רבה: כוותי דידי מסתברא\u0004 \u0005[כשיטתי שלי מסתבר]\u0006 לומר, והטעם: \u0003מה דרכו\u0004 וכוונתו \u0003של\u0004 ה\u0003חורש\u0004 במעשה החרישה — \u0003לרפויי ארעא\u0004 \u0005[לרפות\u0006 ולרכך את \u0005הקרקע],\u0006 \u0003האי נמי מרפויי ארעא\u0004 \u0005[זה גם כן\u0006 הניכוש וההשקיה, \u0005מרפים,\u0006 מרככים את \u0005האדמה]\u0006 ומכשירים אותה. \u0003אמר רב יוסף: כוותי דידי מסתברא\u0004 \u0005[כשיטתי שלי מסתבר]\u0006 לומר, והטעם: \u0003מה דרכו\u0004 וכוונתו \u0003של\u0004 ה\u0003זורע\u0004 ומה מטרת מלאכתו — \u0003לצמוחי פירא\u0004 \u0005[להצמיח\u0006 את \u0005הפרי],\u0006 \u0003הכא נמי מצמח פירא\u0004 \u0005[כאן גם כן\u0006 הניכוש וההשקייה \u0005מצמיחים\u0006 את \u0005הפרי]\u0006 וזוהי תכליתם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבה: לדידך קשיא\u0004 \u0005[לשיטתך קשה]\u0006 \u0003ול\u0004שיטת \u0003רב יוסף קשיא\u0004 \u0005[קשה].\u0006 \u0003לדידך קשיא\u0004 \u0005[לשיטתך קשה]\u0006 וכי \u0003משום חורש אין\u0004 \u0005[כן]\u0006 יש בכך איסור, ו\u0003משום זורע לא? ולרב יוסף קשיא\u0004 \u0005[קשה]\u0006 להיפך: \u0003משום זורע אין\u0004 \u0005[כן],\u0006 \u0003משום חורש לא?\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003כל היכא\u0004 \u0005[מקום]\u0006 \u0003דאיכא תרתי\u0004 \u0005[שיש\u0006 \u0005שתי\u0006 מלאכות בדבר\u0005]\u0006 \u0003לא מיחייב\u0004 \u0005[אינו חייב]\u0006 \u0003אלא\u0004 משום \u0003חדא\u0004 \u0005[אחת]\u0006 מהן, ולכן צריך להכריע למי מהן דומה זו יותר, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב כהנא:\u0004 מי שהיה \u0003זומר\u0004 את ענפי האילן אבל היה \u0003צריך לעצים\u0004 שהוא זומר להשתמש בזמורות אלה להסקה או למטרה אחרת — \u0003חייב שתים,\u0004 משום שעושה שני אבות מלאכה יחד, \u0003אחת\u0004 חייב \u0003משום נוטע\u0004 שהרי זמירת האילנות מסייעת לצמיחתם, והיא כעין תולדה של מלאכת הנטיעה, \u0003ואחת משום קוצר\u0004 שהרי מהותה של קצירה שהוא תולש מן המחובר לקרקע את הדבר שהוא זקוק לו, וכיון שהוא צריך לעצים הרי הוא כקוצר, הרי שאם יש בדבר שתי מלאכות — חייב על שתיהן.","ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר לשניהם.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב יוסף לרבה,\u0004 ממה ששנינו: \u0003המנכש והמחפה\u0004 באדמה את השורשים שהתגלו \u0003לכלאים — לוקה\u0004 משום \"לא תזרע כלאים\" (ויקרא יט, יט). \u0003ר' עקיבא אומר: אף המקיים\u0004 את הכלאים במקומם אף על פי שיכול לעוקרם לוקה, משום איסור כלאים.","ומסביר רב יוסף: \u0003בשלמא לדידי\u0004 \u0005[נניח לשיטתי]\u0006 \u0003דאמינא\u0004 \u0005[שאני אומר]\u0006 שהמנכש חייב \u0003משום\u0004 מלאכת \u0003זורע — היינו\u0004 \u0005[הרי זה]\u0006 משום \u0003דאסירא\u0004 \u0005[שאסורה]\u0006 \u0003זריעה בכלאים\u0004 ולכן לוקה על הניכוש, \u0003אלא לדידך דאמרת\u0004 \u0005[לשיטתך שאתה אומר]\u0006 שהאיסור הוא \u0003משום\u0004 מלאכת \u0003חורש, חרישה בכלאים מי אסירא\u0004 \u0005[האם\u0006 היא \u0005אסורה]?\u0006 שהרי בשעת החרישה עדיין לא שייך איסור כלאים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: לדעתי לוקה המנכש לא משום מלאכת חורש, אלא \u0003משום\u0004 שהוא \u0003מקיים\u0004 כלאים.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנינו בסופה]\u0006 של אותה ברייתא \u0003ר' עקיבא אומר אף המקיים, מכלל\u0004 הדבר אתה למד שטעמו של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003משום מקיים\u0004 אלא משום מלאכה אחרת!","ודוחים: \u0003כולה,\u0004 כל אותה ברייתא כשיטת \u0003ר' עקיבא היא, ו\u0004בסגנון \"\u0003מאי\u0004 \u0005[מה]\u0006 \u0003טעם\" קאמר\u0004 \u0005[אמר],\u0006 וכך צריך להבין את הברייתא: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003טעם המנכש ומחפה בכלאים לוקה — משום מקיים, שר' עקיבא אומר: אף המקיים\u0004 לוקה.","ושואלים לעצם הדברים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' עקיבא,\u0004 כיצד למד הוא דבר זה מן הכתובים? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"שדך לא תזרע כלאים\"\u0004 (ויקרא יט, יט), \u0003אין לי\u0004 מן הכתוב \u0003אלא זורע, מקיים\u0004 שאינו עושה מעשה \u0003מניין\u0004 שאף הוא עובר?","\u0003תלמוד לומר: \"כלאים שדך לא\",\u0004 שאם קוראים את הפסוק כך, אפשר ללמוד ממנו שבכל אופן אסור שיהיו כלאים בשדה.","ומכאן אנו ממשיכים לענייננו, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003משקין\u0004 את \u0003בית השלחין\u0004 השקיית עזר \u0003ב\u0004חול ה\u0003מועד ובשביעית\u0004 (בשנת השמיטה).","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ב\u0003מועד\u0004 מותר, שהרי טעם האיסור במועד \u0003משום טירחא הוא,\u0004 שאין לטרוח בעבודה קשה בחול המועד, \u0003ובמקום פסידא\u0004 \u0005[הפסד]\u0006 \u0003שרו רבנן\u0004 \u0005[התירו חכמים]\u0006 לטרוח אפילו במועד, \u0003אלא שביעית, בין למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שהשקייה יש בה \u0003משום\u0004 מלאכת \u0003זורע ובין למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שיש בה \u0003משום\u0004 מלאכת \u0003חורש, זריעה וחרישה בשביעית מי שרי\u0004 \u0005[האם מותר]?\u0006 והרי מפורש בתורה איסור עבודת קרקע בשביעית!","\u0003אמר אביי:\u0004 במשנה מדובר \u0003בשביעית בזמן הזה\u0004 שאיסורה רק מדברי סופרים, \u0003ו\u0004כשיטת \u0003רבי היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 מה שנאמר \u0003\"וזה דבר השמטה שמוט\u0004 כל בעל משה ידו...\u0003\"\u0004 (דברים טו, ב), \u0003בשתי שמיטות\u0004 (\"השמיטה\" \"שמוט\") \u0003הכתוב מדבר, אחת שמיטת קרקע\u0004 שלא לעבוד את האדמה, \u0003ואחת שמיטת כספים\u0004 שלא לגבות חובות כספים.","והכתוב משוה אותן; \u0003בזמן שאתה משמט קרקע\u0004 מן התורה \u0003אתה משמט כספים, ובזמן שאי\u0004 (אין) \u0003אתה משמט קרקע — אי\u0004 (אין) \u0003אתה משמט כספים,\u0004 הרי שיש זמן שאין בו שמיטת קרקעות, ואימתי — בזמן הזה. ואם כן לשיטת רבי, בזמן הזה (ולמעשה — לאחר שבטלו היובלות ודיני אחוזת נחלה הכתובים בתורה) שמירת שביעית היא רק מדברי סופרים, ובמקום הפסד התירו חכמים.","\u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים ששביעית בזמן הזה מדברי תורה היא, וטעם היתר ההשקיה — כי דווקא \u0003אבות\u0004 מלאכה, כגון זריעה וחרישה ממש \u0003אסר רחמנא\u0004 \u0005[אסרה התורה],\u0006"],["אבל \u0003תולדות\u0004 (מלאכות דומות להן) \u0003לא אסר רחמנא\u0004 \u0005[אסרה התורה].\u0006 ומקור הדבר \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובשנה השביעית שבת שבתון יהיה לארץ\u0004 שבת לה' \u0003שדך לא תזרע\u0004 וכרמך לא תזמור. את ספיח קצירך לא תקצור ואת ענבי נזירך לא תבצור\u0003\"\u0004 (ויקרא כה, ד-ה).","\u0003מכדי\u0004 \u0005[הלא]\u0006 \u0003זמירה בכלל זריעה\u0004 היא שהרי מטרתה לעודד את הצמיחה, \u0003ובצירה בכלל קצירה\u0004 — נטילת היבול מן הצמח. \u0003למאי הלכתא כתבינהו רחמנא\u0004 \u0005[לאיזו הלכה כתבה אותם התורה]\u0006 במפורש, ולא הסתפקה באיסור הכללי של \"שבת שבתון יהיה לארץ\"?","אלא הדברים הללו נתפרשו \u0003למימרא\u0004 \u0005[לומר\u0006 לנו\u0005]:\u0006 \u0003דאהני\u0004 \u0005[שעל אלה]\u0006 ה\u0003תולדות\u0004 של המלאכות המפורשות \u0003מיחייב\u0004 \u0005[חייב\u0006 הוא\u0005],\u0006 \u0003אאחרנייתא לא מיחייב\u0004 \u0005[על\u0006 התולדות \u0005האחרות אינו חייב].\u0006","ושואלים: \u0003ו\u0004כי על מלאכות אחרות הוא \u0003לא\u0004 חייב? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"שדך לא תזרע וכרמך לא תזמר\" אין לי\u0004 איסור מפורש \u0003אלא\u0004 במלאכות \u0003זירוע וזימור, מנין לניכוש ולעידור ולכיסוח\u0004 (כריתת העשבים הרעים) שגם הם אסורים — \u0003תלמוד לומר: \"שדך לא\" \"כרמך לא\".\u0004 וכוונתו: \u0003לא\u0004 תעשה \u0003כל מלאכה שבשדך ולא כל מלאכה שבכרמך.\u0004","וכן אמרו: \u0003מנין שאין מקרסמין\u0004 (זומרים את האילנות), \u0003ואין מזרדין\u0004 (כורתים את הזרדים היבשים מהעצים), \u0003ואין מפסגין\u0004 (חותכים ענפים גדולים) \u0003באילן — תלמוד לומר: \"שדך לא\" \"כרמך לא\",\u0004 שכוונתו: \u0003לא\u0004 תעשה \u0003כל מלאכה שבשדך ולא כל מלאכה שבכרמך.\u0004","וכן, \u0003מנין שאין מזבלין\u0004 את השדות והכרמים, \u0003ואין מפרקין\u0004 אבנים המונחות על עיקר האילן ומפריעות לצמיחתו, \u0003ואין מאבקין\u0004 מכסים באבק את השורשים שנתגלו, \u0003ואין מעשנין\u0004 מעלים עשן מתחת לאילן כדי להשמיד את התולעים ש\u0003באילן — תלמוד לומר: \"שדך לא\" \"כרמך לא\", כל מלאכה שבשדך לא\u0004 תעשה, \u0003וכל מלאכה שבכרמך לא\u0004 תעשה.","לכאורה נובע מכאן שכל מלאכה בשדה אסורה, \u0003יכול לא יקשקש\u0004 (יעשה עידור קל) \u0003תחת\u0004 עצי \u0003הזיתים, ולא יעדר תחת הגפנים ולא ימלא נקעים\u0004 (סדקים שבאדמה) \u0003מים, ולא יעשה עוגיות\u0004 (עיגול עמוק קצת סביב) \u0003לגפנים\u0004 שיצטברו בהן מי הגשמים — \u0003תלמוד לומר: \"שדך לא תזרע\".\u0004","וכך נלמד: \u0003זריעה בכלל\u0004 כל מלאכות השדה \u0003היתה\u0004, שהרי לשיטה זו כל מלאכת הקרקע אסורה, \u0003ולמה יצתה\u0004 (יצאה) זריעה מן הכלל ונכתבה במפורש — כדי \u0003להקיש\u0004 (להשוות) \u0003אליה, לומר לך: מה זריעה מיוחדת\u0004 שהיא \u0003עבודה שבשדה ושבכרם\u0004 גם יחד, \u0003אף כל שהיא עבודה שבשדה ושבכרם\u0004 אסורה, אבל דבר שהוא רק בכרם ואינו בשדה, כלומר שנועד רק לקיום האילנות משנה לשנה — מותר. ואם כן למדנו מברייתא זו שאסורה כל מלאכה בשביעית, ולא רק זריעה וזמירה בלבד!","ודוחים: איסורים אלו שאמרו פרט לזריעה וזמירה, כולם הם \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003וקרא אסמכתא בעלמא\u0004 \u0005[והכתוב\u0006 שהבאנו לראיה \u0005סמך בלבד\u0006 הוא\u0005]\u0006 ואינו דין התורה ממש.","אגב הדברים שואלים: \u0003וקשקוש\u0004 (עידור) מתחת לאילנות \u0003בשביעית מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003והא כתיב\u0004 \u0005[והלא נאמר]:\u0006 \u0003\"והשביעת תשמטנה ונטשתה\"\u0004 (שמות כג, יא) ושנינו על כך: \u0003\"תשמטנה\" — מלקשקש, \"ונטשתה\" — מלסקל\u0004 את האבנים שבשדה, הרי שהקישקוש אסור בשביעית!","\u0003אמר רב עוקבא בר חמא: תרי קשקושי הוו\u0004 \u0005[שני\u0006 מיני \u0005עידור הם];\u0006 \u0003חד אברויי אילני\u0004 \u0005[אחד\u0006 שמטרתו \u0005להבריא\u0006 ולחזק את \u0005האילנות]\u0006 \u0003וחד סתומי פילי\u0004 \u0005[ואחד\u0006 הוא \u0005לסתום\u0006 את \u0005הבקעים\u0006 בקרקע\u0005],\u0006 ויש ביניהם הבדל הלכה למעשה; \u0003אברויי\u0004 \u0005[להבריא]\u0006 את ה\u0003אילן — אסור,\u0004 שזה מעין מלאכת חרישה, שהרי הוא מחזק את הצמיחה, אולם \u0003סתומי פילי\u0004 \u0005[לסתום\u0006 את \u0005הבקעים]\u0006 — \u0003שרי\u0004 \u0005[מותר],\u0006 משום שעל ידי כך הוא מונע נזק לאילן.","באותו ענין עצמו \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003החורש בשביעית,\u0004 נחלקו \u0003ר' יוחנן ור' אלעזר\u0004 במהות איסור זה, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: לוקה\u0004 על כך, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אינו לוקה.\u0004 ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003ב\u0004יחס לשיטת \u0003ר' אבין אמר ר' אילעא קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 שאחד מהם מקבלה ואחד אינו מקבלה. ש\u0003אמר ר' אבין אמר ר' אילעא: כל מקום שנאמר\u0004 בתורה \u0003כלל ב\u0004מצות \u0003\"עשה\", ופרט\u0004 הקשור לאותה מצוה \u0003ב\"לא תעשה\" — אין דנים אותו\u0004 לפי מידת ההלכה \u0003בכלל פרט וכלל\u0004 שאז רואים את הפרט כדוגמה של הכלל ומרחיבים אותו לגבי כל הכלל, אלא רואים זאת כשתי הלכות נפרדות.","ולענייננו, \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 ש\u0003לוקה\u0004 גם על חרישה \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את שיטת \u0003ר' אבין אמר ר' אילעא,\u0004 ולכן הוא דורש כך: נאמר \"ובשנה השביעית שבת שבתון יהיה לארץ\" (ויקרא כה, ד) — הרי מצוות \"עשה\" כללית, ואחר כך נאמר \"שדך לא תזרע\" (ויקרא כה, ד) — הרי פרט באותה מצוה ב\"לא תעשה\", וחוזר וכולל \"שבת שבתון יהיה לארץ\" (ויקרא כה, ה), ומכאן הוא למד שיש איסור \"לא תעשה\" על כל עבודות האדמה בשביעית, כמו שיש במלאכת הזריעה.","\u0003ו\u0004אילו \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 ש\u0003אינו לוקה, אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את שיטת \u0003ר' אבין\u0004 ולכן על שאר עבודות האדמה שלא נאמרו במפורש — עובר בעשייתן רק במצוות \"עשה\", ורק על זריעה וזמירה עובר ב\"לא תעשה\".","את ההצעה הזו דוחים: \u0003לא, דכולי עלמא לית ליה\u0004 \u0005[לדעת הכל אין להם,\u0006 אינם מקבלים\u0005]\u0006 את שיטת \u0003ר' אבין אמר ר' אילעא,\u0004 ולכן, \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003לוקה — שפיר\u0004 \u0005[יפה]\u0006 שלומד בכלל ופרט וכלל,","\u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003אינו לוקה, אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 טעם אחר: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003זמירה בכלל זריעה\u0004 היא מבחינת מהותה, \u0003ובצירה בכלל קצירה,\u0004 אם כן \u0003למאי הלכתא כתבינהו רחמנא\u0004 \u0005[לאיזו הלכה כתבה אותם התורה]\u0006 במפורש? \u0003למימר דאהני\u0004 \u0005[לומר שעל אלה]\u0006 ה\u0003תולדות הוא דמיחייב\u0004 \u0005[שחייב],\u0006 על \u0003תולדה אחרינא לא מיחייב\u0004 \u0005[אחרת אינו חייב],\u0006 אם כן גילה כאן הכתוב שאינו חייב על מלאכות אחרות שאינן מפורשות, ולכן אינו מחשיב את החרישה כאסורה בשביעית במצות \"לא תעשה\".","ושואלים: \u0003ולא?\u0004 וכי אינו חייב על מלאכות אחרות? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"שדך לא תזרע וכרמך לא תזמר\"\u0004 (ויקרא כה, ה) \u0003אין לי אלא זירוע וזימור\u0004 שהם אסורים, \u0003מנין לעידור ולקישקוש ולכיסוח\u0004 שאף הם אסורים \u0003— תלמוד לומר: \"שדך לא\" \"כרמך לא\",\u0004 לומר: \u0003לא\u0004 תעשה \u0003כל מלאכה שבשדך ולא\u0004 תעשה \u0003כל מלאכה שבכרמך.\u0004","\u0003ומנין שאין מקרסמין\u0004 (זומרים את האילנות), \u0003ואין מזרדין\u0004 (כורתים את הזרדים היבשים מהעצים), \u0003ואין מפסגין\u0004 (חותכים ענפים גדולים) \u0003באילן — תלמוד לומר: \"שדך לא\" \"כרמך לא\",\u0004 שכוונתו: \u0003לא\u0004 תעשה \u0003כל מלאכה שבשדך ולא כל מלאכה שבכרמך.\u0004","וכן, \u0003מנין שאין מזבלין\u0004 את השדות והכרמים, \u0003ואין מפרקין\u0004 אבנים המונחות על עיקר האילן ומפריעות לצמיחתו, \u0003ואין מעשנין\u0004 עושים עשן מתחת לאילן כדי להשמיד את התולעים ש\u0003באילן — תלמוד לומר: \"שדך לא\" \"כרמך לא\", כל מלאכה שבשדך לא\u0004 תעשה, \u0003וכל מלאכה שבכרמך לא\u0004 תעשה.","לכאורה נובע מכאן שכל מלאכה בשדה אסורה, \u0003יכול לא יקשקש\u0004 (יעשה עידור קל) \u0003תחת\u0004 עצי \u0003הזיתים, ולא יעדר תחת הגפנים ולא ימלא נקעים\u0004 (סדקים שבאדמה) \u0003מים, ולא יעשה עוגיות\u0004 (עיגול עמוק קצת סביב) \u0003לגפנים\u0004 שיצטברו בהן מי הגשמים — \u0003תלמוד לומר: \"שדך לא תזרע\".\u0004","וכך נלמד: \u0003זריעה בכלל\u0004 כל מלאכות השדה היתה, שהרי לשיטה זו כל מלאכת הקרקע אסורה, \u0003ולמה יצתה\u0004 (יצאה) זריעה מן הכלל ונכתבה במפורש — כדי \u0003להקיש\u0004 (להשוות) \u0003אליה, לומר לך: מה זריעה מיוחדת\u0004 שהיא \u0003עבודה שבשדה ושבכרם\u0004 גם יחד, \u0003אף כל שהיא עבודה שבשדה ושבכרם\u0004 אסורה, אבל דבר שהוא רק בכרם ואינו בשדה, כלומר, שנועד רק לקיום האילנות משנה לשנה — מותר. ואם כן למדנו מברייתא זו שאסורה כל מלאכה בשביעית, ולא רק זריעה וזמירה בלבד!","ודוחים: איסורים אלו שאמרו פרט לזריעה וזמירה, כולם הם \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003וקרא אסמכתא בעלמא\u0004 \u0005[והכתוב\u0006 שהבאנו לראיה \u0005סמך בלבד\u0006 הוא\u0005]\u0006 ואינו דין התורה ממש. והרי מכאן שמלבד זריעה וזמירה אסורות כל שאר המלאכות!"],["\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 מסורת ששמע מחכמי ארץ ישראל בלשון זו: \u0003יכול ילקה על התוספת — ונסיב לה תלמודא לפטורא\u0004 \u0005[ויש על כך לימוד\u0006 \u0005לפטור],\u0006 והעיר רב דימי: \u0003ולא ידענא מאי תלמודא ומאי\u0004 \u0005[ואיני יודע מהו הלימוד ומהי]\u0006 ה\u0003תוספת\u0004 שהתכוונו להם בשמועה זו.","ונחלקו חכמים בפירוש מסורת זו, \u0003ר' אלעזר אמר:\u0004 תוספת זו שאמרו היא \u0003חרישה\u0004 בשביעית, שלא נתפרש בה איסור \"לא תעשה\" בתורה, והיא כתוספת למלאכות המפורטות בכתוב. \u0003והכי קאמר\u0004 \u0005[וכך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003יכול ילקה על חרישה\u0004 בשמיטה \u0003דאתיא\u0004 \u0005[ש\u0006היא \u0005באה,\u0006 נלמדת\u0005]\u0006 \u0003מכלל ופרט וכלל\u0004 שאף היא אסורה, \u0003ונסיב ליה תלמודא לפטורא\u0004 \u0005[ויש על כך לימוד לפטור]\u0006 את החרישה מעונש מלקות.","וטעם הדבר: שאם לוקים על החרישה, \u0003אם כן כל הני פרטי\u0004 \u0005[אלה הפרטים]\u0006 שמנה הכתוב בבצירה וזמירה \u0003למה לי?\u0004 אלא ודאי יש להבין שבאו אלה ללמד שרק על פרטים אלה לוקים, ועל מלאכות אחרות אין לוקים.","\u0003ור' יוחנן אמר:\u0004 תוספת זו היא \u0003ימים שהוסיפו חכמים לפני ראש השנה\u0004 של השביעית שגם בהם אסור לעבוד את האדמה כדי להכשירה לשנה הבאה. \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003יכול ילקה על תוספת ראש השנה, דאתיא\u0004 \u0005[ש\u0006היא \u0005באה,\u0006 נלמדת\u0005]\u0006 מן הכתוב \u0003\"בחריש ובקציר תשבת\"\u0004 (שמות לד, כא), שמייתור הכתוב למדו שלא רק עבודת האדמה בשביעית עצמה אסורה אלא אפילו חריש וקציר של ערב שביעית אסורים, \u0003ונסיב לה תלמודא לפטורא\u0004 \u0005[ויש על כך לימוד לפטור]\u0006 לענין עונש, \u0003כדבעינן למימר לקמן\u0004 \u0005[כפי שנרצה לומר אחר כך].\u0006","ומסבירים: \u0003מאי\u0004 \u0005[מה הם]\u0006 אותם \u0003ימים שלפני ראש השנה, כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003עד מתי חורשין בשדה אילן\u0004 (שדה שצומחים בו אילנות) ב\u0003ערב שביעית? בית שמאי אומרים: כל זמן שיפה\u0004 החריש \u0003ל\u0004גידולו של \u0003פרי\u0004 המצוי כבר על האילנות — מותר, אבל לאחר מכן שהחרישה היא רק לתועלת האילן והפירות שעתיד להצמיח בשנה הבאה — אסור, \u0003ובית הלל אומרים: עד העצרת\u0004 (שבועות) מותר לחרוש. ומעירים: \u0003וקרובין דברי אלו להיות כדברי אלו,\u0004 כלומר למעשה אין הבדל ניכר בתאריך בין דברי בית שמאי לדברי בית הלל.","\u0003ועד מתי חורשין שדה הלבן\u0004 (שדה תבואה) \u0003ערב שביעית — משתכלה הלחה\u0004 (הרטיבות שמחמת הגשמים) שבשדות, \u0003וכל זמן שבני אדם\u0004 בדרך כלל \u0003חורשים\u0004 עדיין את שדותיהם \u0003ליטע מקשאות ומדלעות\u0004 (לגידול קישואים ודלעת) הנזרעים בסוף החורף.","\u0003ר' שמעון אומר: אם כן\u0004 שלא נקבע זמן מסויים \u0003נתנה תורה שיעור לכל אחד ואחד בידו,\u0004 שיכול אדם לומר בכל עת שהוא חורש על מנת לזרוע באותה שנה. \u0003אלא\u0004 יש לקבוע זמן מוגדר: \u0003בשדה הלבן — חורשים עד הפסח, ובשדה האילן\u0004 — חורשים \u0003עד העצרת. ובית הלל אומרים: עד הפסח.\u0004","\u0003ואמר ר' שמעון בן פזי אמר ר' יהושע בן לוי משום\u0004 (בשם) \u0003בר קפרא: רבן גמליאל ובית דינו נמנו\u0004 (דנו והצביעו והחליטו) \u0003על שני פרקים\u0004 (זמנים) \u0003הללו,\u0004 פסח ועצרת, שאסרום חכמים בשנה השישית, \u0003ובטלום\u0004 והתירו לחרוש עד ראש השנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אבהו, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר לו \u0003ריש לקיש לר' יוחנן: רבן גמליאל ובית דינו היכי מצו למבטלי תקנתא\u0004 \u0005[כיצד יכולים\u0006 הם \u0005לבטל תקנה]\u0006 של \u0003בית שמאי ובית הלל\u0004 הגדולים מהם? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין בית דין יכול לבטל דברי בית דין חבירו אלא אם כן גדול ממנו בחכמה ובמנין!\u0004","\u0003\"אשתומם\u0004 \u0005[השתומם,\u0006 תהה\u0005]\u0006 \u0003כשעה חדה\u0004 \u0005[אחת]\u0006\u0003\"\u0004 (דניאל ד, טז) זמן מה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימור\u0004 \u0005[אמור],\u0006 כי \u0003כך התנו ביניהן\u0004 בשעת קביעת התקנה: \u0003כל הרוצה לבטל\u0004 גזירה זו — \u0003יבוא ויבטל.\u0004","ותוהים: וכי \u0003דידהו\u0004 \u0005[שלהם],\u0006 של בית שמאי ובית הלל \u0003היא\u0004 גזירה זו שהם יכולים לתקן בה? הלא \u0003הלכה למשה מסיני היא!\u0004 ש\u0003אמר ר' אסי אמר ר' יוחנן משום ר' נחוניא איש בקעת בית חורתן: עשר נטיעות\u0004 (עצים צעירים) המצויות בשדה של בית סאה מותר לחרוש בשבילן את כל השדה עד ראש השנה, לצורך האילנות. משמע שבעצים אחרים — אסור. וכן דין \u0003ערבה\u0004 שמביאים במקדש יתר על ערבה שבלולב, \u0003ו\u0004כן \u0003ניסוך המים\u0004 בחג הסוכות על המזבח, הלכות אלה \u0003הלכה למשה מסיני\u0004 הן. משמע שאיסור החרישה בערב שביעית אינו מתקנת חכמים בבית שני, אלא הוא מיסודות מסורת תורה שבעל פה!","\u0003אמר ר' יצחק: כי גמירי הלכתא\u0004 \u0005[כאשר\u0006 היו \u0005לומדים הלכה\u0006 זו\u0005],\u0006 היה האיסור בה רק \u0003שלשים יום לפני ראש השנה, ואתו הני תקון\u0004 \u0005[ובאו אלו\u0006 בית שמאי ובית הלל, \u0005ותיקנו]\u0006 זמנים מוקדמים יותר, \u0003מפסח ומעצרת, ואתנו בדידהו\u0004 \u0005[והתנו ב\u0006תקנה \u0005שלהם]:\u0006 \u0003כל הרוצה לבטל יבוא ויבטל.\u0004","ועוד תוהים: \u0003והני הלכתא נינהו\u0004 \u0005[ו\u0006כי איסורים \u0005אלה\u0006 משום \u0005הלכות\u0006 למשה מסיני \u0005הן]?\u0006 הלא \u0003קראי נינהו\u0004 \u0005[כתובים\u0006 מפורשים \u0005הם],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"בחריש ובקציר תשבת\"\u0004 (שמות לד, כא) \u0003ר' עקיבא אומר: אין צריך לומר\u0004 שהתכוון הפסוק ל\u0003חריש\u0004 ול\u0003קציר של שביעית — שהרי כבר נאמר: \"\u0004ובשנה השביעית שבת שבתון יהיה לארץ \u0003שדך לא תזרע וכרמך לא תזמר\"\u0004 (ויקרא כה, ד), אם כן נאסרה כל עבודה בשביעית, \u0003אלא\u0004 בא הכתוב לאסור \u0003חריש של ערב שביעית\u0004"],["\u0003שנכנס לשביעית,\u0004 כלומר, חרישה שנועדה לסייע לגידולים בשנה השביעית \u0003וקציר של שביעית שיצא למוצאי שביעית\u0004 שאסור לקצור בשמינית את התבואה שגדלה בשביעית.","\u0003ר' ישמעאל אומר:\u0004 יש להבין את הפסוק כמשמעו, לענין שבת, וכך יש ללמוד: \u0003מה חריש רשות,\u0004 שהרי אין בתורה חריש של מצוה, \u0003אף קציר\u0004 האמור כאן — \u0003רשות, יצא קציר העומר שהיא מצוה,\u0004 והוא מותר בלא שינוי גם בשבת. ואם כן, לפי ר' עקיבא יש ראיה מן הכתוב לאסור חרישה ערב שביעית!","\u0003אלא אמר רב נחמן בר יצחק,\u0004 יש לדחות את מה שאמרנו ולומר כך: \u0003כי גמירי הלכתא\u0004 \u0005[כאשר למדו\u0006 את \u0005ההלכה\u0006 למשה מסיני\u0005],\u0006 הרי זה \u0003למישרי\u0004 \u0005[להתיר]\u0006 \u0003ילדה\u0004 (נטיעה צעירה) לחרוש בית סאה עבורה. ואילו \u0003קראי\u0004 \u0005[הכתובים]\u0006 שהבאנו — כדי \u0003למיסר\u0004 \u0005[לאסור]\u0006 את הנטיעה ה\u0003זקינה,\u0004 שעץ גדול שכבר הושרש מן התורה אין חורשים בשבילו שלושים יום קודם ראש שנת השמיטה, ובאו בית שמאי ובית הלל וגזרו מפסח ועד עצרת.","ותוהים: \u0003וכיון דהלכתא למשרי\u0004 \u0005[שההלכה\u0006 היתה \u0005להתיר]\u0006 \u0003ילדה,\u0004 האם \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ממילא\u0004 תלמד שה\u0003זקינה אסירה\u0004 \u0005[אסורה]?!\u0006 וכל זה הלכה מסיני הוא ולא מן המקראות!","\u0003אלא\u0004 יש לומר באופן אחר: איסור חריש בערב שביעית הוא מכוח \u0003הלכתא\u0004 \u0005[ההלכה\u0006 למשה מסיני\u0005]\u0006 \u0003ל\u0004שיטת \u0003ר' ישמעאל,\u0004 שדורש פסוק זה לענין אחר, ואילו מ\u0003קראי\u0004 \u0005[\u0006מן \u0005הכתובים]\u0006 \u0003ל\u0004שיטת \u0003ר' עקיבא.\u0004","\u0003ור' יוחנן אמר\u0004 הסבר אחר: \u0003רבן גמליאל ובית דינו מדאורייתא בטיל להו\u0004 \u0005[מן התורה ביטלו אותם],\u0006 שמצאו ראיה מן התורה שאין לאסור כלל עבודת האדמה בערב שביעית.","\u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"שבת\" \"שבת\" משבת בראשית\u0004 (שבת סתם, היום השביעי בשבוע): \u0003מה להלן\u0004 בשבת בראשית \u0003היא\u0004 עצמה \u0003אסורה\u0004 במלאכה אולם \u0003לפניה ולאחריה מותרין, אף כאן\u0004 שנת שבת הארץ \u0003היא\u0004 עצמה \u0003אסורה,\u0004 אבל \u0003לפניה ולאחריה מותרין.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי:\u0004 אם כן, לדעת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שאיסור חרישה הוא \u0003הלכתא\u0004 \u0005[הלכה\u0006 למשה מסיני\u0005] — וכי\u0006 \u0003אתיא\u0004 \u0005[באה,\u0006 יכולה לבוא\u0005]\u0006 ה\u0003גזרה שוה\u0004 \"שבת\" \"שבת\" \u0003עקרה הלכתא\u0004 \u0005[\u0006ו\u0005עוקרת הלכה\u0006 למשה מסיני\u0005]?\u0006 וכן, \u0003ומאן דאמר קרא\u0004 \u0005[ומי שאומר\u0006 שהדבר נלמד מן \u0005הכתוב]?\u0006 וכי \u0003אתיא\u0004 \u0005[באה,\u0006 יכולה לבוא\u0005]\u0006 ה\u0003גזרה שוה עקרה קרא\u0004 \u0005[\u0006ו\u0005עוקרת\u0006 את \u0005הכתוב]?\u0006","\u0003אלא אמר רב אשי: רבן גמליאל ובית דינו סברי לה\u0004 \u0005[סבורים הם]\u0006 בעיקר הדין \u0003כר' ישמעאל\u0004 ש\u0003אמר\u0004 שאיסור זה \u0003הלכתא גמירי לה\u0004 \u0005[מהלכה\u0006 למשה מסיני \u0005למדוהו]\u0006 \u0003וכי גמירי הלכתא\u0004 \u0005[וכאשר למדו הלכה\u0006 זו\u0005],\u0006 הריהו רק \u0003בזמן שבית המקדש קיים,\u0004 וראיה לדבר, \u0003דומיא\u0004 \u0005[בדומה]\u0006 להלכה האחרת שנאמרה יחד עמה \u0003ניסוך המים\u0004 השייך לעבודת המקדש. \u0003אבל בזמן שאין בית המקדש קיים — לא\u0004 חלה הלכה זו, ולכן ביטלוה אחר חורבן הבית.","שנינו במשנה: \u0003אבל\u0004 אין משקים את השדות בחול המועד, \u0003לא ממי הגשמים\u0004 ולא \u0003ממי הקילון\u0004 (מים ששואבים בדליים). ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003מי קילון — איכא\u0004 \u0005[יש]\u0006 בשאיבתם \u0003טירחא יתירא\u0004 \u0005[טירחה יתירה]\u0006 ולכן אסרוה במועד, \u0003אלא מי הגשמים מאי\u0004 \u0005[מה]\u0006 \u0003טירחא איכא\u0004 \u0005[יש]\u0006 בכך? הלא הם נקווים מעצמם וצריך רק להפנותם אל העצים!","\u0003אמר ר' אילעא אמר ר' יוחנן: גזירה מי הגשמים אטו\u0004 \u0005[משום]\u0006 \u0003מי קילון. רב אשי אמר: מי גשמים גופייהו\u0004 \u0005[עצמם]\u0006 \u0003לידי מי קילון אתו\u0004 \u0005[\u0006הם \u0005באים],\u0006 שהרי לאחר זמן מה מתמעטים מי הגשמים וצריך לשאוב אותם בדלי.","ומעירים: \u0003וקמיפלגי\u0004 \u0005[והם חלוקים]\u0006 אם לקבל את דברי \u0003ר' זירא.\u0004 ש\u0003אמר ר' זירא אמר רבה בר ירמיה אמר שמואל: נהרות המושכים מים מן האגמים — מותר להשקות מהם בחולו של מועד,\u0004 משום שמים אלה זורמים תדיר ואינם פוסקים, ואילו","\u0003מר\u0004 \u0005[חכם זה,\u0006 רב אשי\u0005]\u0006 \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את דברי \u0003ר' זירא,\u0004 שהרי אסר במי גשמים רק מפני שהם פוסקים, ובמים שאינם פוסקים — אינו גוזר. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' אילעא\u0005]\u0006 \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את דברי \u0003ר' זירא,\u0004 שהרי גזר במי גשמים משום מי קילון, ולכן יגזור גם במים אחרים משום טעם זה.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של הדבר שהזכרנו, \u0003אמר ר' זירא אמר רבה בר ירמיה אמר שמואל: נהרות המושכים מים מן האגמים\u0004 — \u0003מותר להשקות מהן בחולו של מועד.\u0004","כאשר אמר רבי זירא הלכה זו \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' ירמיה לר' זירא:\u0004 הלא שנינו \u0003אבל לא ממי גשמים ולא ממי קילון! אמר ליה\u0004 \u0005[לו]\u0006 רבי זירא: \u0003ירמיה ברי\u0004 \u0005[בני],\u0006 \u0003הני\u0004 \u0005[אלה]\u0006 ה\u0003אגמים\u0004 שב\u0003בבל\u0004 — \u0003כמיא דלא פסקי דמי\u0004 \u0005[כמים שאינם פוסקים\u0006 הם \u0005נחשבים]\u0006 ואין אנו חוששים שמא יתמעטו המים ויבואו לטרוח ולשאבם בדליים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הפסיקות\u0004 (בריכות ארעיות) \u0003והבריכות שנתמלאו מים מערב יום טוב — אסור להשקות מהם בחולו של מועד.\u0004 שמא יפסקו מימיהם ויצטרך להביא מים ממקום אחר. \u0003ואם היתה אמת המים עוברת ביניהם\u0004 והמים זורמים מזו לזו — \u0003מותר.\u0004","\u0003אמר רב פפא: והוא שרובה של אותה שדה שותה מאותה אמת המים\u0004 והוא משקה איפוא את רוב השדה בבת אחת, ואין לחשוש שכאשר יפסקו מהבריכות יבואו לשאוב ממקור אחר להשקות חלקים שונים של השדה. \u0003רב אשי אמר: אף על פי שאין רובה של אותה\u0004 ה\u0003שדה שותה, כיון דקא משכא ואתיא\u0004 \u0005[שהיא,\u0006 התעלה, \u0005מושכת ובאה]\u0006 והמים מוסיפים ובאים אפילו בכמות מועטת — אותו אדם \u0003מימר אמר\u0004 \u0005[אומר\u0006 בלבו\u0005]\u0006 \u0003אי לא שתיא לחד יומא\u0004 \u0005[אם אין\u0006 היא \u0005שותה,\u0006 מושקה, \u0005ביום אחד]\u0006 — \u0003תשתי לתרי ותלתא יומי\u0004 \u0005[תשתה,\u0006 תהיה מושקה, \u0005בשנים ובשלושה ימים],\u0006 ולכן איננו בא לטרוח ולמהר להשקות את מה שלא הושקה תחילה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 שתי שדות בית השלחין, אחת מעל גבי השניה, ובעליונה נובע מעיין שמימיו ניגרים לבריכה הנמצאת בשדה התחתונה, ואותה \u0003בריכה נוטפת מים\u0004 שיורדים אליה \u0003משדה בית השלחין זו\u0004 העליונה \u0003— מותר להשקות ממנה שדה בית השלחין אחרת\u0004 המצויה למטה.","ושואלים: \u0003והא עבידא דפסקא\u0004 \u0005[והרי\u0006 הבריכה \u0005עשויה שתיפסק]\u0006 ואז יבוא לדלות מים אחרים ולהשקות! \u0003אמר ר' ירמיה:\u0004 ש\u0003עדיין היא\u0004 השדה העליונה \u0003מטפטפת\u0004 לבריכה, שאין המים פוסקים. \u0003אמר אביי: והוא שלא פסק מעיין ראשון\u0004 המשקה את שדה בית השלחין הגבוה ועדיין הוא ממלא את הבריכה, ואפשר אם כן לסמוך על כך ולהשקות את בית השלחין הנמוך.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' שמעון בן מנסיא אומר: שתי ערוגות\u0004 שהיו \u0003זו למעלה מזו — לא ידלה\u0004 (ישאב מים באמצעות דליים) \u0003מן התחתונה וישקה את העליונה\u0004 משום טירחה. \u0003יותר על כן אמר ר' אלעזר בר שמעון: אפילו ערוגה אחת\u0004 ש\u0003חציה נמוך וחציה גבוה — לא ידלה ממקום נמוך וישקה למקום גבוה\u0004 אף באותה ערוגה עצמה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מדלין לירקות כדי לאוכלן\u0004 בחול המועד, \u0003ואם בשביל לייפותם\u0004 שיגדלו ויתייפו יותר — \u0003אסור,\u0004 שאסור לטרוח טירחה שאינה הכרחית.","מסופר: \u0003רבינא ורבה תוספאה הוו קא אזלי באורחא\u0004 \u0005[היו מהלכים בדרך]\u0006 \u0003חזו לההוא גברא דהוה דלי דוולא בחולא דמועדא\u0004 \u0005[ראו אדם אחד שהיה דולה בדלי בחול המועד],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה תוספאה לרבינא: ליתי מר לשמתיה\u0004 \u0005[\u0006ש\u0005יבוא אדוני וינדה אותו],\u0006 שהרי הוא עובר על דברי חכמים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מדלין לירקות כדי לאוכלן,\u0004 הרי שאין עבירה בדבר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה תוספאה: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מדלין\" — מדלין מיא\u0004 \u0005[מים]\u0006 כדי להשקות ירקות? לא כן הוא, אלא \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006"],["\u0003\"מדלין\" — שלופי\u0004 \u0005[לשלוף,\u0006 לדלל\u0005]\u0006 קצת מן הירקות הגדלים בצפיפות, ופירוש הברייתא הוא, שאם מדלל ואוכל את הירקות שמוציא — מותר, אבל אסור לעשות זאת על מנת לייפות את הנשארים. \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המידל\u0004 (המדלל) \u0003בגפנים\u0004 שבכרמו, \u0003כשם שהוא מידל בשלו — כך הוא מידל בשל עניים\u0004 בגפנים שמשאיר עוללות לעניים, שכיון שעושה זאת לצורך הגפנים יכול לדלל אף במופרש לעניים, אלו \u0003דברי ר' יהודה.\u0004 ואילו \u0003ר' מאיר אומר: בשלו רשאי, ואינו רשאי בשל עניים.\u0004 ומכאן למדנו ש\"מידל\" הוא מלשון דילול, ולא לשון דליה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 מפורשת: \u0003מדלין מים לירקות כדי לאוכלן! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי תניא\u0004 \u0005[אם שנויה]\u0006 — \u0003תניא\u0004 \u0005[שנויה]\u0006 וחוזר אני איפוא מדברי.","שנינו במשנה: \u0003ואין עושים עוגיות לגפנים.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003עוגיות\u0004 אלה? \u0003אמר רב יהודה:\u0004 בארמית קוראים להם \u0003בנכי\u0004 (החפירות העגולות שחופרים סביב הגפנים). \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אלו הן עוגיות — בדידין\u0004 (חפירות עגולות) \u0003שבעיקרי זיתים\u0004 (סמוך לגזעי הזיתים) \u0003ושבעיקרי גפנים.\u0004","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]\u0006 שאסור לעשות בנכי? \u0003והא רב יהודה שרא\u0004 \u0005[התיר]\u0006 \u0003לבני בר ציתאי למעבד\u0004 \u0005[לעשות]\u0006 \u0003בנכי לכרמיהון\u0004 \u0005[לכרמיהם]\u0006 בחול המועד! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זו]\u0006 — \u0003בחדתי\u0004 \u0005[בחדשות],\u0006 שאסור לחפור עוגיה כזו כשלא היתה כלל קודם, \u0003הא\u0004 \u0005[זו]\u0006 — \u0003בעתיקי\u0004 \u0005[בישנות],\u0006 בעוגיות שהיו חפורות כבר וצריך רק לעדרן — מותר.","שנינו במשנה: \u0003ר' אלעזר בן עזריה אומר: אין עושים את האמה\u0004 בתחילה בחול המועד ובשביעית. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שבחול ה\u0003מועד\u0004 טעם האיסור הוא \u0003משום דקא טרח\u0004 \u0005[שהוא טורח]\u0006 בשל כך טירחה יתירה במועד, \u0003אלא\u0004 ב\u0003שביעית מאי טעמא\u0004 \u0005[מה הטעם]\u0006 נאסרה? הרי לא נאסר בשביעית אלא דבר העשוי לגדל צמחים.","ומשיבים: \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003ר' זירא ור' אבא בר ממל. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 הטעם הוא \u0003מפני שנראה\u0004 לאנשים \u0003כעודר\u0004 בכרמו ואינם יודעים שהוא רק חופר תעלה, וחושדים בו איפוא במלאכת שביעית. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: מפני שמכשיר אגפיה לזריעה,\u0004 שכאשר הוא מוציא את האדמה מן האמה, הריהו שופך לשני צידי התעלה אדמה חדשה ותחוחה הראויה לזריעה, ונמצא שמכשיר בשביעית אדמה לגידול צמחים.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה, אם זה או זה הטעם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 באופן \u0003דקא אתו מיא בתריה\u0004 \u0005[שבאים המים אחריו]\u0006 כשהוא חופר תעלה ורואים שהמים זורמים מיד ונכנסים אליה; \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מפני שמכשיר אגפיה לזריעה — איכא\u0004 \u0005[יש]\u0006 בכך עדיין איסור, שהרי מכל מקום מכשיר את האדמה, \u0003ומאן דאמר\u0004 \u0005[ו\u0006לדעת \u0005מי שאומר]\u0006 \u0003מפני שנראה כעודר — ליכא\u0004 \u0005[אין\u0006 כאן\u0005]\u0006 איסור, שהרי רואים שהוא חופר אמת מים.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003מפני שנראה כעודר, ליחוש\u0004 \u0005[שיחשוש]\u0006 אף הוא \u0003מפני שמכשיר אגפיה לזריעה,\u0004 וכיצד יכול הוא לבטל חשש זה לגמרי? \u0003אלא,\u0004 יש להסביר בדרך אחרת, ולומר כי \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה במקרה אחר; \u0003דקא שקיל מיניה ושדי לבראי\u0004 \u0005[שהוא לוקח ממנו\u0006 מן התעלה \u0005וזורק החוצה\u0006 למקום רחוק\u0005].\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מפני שמכשיר אגפיה לזריעה — ליכא\u0004 \u0005[אין\u0006 כאן\u0005]\u0006 מקום לאיסור, שהרי אינו מכשיר. \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מפני שנראה כעודר — איכא\u0004 \u0005[יש\u0006 כאן\u0005]\u0006 איסור, שעדיין נראה כעודר, ושואלים מצד שני אף","\u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מפני שמכשיר אגפיה לזריעה, ליחוש\u0004 \u0005[שיחשוש]\u0006 גם הוא \u0003מפני שנראה כעודר!\u0004 ומשיבים: \u0003עודר נמי\u0004 \u0005[גם כן]\u0006 \u0003כי קא שקיל\u0004 \u0005[כאשר הוא נוטל]\u0006 רגב אדמה בזמן העידור, הלא \u0003בדוכתיה מנח ליה\u0004 \u0005[במקומו\u0006 הוא \u0005מניח אותו],\u0006 וכיון שאותו אדם משליך רגבי אדמה למקום אחר רואים מיד שאינו מתכווין לעידור, אלא ודאי חופר תעלה.","ואומרים: \u0003אמימר מתני לה\u0004 \u0005[היה שונה אותה]\u0006 הלכה בנוסח שנאמר בו במפורש \u0003מפני שנראה כעודר,\u0004 ומשום כך \u0003קשיא ליה\u0004 \u0005[היה קשה לו]\u0006 מדברי \u0003ר' אלעזר בן עזריה\u0004 על דברי \u0003ר' אלעזר בן עזריה\u0004 עצמו במקום אחר. וכך הקשה: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' אלעזר בן עזריה\u0004 כי \u0003כל שנראה כעודר אסור?\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003עושה אדם את זבלו\u0004 בשנה השביעית \u0003אוצר,\u0004 שצובר את הזבל למקום אחד, ואינו חושש, שהרי אינו מזבל עכשיו. \u0003ר' מאיר אוסר, עד שיעמיק שלשה טפחים\u0004 בקרקע ויטמון שם את הזבל, כדי שלא ייראה כמזבל את שדהו בשביעית, \u0003או עד שיגביה שלשה טפחים. היה לו דבר מועט,\u0004 שכבר היתה כמות זבל מעטה באותו מקום מערב שביעית — \u0003מוסיף עליו והולך\u0004 ואינו חושש.","\u0003ר' אלעזר בן עזריה אוסר\u0004 בכל מקרה \u0003עד שיעמיק שלשה או עד שיגביה שלשה, או עד שיתן\u0004 את הזבל \u0003על הסלע\u0004 שאינו מקום העשוי להצמיח. מכל מקום נראה שלדעת ר' אלעזר בן עזריה רשאי לחפור כדי להעמיק ולהטמין את הזבל אף על פי שהוא נראה כעודר!","\u0003ר' זירא ור' אבא בר ממל\u0004 תירצו את הקושי; \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר,\u0004 שכאן מדובר \u0003כגון שהעמיק\u0004 באדמה והכין מקום לזבל עוד קודם שנת השביעית. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: זיבלו מוכיח עליו,\u0004 שכיון שמצוי זבל במקום, הרי זה מוכיח שהוא מתכוון רק להטמינו ולא לעידור.","שנינו במשנה ש\u0003מתקנין את\u0004 האמה \u0003המקולקלת במועד.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מקולקלת? אמר ר' אבא: שאם היתה\u0004 כעת \u0003עמוקה טפח\u0004 מפני שנתמלאה בטין — חופר \u0003ומעמידה על ששה טפחים.\u0004 על בסיס הלכה זו באים לברר כמה בעיות מעשיות.","ותחילה מקדימים; \u0003פשיטא\u0004 \u0005[פשוט]\u0006 לנו, שאם היתה התעלה עמוקה \u0003חצי טפח\u0004 ובא להעמיקה ל\u0003שלשה טפחים, כיון דלא עבר מיא\u0004 \u0005[שאין עוברים מים]\u0006 במידה מספקת בשלושה טפחים — \u0003לא כלום הוא\u0004 ובודאי אסור לטרוח במלאכה שאינה מועילה. וכן אם היו שם \u0003טפחיים\u0004 (שני טפחים) והוא רוצה להעמיקה שתעמוד \u0003על שנים עשר\u0004 טפחים — גם זה \u0003לא\u0004 הותר משום \u0003דקא טרח\u0004 \u0005[שהוא טורח]\u0006 \u0003טירחא יתירא,\u0004 אף על פי שיש כאן אותו יחס של אחד על שש.","השאלה היא איפוא, אם היה עומקה \u0003טפחיים\u0004 ורוצה להעמידם \u0003על שבעה מהו?\u0004 וצדדי הבעיה: \u0003הכא\u0004 \u0005[כאן]\u0006 במקום שהתירו לו להעמיק מטפח לשישה, \u0003חמשה\u0004 טפחים \u0003קא\u0004 \u0005[הוא]\u0006 ש\u0003מעמיק, והכא\u0004 \u0005[וכאן]\u0006 מטפחיים לשבעה, גם כן \u0003חמשה\u0004 טפחים \u0003קא\u0004 \u0005[הוא]\u0006 ש\u0003מעמיק\u0004 ומותר, \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר: \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003טפח יתירא\u0004 \u0005[יתר]\u0006 של חפירה בעומק — \u0003איכא\u0004 \u0005[יש]\u0006 \u0003טירחא טפי\u0004 \u0005[יתירה]\u0006 להתכופף כדי לחפור עמוק כל כך, ויש אולי לאסור? שאלה זו לא נפתרה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","בעניינים דומים מסופר, כי \u0003אביי שרא\u0004 \u0005[התיר]\u0006 \u0003לבני\u0004 המקום \u0003בר המדך לשחופי נהרא\u0004 \u0005[להוציא את ענפי האילנות מהנהר]\u0006 בחול המועד. \u0003ר' ירמיה שרא להו\u0004 \u0005[התיר להם]\u0006 \u0003לבני\u0004 המקום \u0003סכותא למיכרא נהרא טמימא\u0004 \u0005[לכרות\u0006 מחדש \u0005נהר שנסתם אפיקו].\u0006 \u0003רב אשי שרא להו\u0004 \u0005[התיר להם]\u0006 \u0003לבני מתא מחסיא\u0004 עירו \u0003לאקדוחי\u0004 \u0005[לקדוח]\u0006 ולהוציא את השרטונות שב\u0003נהר בורניץ\u0004 הסמוך. \u0003אמר: כיון דשתו מיניה\u0004 \u0005[ששותים ממנו]\u0006 \u0003רבים,\u0004 אם כן \u0003כ\u0004צורך \u0003רבים דמי\u0004 \u0005[נחשב],\u0006 \u0003ותנן\u0004 \u0005[ו\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003עושים כל צורכי רבים\u0004 בחול המועד.","שנינו במשנה, שבחול המועד \u0003מתקנין את\u0004"],["\u0003קילקולי המים שברשות הרבים\u0004 וחוטטים אותם. מלשון המשנה נדייק: \u0003חטיטה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 הותרה, שמותר להוציא את האבנים והעפר שנפלו לבורות המים, אולם \u0003חפירה\u0004 לכתחילה של בור — \u0003לא.\u0004","\u0003אמר ר' יעקב אמר ר' יוחנן: לא שנו\u0004 שאסור לחפור בורות חדשים \u0003אלא\u0004 כ\u0003שאין\u0004 ה\u0003רבים צריכין להם, אבל\u0004 אם ה\u0003רבים צריכין להם — אפילו חפירה מותר.\u0004","ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003רבים צריכין להם מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חוטטין בורות, שיחין\u0004 (בורות מאורכים) \u0003ומערות\u0004 (בורות מכוסים בתיקרה) \u0003של יחיד, ואין צריך לומר\u0004 שחוטטים \u0003של רבים, ואין חופרין בורות שיחין ומערות של רבים, ואין צריך לומר של יחיד. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה, כשאסרו של רבים, \u0003בשרבים צריכין להם\u0004 ואף על פי כן אסרו?!","ודוחים: \u0003לא,\u0004 מדובר \u0003בשאין רבים צריכין להם.\u0004","ומקשים: \u0003דכוותה\u0004 \u0005[כיוצא בזה]\u0006 ל\u0003גבי\u0004 בור של \u0003יחיד,\u0004 יש איפוא לפרש שמדובר שחוטטים בורות של יחיד גם כאשר \u0003אין יחיד צריך להם,\u0004 אולם במקרה כזה \u0003חטיטה מי שרי\u0004 \u0005[האם מותרת]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בורות שיחין ומערות של יחיד כונסין מים לתוכן אבל לא חוטטין ולא שפין\u0004 (מושחים בטיח) \u0003את סדקיהן, ושל רבים — חוטטין אותן ושפין את סדקיהן.\u0004 משמע שבורות של יחיד שאין היחיד צריך להם אסור אפילו לחטוט!","קושיה זו דוחים: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 כיצד תפרש את הברייתא — \u0003בשיחיד צריך להם,\u0004 אם כן \u0003דכוותה\u0004 \u0005[כיוצא בזה]\u0006 מה שאמרו בברייתא \u0003גבי רבים,\u0004 יש לפרש גם כן \u0003בשרבים צריכין להם,\u0004 אולם אז \u0003חפירה מי אסיר\u0004 \u0005[האם אסורה]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת: \u0003בורות שיחין ומערות של יחיד כונסין מים לתוכן וחוטטין אותן, אבל לא שפין את סדקיהן, ולא חוטטין לתוכן\u0004 אדמה למלא אותם, \u0003ולא סדין אותן בסיד\u0004 כדי שלא יספגו מים. \u0003ושל רבים — חופרין אותן, וסדין אותן בסיד!\u0004","אומרים אם כן, \u0003אלא קשיא הך קמייתא\u0004 \u0005[קשה זו\u0006 הברייתא \u0005הראשונה]\u0006 ששנינו בה שאין חופרים בורות של רבים! ומסבירים: \u0003תריץ הכי\u0004 \u0005[תרץ,\u0006 ישב, \u0005כך]:\u0006 \u0003חוטטין בורות של יחיד בשיחיד צריך להם, ואין צריך לומר בשל רבים כשרבים צריכין להם,\u0004 שאז \u0003אפילו חפירה מותר.\u0004","\u0003ואין חופרין בורות שיחין ומערות של רבים בשאין רבים צריכין להם, ואין צריך לומר של יחיד, דכי\u0004 \u0005[שכאשר]\u0006 \u0003אין יחיד צריך להם\u0004 במועד — \u0003אפילו חטיטה נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור.\u0004 ובאופן זה יתיישבו כל המקורות בלא סתירה.","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כהסבר זה, שכשרבים צריכים לבורות, מותרת חפירתם בחול המועד, \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]:\u0006 \u0003עושין כל צורכי רבים, \"כל\" לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 שלא נתפרט — \u0003לאו לאתויי\u0004 \u0005[\u0006האם \u0005לא להביא]\u0006 \u0003חפירה\u0004 של בורות שמותרת?","ראיה זו דוחים: \u0003לא, לאתויי הא דתניא\u0004 \u0005[להביא\u0006 את \u0005זו ששנויה\u0006 בברייתא\u0005]\u0006 בענין זה, שבחול המועד \u0003יוצאין לקווץ\u0004 (להוציא את הקוצים) מן \u0003הדרכים, ולתקן את הרחובות\u0004 שבעיר, \u0003ואת האסטרטאות\u0004 (רחובות ראשיים) \u0003ולמוד\u0004 (למדוד) \u0003את המקואות\u0004 אם יש בהם מים כשיעור, \u0003וכל מקוה שאין בו ארבעים סאה\u0004 (שהוא השיעור הראוי לטהרה) \u0003מרגילין\u0004 (מושכים) \u0003לתוכו\u0004 (לא על ידי שאיבה הפוסלת, אלא על ידי משיכה שאינה פוסלת) \u0003ארבעים סאה\u0004 מים.","\u0003ומנין שאם לא יצאו\u0004 בית דין \u0003ועשו כל אלו, שכל דמים שנשפכו שם\u0004 בשל מכשולים אלה \u0003מעלה עליהם\u0004 (מחשיב להם) \u0003הכתוב כאילו הם שפכום — תלמוד לומר,\u0004 ממה שאמר הכתוב בענין ערי מקלט: \u0003\"\u0004ולא ישפך דם נקי בקרב ארצך אשר ה' אלהיך נותן לך נחלה \u0003והיה עליך דמים\"\u0004 (דברים יט, י).","ומשיבים: \u0003הא בהדיא קתני\u0004 \u0005[\u0006ענין \u0005זה בפירוש שנינו]\u0006 שהרי אומרת המשנה במפורש: \u0003ומתקנים את הדרכים ואת הרחובות ואת המקואות,\u0004 ואם כן התוספת \u0003\"ועושין כל צורכי רבים\" לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה] —\u0006 \u0003לאו לאתויי\u0004 \u0005[האם לא להביא]\u0006 \u0003חפירה\u0004 של בורות הצריכים לרבים? ומסכמים, אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך פירוש המשנה.","שנינו במשנה ש\u0003מציינין את הקברות\u0004 בחול המועד. כלומר, עושים עליהם סימן כדי שלא יטמאו בהם אנשים הנזהרים מטומאה. \u0003אמר ר' שמעון בן פזי: רמז לציון הקברות מן התורה\u0004 (הכתוב) \u0003מנין — תלמוד לומר: \"וראה עצם אדם ובנה אצלו ציון\"\u0004 (יחזקאל לט, טו), שהנביא מתנבא, שלעתיד לבוא יעשו ישראל ציונים (סימנים) על עצמות המתים המושלכים, כדי שלא יטמאו בהם אנשים הנזהרים מטומאה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: הא מקמי דליתי\u0004 \u0005[\u0006דבר \u0005זה לפני שבא]\u0006 \u0003יחזקאל\u0004 הנביא ורמז לחיוב זה, \u0003מאן\u0004 \u0005[מי]\u0006 \u0003אמר\u0004 וכיצד ידעו שצריך לעשות כן? והלא גם לפניו היו נזהרים מטומאה? השיב לו רב אשי: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה חושב שיחזקאל חידש זאת, \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב חסדא: דבר זה\u0004 שערלים ומומרים אסורים לעבוד במקדש, \u0003מתורת משה רבינו לא למדנו,\u0004 אלא \u0003מדברי יחזקאל בן בוזי\u0004 הנביא \u0003למדנו,\u0004 שנאמר בהם: \u0003\"כל בן נכר ערל לב וערל בשר לא יבוא אל מקדשי לשרתני\"\u0004 (יחזקאל מד, ט), וגם על זה יש לשאול:","\u0003מקמי דליתי\u0004 \u0005[לפני שבא]\u0006 \u0003יחזקאל, מאן\u0004 \u0005[מי]\u0006 \u0003אמר\u0004 איסור זה? \u0003אלא\u0004 על כרחך יהא עליך לומר כי \u0003גמרא גמירי לה\u0004 \u0005[במסורת למדו אותה]\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003יחזקאל ואסמכה אקרא\u0004 \u0005[והסמיכה על הכתוב]\u0006 אף שהיא הלכה מקובלת מדורות, \u0003הכא נמי גמרא גמירי לה\u0004 \u0005[כאן גם כן במסורת למדנו אותה],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003יחזקאל ואסמכה אקרא\u0004 \u0005[והסמיכה על הכתוב].\u0006","\u0003ר' אבהו אמר: מהכא\u0004 \u0005[מכאן]\u0006 יש רמז לציון קברות, שנאמר במצורע: \u0003\"וטמא טמא יקרא\"\u0004 (ויקרא יג, מה), וכוונתו: \u0003טומאה קוראה לו ואומרת לו \"פרוש\".\u0004 שהטמא צריך להודיע לרבים שטמא הוא ויפרשו ממנו, וכן עושים גם בקבר שצריך להודיע טומאתו. \u0003וכן אמר ר' עוזיאל בר בריה\u0004 \u0005[בן בנו]\u0006 של \u0003ר' עוזיאל רבה\u0004 \u0005[הגדול]:\u0006 \u0003טומאה קוראה לו ואומרת לו \"פרוש\".\u0004","ושואלים: \u0003והאי להכי הוא דאתא\u0004 \u0005[ו\u0006פסוק \u0005זה ל\u0006צורך \u0005זה הוא שבא]?\u0006 הלא הפסוק \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[הוצרך לו לכפי ששנינו\u0006 בברייתא\u0005]\u0006 בענין אחר: \u0003\"וטמא טמא יקרא\"\u0004 כוונתו: ש\u0003צריך\u0004 המצורע \u0003להודיע צערו לרבים,\u0004 שחולה הוא \u0003ו\u0004אז \u0003רבים מבקשים עליו רחמים!\u0004","ומשיבים: \u0003אם כן,\u0004 אם בא כתוב זה ללמד רק דבר אחד \u0003ליכתוב\u0004 \u0005[שיכתוב]\u0006 המקרא אם כן רק \u0003\"וטמא יקרא\", מאי\u0004 \u0005[מה]\u0006 למדנו מן ההכפלה \u0003\"וטמא טמא\" — שמעת מינה תרתי\u0004 \u0005[לומד אתה ממנה שני\u0006 דברים\u0005],\u0006 הן לענין הודעת צערו לרבים, והן שצריך להזהיר את הרבים מלהיטמא לו.","\u0003אביי אמר:\u0004 רמז לציון קברות \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"ולפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד). \u0003רב פפא אמר,\u0004 הרמז הוא ממה שנאמר: \u0003\"ואמר סלו סלו פנו דרך\"\u0004 (ישעיהו נז, יד), שיש לפנות הדרך מכל מפגע,","\u0003רב חיננא אמר:\u0004 מסופו של אותו פסוק נלמד הדבר, שנאמר \u0003\"הרימו מכשול מדרך עמי\"\u0004 (ישעיהו נז, יד). \u0003ר' יהושע בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר:\u0004 דבר זה נלמד ממה שנאמר: \u0003\"והודעת להם את הדרך ילכו בה\"\u0004 (שמות יח, כ), לומר שיש לתקן את הדרכים כיאות ובכלל זה ציון הקברות.","\u0003מר זוטרא אמר\u0004 שלמדו זאת ממה שנאמר: \u0003\"והזרתם את בני ישראל מטמאתם\"\u0004 (ויקרא טו, לא), משמע שיש להרחיק את האנשים מן הטומאה. \u0003רב אשי אמר,\u0004 דבר זה נלמד ממה שנאמר: \u0003\"ושמרתם את משמרתי\"\u0004 (ויקרא יח, ל), שמשמעו: \u0003עשו משמרת למשמרתי,\u0004 שיש לעשות סייג ומשמרת לתורה ובכלל משמרת זו גם הרחקת אוכלי תרומה (שנאמר בהם: \"ואני נתתי לך את משמרת תרומותי. במדבר יח, ח) מן הטומאה על ידי ציון הקברות.","\u0003רבינא אמר\u0004 מן הכתוב: \u0003\"ושם דרך אראנו בישע אלהים\"\u0004 (תהלים נ, כג), לומר שיש לציין את הדרכים הראויות להליכה, ובכלל זה הנקיות מן הטומאה.","על פסוק זה \u0003אמר ר' יהושע בן לוי: כל השם\u0004 (מעריך) \u0003אורחותיו\u0004 וחושב כיצד לעשות דברים בצורה הראויה והכשירה — \u0003זוכה ורואה בישועתו של הקדוש ברוך הוא, שנאמר: \"ושם דרך\", אל תקרי \"ושם\" אלא \"ושם\u0004 (בשין ימנית, מלשון שומא, הערכה) \u0003דרך\",\u0004 אותו אדם \u0003\"אראנו בישע אלהים\".\u0004","\u0003ר' ינאי הוה ליה ההוא תלמידא דכל יומא הוה מקשי ליה\u0004 \u0005[היה לו תלמיד אחד שבכל יום היה מקשה לו]\u0006 קושיות בזמן הלימוד, \u0003בשבתא דריגלא לא הוה מקשי ליה\u0004 \u0005[בשבת הרגל\u0006 שבא ציבור רחב לשמוע את הדרשה \u0005לא היה מקשה לו]\u0006 שמא לפי שעה לא ימצא תשובה ויהיה נבוך,"],["\u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 מקרא זה: \u0003\"ושם דרך אראנו בישע אלהים\"\u0004 (תהלים נ, כג), שחישב אורחותיו, מתי אין ראוי לשאול.","בדין של ציון קברות \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מציינין לא על\u0004 מקום שיש בו רק \u0003כזית מן המת, ולא על עצם\u0004 בשיעור \u0003כשעורה\u0004 מן המת, \u0003ולא על כל דבר\u0004 אחר מן המת \u0003שאינו מטמא באהל\u0004 (כאשר מאהילים עליו) אלא במגע בלבד. שכיון שאין בהם טומאת אוהל, וקבורים באדמה, אין חשש שמשהו יטמא בגללם. \u0003אבל מציינין על השדרה\u0004 של מת, \u0003ועל הגולגולת, ועל רוב בנין\u0004 על עצמות גדולות, שהן רוב גובהו של הגוף, \u0003ועל רוב מנין\u0004 של עצמות \u0003המת\u0004 (ממאה עשרים וחמש עצמות ומעלה, מתוך מאתיים ארבעים ושמונה שבגוף).","\u0003ואין מציינין על הוודאות\u0004 על מקומות שהכל יודעים שהם מקומות טומאה, \u0003אבל מציינין על הספיקות. ואלו הן הספיקות: סככות ופרעות ובית הפרס\u0004 כאשר יבואר להלן. \u0003ואין מעמידין ציון במקום\u0004 ה\u0003טומאה\u0004 בדיוק, כדי \u0003שלא\u0004 לגרום \u0003להפסיד את הטהרות,\u0004 שמא יבוא אדם נושא טהרות ולא ישים לב ועד שישים לב שהמקום מצויין כמקום טומאה כבר יטמאו הטהרות. \u0003ו\u0004כן \u0003אין מרחיקין ציון\u0004 הרבה \u0003ממקום טומאה,\u0004 כדי \u0003שלא להפסיד את ארץ ישראל,\u0004 שלא להרבות שטח שנזהרים בו, אף שאיננו טמא. עד כאן לשון הברייתא. ומעתה מבררים את כל הפרטים שבה.","ושואלים: \u0003ו\u0004כי \u0003כזית מן המת אינו מטמא באהל? והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אלו שמטמאין באהל\u0004 ובתוך רשימה זו מנינו גם \u0003כזית מן המת!\u0004","\u0003אמר רב פפא: הכא\u0004 \u0005[כאן]\u0006 בברייתא בענין הציון \u0003בכזית מצומצם\u0004 (בדיוק) \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003דסוף סוף מיחסר חסר\u0004 \u0005[שבסופו\u0006 של דבר הלא \u0005יחסר]\u0006 כאשר ירקב, ולכן \u0003מוטב\u0004 שלא יציינו את מקומו, אף אם בשל כך \u0003ישרפו עליו תרומה וקדשים לפי שעה\u0004 אם יתקל בו אדם כשעדיין לא נחסר, וייטמא, וישרפו בגללו תרומה וקדשים שנטמאו, \u0003ואל ישרפו עליו לעולם\u0004 לחינם, שהרי כעבור זמן מסויים יתמעט הבשר מכזית, ושוב איננו מטמא באהל, ואם יהא שם ציון קבוע, יחשבו שיש שם טומאת אהל ויוסיפו לשרוף עליו תרומה וקדשים לעולם.","שנינו בברייתא, \u0003ואלו הן הספיקות: סככות ופרעות!\u0004","ומסבירים, \u0003סככות\u0004 — כגון \u0003אילן המיסך\u0004 (סוכך) \u0003על הארץ\u0004 סמוך לבית הקברות, ותחת אחד מענפיו טומאת מת, ואין יודעים תחת איזה מן הענפים, וכיון שידוע שהוא מיסך על הטומאה, הרי כל ענפיו יוצרים אהל מחמת הספק, ולכן כל שתחת האילן נטמא.","\u0003פרעות\u0004 — הם \u0003אבנים פרועות היוצאות מן הגדר\u0004 ואינן עומדות במישרין עם הכותל ואם יש טומאת מת תחתיהן הרי הן מאהילות עליה, ויוצרות אהל שלא הכל שמים לב אליו.","\u0003בית הפרס — כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003החורש את ה\u0004שדה שהיה בה \u0003קבר,\u0004 שיש לחשוש שפיזר את העצמות שבקבר בכל המקום שחרש — \u0003הרי הוא עושה\u0004 על ידי כך \u0003בית הפרס, וכמה הוא עושה — מלא מענה\u0004 (מלוא אורך תלם) אחד, שהוא \u0003מאה אמה.\u0004","ושואלים: \u0003ובית הפרס מי\u0004 \u0005[האם]\u0006 \u0003מטמא באהל? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר שמואל: מנפח אדם בית הפרס והולך,\u0004 שאם אדם נושא טהרות או רוצה להישמר בטהרה כדי לאכול קדשים וצריך לעבור דרך בית הפרס, יכול הוא ללכת, ולנפוח בפיו באבק השדה ולראות אם הוא מגלה בתוך העפר עצם הראויה לטמא שלא יגע בה. ומכאן מובן שאין לחשוש לטומאת אהל בבית הפרס, שכן אם חוששים לטומאת אהל יש לחשוש שמא תוך כדי פעולת הניפוח כבר נטמא.","\u0003ו\u0004כיוצא בו \u0003רב יהודה בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא אמר: בית הפרס שנידש\u0004 שכבר הלכו בו אנשים ודשו אותו ברגליהם — \u0003טהור,\u0004 שודאי סילקו ברגליהם את העצמות משם. ואם אומרים כי בית הפרס מטמא באהל הרי יש לחשוש שהעצמות נדושו ונכנסו פנימה!","\u0003אמר רב פפא: לא קשיא\u0004 \u0005[אין זה קשה]\u0006 כי יש מקומות שונים הקרויים בית הפרס, ויש לחלק; \u0003כאן\u0004 שאמרנו שמציינים בית הפרס בגלל טומאת אוהל מדובר \u0003בשדה שאבד בה קבר,\u0004 שאנו יודעים שבמקום כלשהו בשדה זה היה קבר, אלא ששכחו היכן היה, ויש כאן טומאת אהל וודאית, \u0003כאן\u0004 שהתירו בניפוח, מדובר \u0003בשדה שנחרש בה קבר,\u0004 שלא ברור שיש אכן עצמות מת במקום זה.","ושואלים: \u0003ושדה שנחרש בה קבר, בית הפרס קרי ליה\u0004 \u0005[קוראים לו],\u0006 וחוששים לטומאתו? ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 \u0003והתנן\u0004 \u0005[ואכן\u0006 כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שלשה\u0004 סוגי \u0003בית הפרס הן\u0004 ובהם אסורים אוכלי תרומה וקדשים מלהלך: \u0003שדה שנאבד בה קבר\u0004 ואין מקומו ידוע, \u0003שדה שנחרש בה קבר\u0004 ויש לחשוש שהעצמות התפזרו בכל השדה, \u0003ושדה בוכין.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שדה בוכין\"? רב יהושע בר אבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא אמר: שדה שמפטירין בה מתים,\u0004 שכאשר היו מביאים מת ממקום אחר, שם היו נפטרים אלו שהביאוהו ממקומו ומוסרים אותו לבני המקום לקוברו.","\u0003וטעמא מאי\u0004 \u0005[ומה הטעם]\u0006 שאנחנו חוששים לטומאה במקום זה, \u0003אמר אבימי: משום יאוש בעלים נגעו בה.\u0004 שיש לחשוש שמא תוך כדי טילטול המת ממקום רחוק נפל אבר ממנו בשדה ולא שמו האנשים לב לכך ונתייאשו. ובמשך הזמן יש לחשוש בשדה כזה שהיו בו מתים רבים, שיש בו טומאה במקומות רבים.","ושואלים: \u0003ושדה שנחרש בה קבר לא בעי\u0004 \u0005[צריך]\u0006 \u0003ציון? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצא שדה מצויינת,\u0004 כלומר, שדה שיש עליה כבר ציון של טומאה \u0003ואין ידוע מה טיבה,\u0004 שכבר נשתכח מה טומאה היתה שם, אם \u0003יש בה אילנות\u0004 באותה שדה — \u0003בידוע שנחרש בה קבר,\u0004 שבשדה שנחרש בו קבר מותר לנטוע. \u0003אין בה אילנות\u0004 ואין לחשוש לחרישה — \u0003בידוע שאבד בה קבר.\u0004 שבשדה כזה אסור לנטוע עצים, ואם המקום ראוי לכך ולא נטעו בו — ודאי שזה משום קבר שאבד בו (רמב\"ם).","\u0003ר' יהודה אומר:\u0004 אין סומכים על סימנים אלה \u0003עד שיהא שם\u0004 באותו מקום \u0003זקן\u0004 (חכם) \u0003או תלמיד\u0004 חכם, \u0003לפי שאין הכל בקיאין בדבר,\u0004 ושמא לא נחרש השדה כלל. ומכל מקום מדברי ברייתא זו יוצא שאף שדה שנחרש בה קבר מציינים!","ומשיבים: \u0003אמר רב פפא: כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 לגבי שדה מצויינת, מדובר בה \u0003בשדה שאבד בה קבר\u0004 ודאי \u0003דציינוה\u0004 \u0005[שציינו אותו]\u0006 מיד לאחר מכן, אולם אם \u0003יש בה אילנות בידוע שנחרש בה\u0004 ה\u0003קבר,\u0004 ששכחו ואף חרשו שדה זה לצורך האילנות שלא כדין, \u0003אין בה אילנות — בידוע שאבד בה קבר\u0004 ולא נחרש.","לעצם הלכה זו שואלים: \u0003וליחוש דלמא אילנות מגואי וקבר מבראי\u0004 \u0005[ונחשוש שמא\u0006 היו \u0005האילנות מבפנים והקבר\u0006 היה \u0005מבחוץ]\u0006 ומקום הקבר עצמו לא נחרש כלל אלא אבד, ואיך אפשר לסמוך על כך ולומר שמן הסתם כבר נחרש הקבר?","ומשיבים: \u0003כ\u0004פי ש\u0003אמר עולא\u0004 בענין דומה, שמדובר \u0003ב\u0004ש\u0003עומדין\u0004 האילנות \u0003על הגבולין\u0004 ליד רשות הרבים, שודאי לא היה קבר מבחוץ ברשות הרבים אלא בין האילנות, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003ב\u0004ש\u0003עומדין על הגבולין.\u0004"],["\u0003ודלמא\u0004 \u0005[ושמא]\u0006 היתה ה\u0003טומאה מגואי\u0004 \u0005[מבפנים]\u0006 \u0003ו\u0004ה\u0003אילנות\u0004 היו \u0003מבראי\u0004 \u0005[מבחוץ]\u0006 ובין האילנות נחרש, אבל מקום הקבר שאבד היה מעבר לאילנות, בתוך השדה?","ומשיבים: מדובר פה \u0003במסובכין,\u0004 שהיו האילנות מצויים בכמה מקומות בשדה, ואם חרשו — מן הסתם חרשו את כל השדה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 טעם אחר: \u0003הא אמרן\u0004 \u0005[הרי אמרנו]\u0006 ש\u0003אין מרחיקין\u0004 את ה\u0003ציון ממקום\u0004 ה\u0003טומאה\u0004 כדי \u0003שלא להפסיד את ארץ ישראל,\u0004 וכיון שיש ציון ליד האילנות — מן הסתם האילנות היו סמוכים למקום הקבר ולא רחוקים ממנו.","שנינו באותה ברייתא ש\u0003ר' יהודה אומר\u0004 שאין לסמוך על סימנים כדי לקבוע את השדה כבית הפרס \u0003עד שיהא שם זקן או תלמיד\u0004 (חכם), \u0003לפי שאין הכל בקיאין בדבר,\u0004 ויתכן שלא נחרש השדה כלל. \u0003אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 מדברי ר' יהודה ש\u0003צורבא מרבנן דאיכא במתא\u0004 \u0005[תלמיד חכם שישנו בעיר]\u0006 — \u0003כל מילי דמתא עליה רמיא\u0004 \u0005[ענייני העיר מוטלים עליו],\u0006 שהרי סומכים עליו ושואלים אותו ואין אומרים שאינו יודע מה שמתרחש בעיר.","ועוד בדין ציון קברות, \u0003אמר רב יהודה: מצא אבן\u0004 אחת \u0003מצויינת\u0004 — הרי זה סימן ש\u0003תחתיה טמא.\u0004 מצא \u0003שתים\u0004 מצויינות, \u0003אם יש סיד\u0004 על הקרקע ש\u0003ביניהן,\u0004 סימן הוא שהמקום ש\u0003ביניהן טמא\u0004 ושתי האבנים הם הצדדים הקיצוניים של אותו סימון, \u0003ואם אין סיד ביניהן — ביניהן טהור\u0004 וכל אחת מן האבנים היא ציון טומאה לעצמו.","ושואלים: \u0003ואף על גב דליכא\u0004 \u0005[ואף על פי שאין]\u0006 סימן שהיה \u0003חורש\u0004 באמצע, גם יהיה מה שביניהן טהור? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצא אבן אחת מצויינת\u0004 — יש להניח כי \u0003תחתיה טמא.\u0004 מצא \u0003שתים\u0004 מצויינות, \u0003אם יש\u0004 סימן שהיה \u0003חורש ביניהן — ביניהן טהור, ואם לאו\u0004 \u0005[לא] —\u0006 \u0003ביניהן טמא!\u0004","\u0003אמר רב פפא:\u0004 יש לפרש \u0003הכא\u0004 \u0005[כאן]\u0006 בברייתא מדובר \u0003כשהסיד\u0004 שהוא סימן הטומאה \u0003שפוך על ראשיהן\u0004 של האבנים \u0003ומרודה\u0004 (ונוטה) \u0003לכאן ולכאן,\u0004 ואז: \u0003אי איכא\u0004 \u0005[אם יש]\u0006 \u0003חורש ביניהן\u0004 אנחנו אומרים ש\u0003ביניהן טהור, דאימור\u0004 \u0005[שאמור,\u0006 נניח\u0005]\u0006 ש\u0003מחמת חורש הוא דאיקפל\u0004 \u0005[שנקלף\u0006 הסיד\u0005]\u0006 ומתחילה היה הסיד רק על ראשי האבנים ורק תחתיהן היתה הטומאה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שאין חורש, מן הסתם ה\u0003סיד דביני ביני\u0004 \u0005[שבין]\u0006 האבנים \u0003הוא\u0004 זה והניחוהו כך לומר שכל המקום שבאמצע \u0003טמא.\u0004","\u0003אמר ר' אסי\u0004 אם היה \u0003מצר\u0004 (גבול) \u0003אחד\u0004 של השדה \u0003מצוין\u0004 — יש ללמוד מכאן ש\u0003הוא,\u0004 המצר עצמו, \u0003טמא, וכל השדה כולה טהורה. שנים\u0004 מסומנים — \u0003הם טמאין וכל השדה כולה טהורה. שלשה — הם טמאין וכל השדה כולה טהורה. ארבעה\u0004 מצרי השדה מכל צד מסומנים — \u0003הן טהורין,\u0004 שאין מציינים על מקום הטומאה עצמו, \u0003וכל השדה כולה\u0004 שבאמצע \u0003טמאה.\u0004","ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אין מרחיקין ציון ממקום טומאה שלא להפסיד את ארץ ישראל\u0004 ולכן ציינו את כל המיצרים לדעת שהשדה שביניהם כולו טמא.","שנינו במשנה ש\u0003יוצאין\u0004 בחול המועד \u0003אף על הכלאים,\u0004 לעקור את שתילי הכלאים שצמחו בין הזרעים במשך תקופת הגשמים.","ושואלים: \u0003ו\u0004על ה\u0003כלאים בחולו של מועד נפקינן\u0004 \u0005[יוצאים אנו]?\u0006 \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003באחד באדר משמיעין\u0004 מודיעים לכול \u0003על השקלים,\u0004 שיש לתרום שקלים למקדש, \u0003ו\u0004כן מודיעים \u0003על הכלאים\u0004 שיש לעקור מן השדה,","ו\u0003בחמשה עשר בו\u0004 באדר \u0003קורין את המגילה בכרכים\u0004 (ערים מוקפות חומה) \u0003ויוצאין לקווץ\u0004 (להוציא את הקוצים) מן \u0003הדרכים, ולתקן הרחובות, ולמוד המקואות. ועושין כל צרכי רבים, ומציינין את הקברות\u0004 בסיד כסימן טומאה, \u0003ויוצאין על הכלאים.\u0004 ואם כבר באדר יוצאים על הכלאים, מדוע יוצאים בחול המועד?","נחלקו בכך \u0003ר' אלעזר ור' יוסי בר חנינא; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: כאן\u0004 שאמרו שיוצאים בחמישה עשר באדר, הרי זה \u0003בבכיר,\u0004 בצמחים המקדימים לצמוח, ומה ששנינו במשנה \u0003כאן\u0004 שיוצאים בחול המועד, הרי זה \u0003באפיל,\u0004 בגידול המאוחר שאינו ניכר עד חול המועד פסח. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כאן\u0004 שאמרו שיוצאים בחמישה עשר באדר, הרי זה \u0003בזרעים\u0004 כגון תבואה שנזרעה עוד בחורף ובאדר היא גדולה, \u0003כאן\u0004 במשנתנו ששנינו שמאחרים, הרי זה \u0003בירקות\u0004 שצומחים מאוחר יותר.","\u0003אמר ר' אסי אמר ר' יוחנן: לא שנו\u0004 שיוצאים על הכלאים רק בחודש אדר \u0003אלא\u0004 כ\u0003שאין ניצן\u0004 (הפרח שלהם) \u0003ניכר\u0004 ועדיין לא ניתן להכיר את מין הצמח, ולא ברור אם כלאים הוא, \u0003אבל\u0004 אם ה\u0003ניצן ניכר\u0004 עוד קודם לכן — \u0003יוצאין עליהן\u0004 קודם.","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה,\u0006 מדוע דווקא\u0005]\u0006 \u0003בחולו של מועד דנפקינן\u0004 \u0005[שאנו יוצאים]\u0006 על הכלאים? \u0003אמר ר' יעקב אמר ר' יוחנן: משום שכר פעולה\u0004 (עבודה) של הפועלים ששוכר בית דין לעקור את הכלאים \u0003דמוזלי גבן\u0004 \u0005[שהם מוזילים לנו,\u0006 לבית הדין\u0005],\u0006 שהרי בחול המועד אסורים הפועלים בשאר מלאכות, ואם שוכרים אותם לעבודה המותרת שהיא צורך הציבור, הם מבקשים עליה שכר פחות, שהרי אין מלאכה אחרת מצויה להם אז.","\u0003אמר רב זביד ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב משרשיא:\u0004 מתוך הנחה זו שבחול המועד שכר הפועלים זול יותר ולכך שוכרים אותם אז, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003כי יהבינן להו\u0004 \u0005[כאשר נותנים אנו להם]\u0006 \u0003שכר\u0004 לפועלים המוציאים את הכלאים — \u0003מתרומת הלשכה\u0004 של בית המקדש \u0003יהבינן להו\u0004 \u0005[נותנים אנו להם],\u0006 וכיון שהוא כסף הקודש משתדלים לצמצם בהוצאות. \u0003דאי סלקא דעתך מדידהו יהבינן להו\u0004 \u0005[שאם עולה על דעתך\u0006 לומר ש\u0005משלהם,\u0006 משל בעלי השדה, \u0005נותנים להם]\u0006 \u0003מאי נפקא לן מיניהו\u0004 \u0005[מה איכפת לנו מהם]?\u0006 \u0003כל כמה דבעו ליתן להו\u0004 \u0005[ש\u0006הם \u0005רוצים שיתנו להם]\u0006 לפועלים!","ולגוף הענין שואלים: \u0003ועד כמה,\u0004 מהו שיעור הכלאים שעליו יוצאים הפועלים לעקור? \u0003אמר רב שמואל בר יצחק: כאותה ששנינו\u0004 במשנה: \u0003כל סאה\u0004 של זרעים \u0003שיש בה\u0004"],["\u0003רובע\u0004 הקב \u0003זרע ממין אחר\u0004 (שהוא אחד מעשרים וארבעה) — \u0003ימעט\u0004 את הזרע האחר.","על עצם ההלכה, שיוצאים לעקור את צמחי הכלאים שצמחו בשדה, שואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003התקינו שיהו מפקירין כל השדה כולה\u0004 שיש בה כלאים, והרי שאין די במיעוט! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 שאמרנו שיוצאים וממעטים הוא \u0003קודם\u0004 שנתקנה ה\u0003תקנה, כאן\u0004 שאמרו שיש להפקיר את כל השדה, הרי זה \u0003לאחר\u0004 שנתקנה ה\u0003תקנה.\u0004","ומה היא תקנה זו — \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003בראשונה היו\u0004 שליחי בית דין \u0003עוקרין\u0004 את צמחי הכלאים \u0003ומשליכין לפני בהמתן\u0004 של בעלי השדות, \u0003והיו בעלי בתים שמחין שתי שמחות: אחת — שמנכשין להם שדותיהן\u0004 על ידי שנוטלים מתוכם את הצמחים הזרים, \u0003ואחת — שמשליכין\u0004 אוכל \u0003לפני בהמתן,\u0004 ולא הקפידו בבירור זרעי כלאים,","\u0003התקינו שיהו עוקרין ומשליכין על הדרכים. ועדיין היו שמחין שמחה גדולה שמנכשין שדותיהן\u0004 בחינם, \u0003התקינו שיהו מפקירין כל השדה כולה.\u0004","\u0003ר' אליעזר בן יעקב אומר: מושכין את המים מאילן לאילן\u0004 בחול המועד, שכיון שהאילנות זקוקים ביותר למים, מותר להשקותם, \u0003ובלבד שלא ישקה\u0004 אגב כך \u0003את כל השדה.\u0004 ועוד, \u0003זרעים שלא שתו\u0004 (שלא הושקו) \u0003לפני המועד,\u0004 שהם מסוג הזרעים שאינו דורש השקייה מרובה ולכך לא הקפיד להשקותם לפני המועד — \u0003לא ישקה\u0004 אותם \u0003במועד\u0004 שהרי ממילא אינם זקוקים כל כך למים, \u0003וחכמים מתירין בזה ובזה,\u0004 להשקות את השדה כולה במועד, וכן להשקות במועד אף את הזרעים שלא שתו לפני המועד \u0003.\u0004","\u0003אמר רב יהודה: אם היתה שדה\u0004 זו \u0003מטוננת\u0004 (שדה של טין), שהיתה לחה לפני המועד ועכשיו יבשה — \u0003מותר\u0004 להשקות את כל השדה אף לשיטת רבי אליעזר בן יעקב. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כשאמרו אסור להשקותן במועד — לא אמרו אלא בזרעים שלא שתו מלפני המועד\u0004 כלל, \u0003אבל זרעים ששתו לפני המועד\u0004 והתחילו לצמוח — \u0003מותר להשקותן במועד,\u0004 שאם לא ישקו אותם יהיה הפסד מרובה,","\u0003ואם היתה שדה מטוננת — מותר\u0004 אפילו לא שתו מים לפני המועד. \u0003ואין משקין שדה גריד\u0004 (שדה יבשה שאינה צריכה השקייה) \u0003במועד, וחכמים מתירין בזה ובזה\u0004 גם להשקות במועד גם זרעים שלא שתו לפני המועד אם הדבר נחוץ, וכן להשקות שדה גריד.","\u0003אמר רבינא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003האי תרביצא שרי לתרבוצי בחולא דמועדא\u0004 \u0005[גינה מותר לזלף\u0006 עליה מים \u0005בחול המועד]\u0006 וכיצד למדים אנו דבר זה: — \u0003שדה גריד מאי טעמא\u0004 \u0005[מה טעם]\u0006 התירו חכמים להשקותו למרות שאין הצמחים מתים בגלל היובש — שבסופו של דבר השקייה זו גורמת לכך \u0003דאפלא משוי לה חרפא\u0004 \u0005[ש\u0006את הפירות \u0005האפילים,\u0006 שהיו בשלים מאוחר יותר, \u0005הוא עושה בכירים]\u0006 על ידי השקיית עזר, משמע שאם הפירות מאחרים בהבשלתם נחשב הדבר להפסד, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בגינה \u0003אפלא משוי לה חרפא\u0004 \u0005[\u0006את \u0005האפיל\u0006 הוא \u0005עושה בכיר]\u0006 על ידי הרבצת מים ולכן מותר הדבר במועד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מרביצין\u0004 (מזלפים מים, השקאה קלה) \u0003שדה לבן\u0004 (שדה תבואה) \u0003ב\u0004שנת \u0003שביעית, אבל לא ב\u0004חול ה\u0003מועד.\u0004","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 האומרת: \u0003מרביצין בין במועד בין בשביעית! אמר רב הונא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא האוסרת בחול המועד, היא כשיטת \u0003ר' אליעזר בן יעקב\u0004 המחמיר בשדה יבש, \u0003הא\u0004 \u0005[זו]\u0006 שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 המקילים בכך.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003מרביצין שדה לבן\u0004 ב\u0003ערב שביעית כדי שיצאו ירקות בשביעית, ולא עוד אלא שמרביצין שדה לבן\u0004 אפילו \u0003בשביעית\u0004 עצמה \u0003כדי שיצאו ירקות למוצאי שביעית,\u0004 שהרבצת מים זו אינה עבודת אדמה גמורה, ואם אין גם העבודה וגם צמיחת הפירות בשנת השביעית — מותר.","\u0003צדין את האישות ואת העכברים משדה האילן ומשדה הלבן\u0004 (שדה תבואה) \u0003כדרכו,\u0004 כדרך שצד כל השנה כולה, גם \u0003ב\u0004חול ה\u0003מועד ו\u0004גם \u0003בשביעית. וחכמים אומרים: משדה האילן\u0004 צד אותם \u0003כדרכו, ומשדה הלבן\u0004 שאין ההפסד מרובה כל כך — \u0003שלא כדרכו,\u0004 בשינוי מסויים.","\u0003ומקרין\u0004 (סותמים) \u0003את הפירצה\u0004 בכותל הגינה \u0003במועד, ובשביעית בונה\u0004 מחיצה \u0003כדרכו\u0004 אף לכתחילה שהרי אין זו עבודת אדמה, ולמרות שהיא מועילה לשמירת הגן — לא נאסרה בשנת השמיטה.","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אישות? אמר רב יהודה: בריה שאין לה עינים,\u0004 החולד החופר באדמה שצריך לצוד אותו שלא יזיק את השורשים והירקות. \u0003אמר רבא בר ישמעאל ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יימר בר שלמיא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 שממנו למדים מה היא אישות? שנאמר: \u0003\"כמו שבלול תמס יהלך נפל אשת בל חזו שמש\"\u0004 (תהלים נח, ט), ואנו מבינים שהאישות (\"אשת\") אינה רואה שמש — מפני שהיא בריה חסרת עיניים.","ההלכה שבמשנה מובאת בהרחבה בברייתא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003צדין את האישות ואת העכברים משדה הלבן ומשדה האילן כדרכו, ומחריבין חורי נמלים\u0004 שהנמלים לא יזיקו. ומסבירים: \u0003כיצד מחריבין? רבן שמעון בן גמליאל אומר: מביא עפר מחור\u0004 נמלים \u0003זה ונותן לתוך חור זה\u0004 (קן נמלים אחר) \u0003ו\u0004מכיון שאין הנמלים מזהות את העפר, אינן מוציאות אותו ואינן יכולות לצאת החוצה ולכך \u0003הן חונקין זה את זה.\u0004","\u0003אמר רב יימר בר שלמיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי:\u0004 עצה זו מועילה רק בתנאים מסויימים, \u0003והוא — דקאי בתרי עברי נהרא\u0004 \u0005[שעומדים,\u0006 שמצויים חורי הנמלים הללו, \u0005בשני עברי הנהר\u0006 השונים\u0005];\u0006 \u0003והוא דליכא גשרא\u0004 \u0005[שאין גשר]\u0006 בין עברי הנהר; \u0003והוא דליכא גמלא\u0004 \u0005[שאין גשר צר]\u0006 על הנהר; \u0003והוא דליכא מצרא\u0004 \u0005[שאין חבל מתוח]\u0006 בין שני צידי הנהר, שאם יש חיבור כלשהו בין עברי הנהר מכירות הנמלים זו את זו, ואינן נלחמות זו בזו."],["\u0003עד כמה\u0004 נקראים חורים אלה קרובים שצריך שהנהר יפסיק ביניהם — \u0003עד פרסה.\u0004","\u0003ר' יהודה אומר: משדה האילן\u0004 צד את האישות והעכברים \u0003כדרכו, ומשדה הלבן שלא כדרכו. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד כדרכו? חופר גומא\u0004 באדמה \u0003ותולה בה מצודה\u0004 (מלכודת). \u0003כיצד שלא כדרכו? נועץ שפוד\u0004 באדמה \u0003ומכה בקורדום ומרדה\u0004 (ומוציא) את \u0003האדמה מתחתיה\u0004 עד שמוצאה והורג אותה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' שמעון בן אלעזר אומר: כשאמרו\u0004 שצד במועד את האישות והעכברים \u0003משדה לבן שלא כדרכו — לא אמרו אלא בשדה לבן הסמוכה לעיר,\u0004 שאז יש נזק רק לשדה \u0003אבל בשדה לבן הסמוכה לשדה האילן\u0004 יצוד \u0003אפילו כדרכו, שמא יצאו משדה הלבן ויחריבו את האילנות\u0004 בשדות הסמוכים וייגרם נזק גדול.","שנינו במשנה: \u0003ומקרין את הפירצה במועד.\u0004 ושואלים: \u0003כיצד מקרין? רב יוסף אמר: בהוצא ודפנא\u0004 (בעלי דקל ודפנה), שאינו עושה מחיצה של ממש, אלא רק סגירה ארעית.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 בענין זה: \u0003צר\u0004 (ממלא את הפירצה) \u0003בצרור\u0004 (אבנים), \u0003ואינו טח בטיט\u0004 את הצרורות הללו. \u0003אמר רב חסדא: לא שנו\u0004 שאין לסגור את הפירצה אלא בדרך ארעית \u0003אלא\u0004 ב\u0003כותל הגינה\u0004 שאין הפסד מרובה אם יש בו פירצה, \u0003אבל כותל החצר\u0004 שחשוב לאדם למנוע כניסה מזרים העלולים לגנוב — \u0003בונה כדרכו\u0004 אף במועד.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם לומר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ששנינו: \u0003כותל הגוחה\u0004 \u0005[הנוטה,\u0006 ועומד ליפול\u0005]\u0006 אל \u0003רשות הרבים — סותר ובונה כדרכו\u0004 בחול המועד \u0003מפני הסכנה\u0004 שעלול ליפול על העוברים והשבים. ודוחים: \u0003התם כדקתני טעמא\u0004 \u0005[שם כפי ששנה\u0006 את \u0005הטעם]\u0006 במפורש — \u0003מפני הסכנה,\u0004 אבל לא לשם שמירת החצר.","\u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]\u0006 שלא הביאו תוספתא זו לראיה אלא לסתור, וכך אמרו: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003כותל הגוחה לרשות הרבים\u0004 — \u0003סותר ובונה כדרכו מפני הסכנה.\u0004 ונדייק: \u0003מפני הסכנה — אין\u0004 \u0005[כן],\u0006 \u0003שלא מפני הסכנה — לא.\u0004 ואם כן \u0003לימא תיהוי תיובתיה\u0004 \u0005[האם לומר שתהא זו קושיה חמורה]\u0006 על דברי \u0003רב חסדא?\u0004","ומשיבים: \u0003אמר לך רב חסדא\u0004 (יכול היה רב חסדא לענות לך): \u0003התם\u0004 \u0005[שם]\u0006 במקום הסכנה הותר לו אף להיות \u0003סותר ובונה\u0004 ונמצא בונה גדר שלימה לכתחילה, \u0003הכא\u0004 \u0005[כאן]\u0006 בכותל חצר סתם הריהו \u0003בונה ולא סותר.\u0004","ושואלים: \u0003התם נמי\u0004 \u0005[שם גם כן],\u0006 שיש חשש סכנה, \u0003ליסתור\u0004 \u0005[שיסתור]\u0006 ועל ידי כך תתבטל הסכנה, \u0003ולא ליבני\u0004 \u0005[יבנה]\u0006 מחדש אלא לאחר המועד! ומשיבים: \u0003אם כן\u0004 שתאסור עליו לבנות, עלול להיות שבשל כך \u0003מימנע\u0004 \u0005[ימנע]\u0006 \u0003ולא סותר\u0004 \u0005[יסתור],\u0006 שהרי לא ירצה להשאיר את חצירו פרוצה, ולכן, כדי שלא יגיע הדבר לסכנה, מתירים לו גם לבנות.","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כהבנה זו, של רב חסדא \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]\u0006 \u0003ובשביעית בונה כדרכו.\u0004","ונברר: \u0003דהיכא\u0004 \u0005[של היכן]\u0006 גדר של איזה מקום התירו לבנות בשביעית? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שמדובר בכותל של \u0003חצר,\u0004 וכי זו \u0003צריכא למימר\u0004 \u0005[צריכה להיאמר]?\u0006 והרי לא נאסרה בשביעית אלא עבודת אדמה בלבד, וברור שמותר לבנות בנין אחר. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר שם בכותל של \u0003גינה\u0004 והוצרך הדבר להיאמר \u0003ואף על גב דמיחזי כמאן דעביד נטירותא לפירי\u0004 \u0005[ואף על פי שנראה כמי שעושה שמירה לפירות]\u0006 מכל מקום התירו לו, ואם כן משמע שמשנתנו כולה היא דווקא בכותל גינה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא הפירוש.","\u0003ר' מאיר אומר:\u0004 אין \u0003רואין את הנגעים,\u0004 כלומר, אין מביאים את מי שנראתה בו בהרת ויש חשש שהיא צרעת אל הכהן בחול המועד \u0003בתחילה\u0004 (בראשית ימי הטומאה) אלא \u0003להקל,\u0004 שהכהן הרואה יכול לטהר אותו, \u0003אבל לא להחמיר,\u0004 שאם רואה שהוא טמא — ישתוק, שאין הטומאה חלה עליו עד שיטמאנו הכהן בפירוש. וכל זה שלא לגרום צער לאדם במועד. \u0003וחכמים אומרים:\u0004 אין רואים את הנגעים בחול המועד כל עיקר, \u0003לא להקל ולא להחמיר.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' מאיר אומר: רואין את הנגעים להקל, אבל לא להחמיר. ר' יוסי אומר: לא להקל ולא להחמיר.\u0004 וטעמו: \u0003שאם אתה נזקק לו\u0004 לאותו אדם, שיבוא ויראה את נגעו \u0003להקל — נזקק לו אף להחמיר,\u0004 שאם רואה הכהן שהוא טמא צריך לומר שטמא הוא ולכן לא יזדקק לו כלל.","\u0003אמר רבי: נראין דברי ר' מאיר ב\u0004מצורע \u0003מוסגר,\u0004 שציוה קודם הכהן להכניסו להסגר שבוע ימים ועכשיו בודקו שנית, ואם יטהרו לחלוטין הריהו משמחו, ואם מסגיר אותו הסגר שני אינו מצערו, שכן לא נשתנה מצבו לרעה. \u0003ו\u0004לעומת זאת נראים \u0003דברי ר' יוסי במוחלט,\u0004 שהכהן קבע כבר שהוא מצורע, ועכשיו בא לראות אם נטהר. שאף אם נטהר עדיין צריך לספור שבעה ימים לטהרה, והרי הוא מצערו, לפיכך אין נזקק לו כלל.","\u0003אמר רבא: בטהור\u0004 גמור \u0003כולי עלמא לא פליגי דלא חזו ליה\u0004 \u0005[הכל אינם חולקים שאין\u0006 הכהנים \u0005רואים אותו]\u0006 שכן עלול לטמאו, ואין מביאים אדם לידי עוגמת נפש במועד. אם היה הטמא \u0003בהסגר ראשון — דכולי עלמא לא פליגי דחזי ליה\u0004 \u0005[הכל אינם חלוקים שרואים אותו],\u0006 שכאמור, אם יטהרנו הכהן — הריהו טהור, וגם אם יאמר שהוא טמא — הרי ישלחנו רק להסגר שני, ואינו מוסיף לו טומאה ואיסור. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו],\u0006"],["\u0003בהסגר שני. מר\u0004 \u0005[חכם זה\u0006 ר' מאיר\u0005]\u0006 \u0003סבר\u0004 כי \u0003בכהן תליא מילתא\u0004 \u0005[תלוי הדבר];\u0006 \u0003אי\u0004 \u0005[אם]\u0006 הוא \u0003טהור — אמר ליה\u0004 \u0005[לו]\u0006 הכהן \u0003\"טהור\", ואי\u0004 \u0005[ואם]\u0006 \u0003טמא\u0004 הוא — \u0003שתיק\u0004 \u0005[שותק]\u0006 הכהן וכל עוד שאין הכהן אומר שטמא הוא, אינו נטמא. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' יוסי\u0005]\u0006 \u0003סבר: \"\u0004זאת תורת נגע צרעת... \u0003לטהרו או לטמאו\"\u0004 (ויקרא יג, נט) \u0003כתיב\u0004 \u0005[נאמר],\u0006 וכפי שהכהן חייב לטהר, כך הוא חייב לטמא ואיננו רשאי לשתוק.","\u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003אמר רבי: נראין דברי ר' יוסי במוחלט ודברי ר' מאיר במוסגר.\u0004 ומקשים: \u0003והתניא איפכא\u0004 \u0005[והרי שנויה\u0006 ברייתא האומרת \u0005להיפך],\u0006 שנראים דברי רבי יוסי במוסגר ודברי רבי מאיר במוחלט!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003רבי,\u0004 ובכך נחלקו: \u0003מר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 \u0003סבר: צוותא דעלמא עדיף ליה\u0004 \u0005[חברת העולם,\u0006 חברת הכלל \u0005עדיפה לו\u0006 לאדם\u0005]\u0006 ואם יטמאו הכהן וייעשה מצורע מוחלט, הריהו צריך לצאת מחוץ לשלוש מחנות, ואם מטהרו הרי משמחו, ולכן, יכול הכהן לראות במועד.","\u0003ומר סבר: צוותא\u0004 \u0005[חברת]\u0006 \u0003אשתו עדיפא ליה\u0004 \u0005[עדיפה לו]\u0006 שאם הוא מצורע מוחלט — מותר לו להיות עם אשתו, אולם אם יטהרנו הכהן יצטרך לספור שבעה ימים שבהם אסור הוא באשתו, ומפני שצער הוא לו עדיף שלא יבוא לכהן במועד כלל.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר,\u0006 וללמוד, מכאן\u0005]\u0006 שמצורע \u0003מוחלט מותר בתשמיש המטה?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[ואכן\u0006 כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר במצורע הסופר שבעה ימים לטהרתו: \u0003\"וישב מחוץ לאהלו שבעת ימים\"\u0004 (ויקרא יד, ח), ללמד \u0003שיהא אסור בתשמיש המטה,\u0004 כי \u0003אין \"אהלו\" אלא\u0004 רמז עבור \u0003אשתו, שנאמר: \"לך אמר להם שובו לכם לאהליכם\"\u0004 (דברים ה, כז). \u0003ר' יהודה אומר:\u0004 נאמר \u0003\"\u0004ואחרי טהרתו \u0003שבעת ימים יספרו לו\"\u0004 (יחזקאל מד, כו), ומדייקים: דווקא \u0003ימי ספירו\u0004 אסורים בתשמיש המיטה \u0003ולא ימי חלוטו.\u0004","\u0003ר' יוסי בר' יהודה אומר:\u0004 כיון שגילה הכתוב שב\u0003שבעה ימי ספירו\u0004 אסור בתשמיש, \u0003קל וחומר לימי חלוטו\u0004 שבהם טומאתו חמורה.","\u0003ואמר ר' חייא: דנתי לפני רבי\u0004 ואמרתי: הלא \u0003לימדתנו רבינו,\u0004 ש\u0003יותם\u0004 המלך \u0003לא היה לו\u0004 (לא נולד לו) \u0003לעוזיהו\u0004 מלך יהודה \u0003אלא בימי חלוטו\u0004 (כשהיה מצורע מוחלט), הרי שמצורע מוחלט מותר בתשמיש, \u0003אמר לו: אף אני כך אמרתי\u0004 וגם אני סבור שמצורע מוחלט מותר בתשמיש המיטה, ולא כרבי יוסי ברבי יהודה.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון, הם \u0005חלוקים]?\u0006 ומסבירים, \u0003ר' יוסי בר' יהודה סבר: גלי רחמנא\u0004 \u0005[גילתה התורה]\u0006 \u0003בימי ספירו\u0004 שאסור באשתו \u0003וכל שכן\u0004 שאסור \u0003בימי חלוטו\u0004 כאשר הוא טמא בטומאה חמורה. \u0003ומר\u0004 \u0005[וחכם\u0006 זה\u0005]\u0006 \u0003סבר: מאי דגלי\u0004 \u0005[מה שגילה]\u0006 הכתוב — \u0003גלי\u0004 \u0005[גילה],\u0006 \u0003ומאי דלא גלי\u0004 \u0005[ומה שלא גילה] —\u0006 \u0003לא גלי\u0004 \u0005[גילה]\u0006 שאין להוסיף חומרה שאינה מפורשת.","ושואלים: לגופה של המחלוקת הראשונה ביחס לראיית הנגע \u0003למימרא\u0004 \u0005[האם לומר]\u0006 שב\u0003כהן תליא מילתא\u0004 \u0005[תלוי הדבר],\u0006 אם לטמא או לטהר, אם לראות את הנגע או לא לראות? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[ואכן\u0006 כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"וביום הראות בו\"\u0004 (ויקרא יג, יד), ומלשון הכתוב נלמד: \u0003יש יום שאתה רואה בו, ויש יום שאי אתה רואה בו.\u0004","\u0003מכאן אמרו: חתן שנולד בו נגע — נותנין לו שבעה ימי המשתה\u0004 ואין הולכים לכהן לבדוק אם טמא הוא. ואם נולד הנגע \u0003לו,\u0004 כלומר, בו עצמו, \u0003ולביתו\u0004 אם נראה הנגע בביתו \u0003ולכסותו\u0004 אם נראה הנגע בבגדו, \u0003וכן\u0004 אם נראה באדם נגע \u0003ברגל — נותנין לו שבעת ימי הרגל\u0004 ואין מצערים אותו במועד, אלו \u0003דברי ר' יהודה,\u0004 ומכאן שהכל תלוי בכהן.","\u0003רבי אומר:\u0004 הדין נכון הוא, אבל \u0003אינו צריך\u0004 למדרש זה, שיש ראיה פשוטה מכתוב אחר, \u0003הרי הוא אומר: \"וצוה הכהן ופנו את הבית\u0004 בטרם יבוא הכהן לראות את הנגע ולא יטמא כל אשר בבית\u0003\"\u0004 (ויקרא יד, לו), \u0003אם ממתינים לו\u0004 לבית ואין הכהן מטמא אותו מיד, שהוא \u0003לדבר הרשות,\u0004 כדי למנוע שיטמאו הכלים שבבית — \u0003כל שכן\u0004 שממתינים לו \u0003לדבר מצוה\u0004 כדי שלא לפגוע בשמחת חתן או בשמחת הרגל.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 אם מקור ההלכה הוא בפסוק זה או אחר? \u0003אמר אביי: משמעות דורשין\u0004 ההבדל הוא במקור הדרשה מאיזה כתוב דורשים, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שכל אחד יש לו דרשה אחרת מן הכתוב שחבירו דורש. \u0003ורבא אמר:\u0004 לענין של \u0003דבר הרשות\u0004 סיבה שאינה של מצוה, אם דוחים בגללה את ראיית הנגע \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שלדעת רבי יהודה רק בדבר מצוה ממתינים ולא בדבר אחר, ולדעת רבי הרי מוכח שאף לדבר הרשות אפשר להמתין לו.","ושואלים: \u0003ור' יהודה\u0004 מה טעמו שאין ממתינים לדבר הרשות, למרות דברי הכתוב בטומאת הבתים? ומשיבים: לדעתו \u0003מהתם לא גמרינן\u0004 \u0005[משם אין אנו למדים]\u0006 הלכה כללית, משום שענין זה של טומאת בתים כולו \u0003חידוש הוא,\u0004 והוא דין מיוחד ומבודד בתורה ואין ללמוד ממנו לדברים אחרים,"],["\u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003עצים ואבנים בעלמא\u0004 \u0005[בכלל]\u0006 בשאר דיני התורה \u0003לא מטמאו\u0004 \u0005[אינם נטמאים],\u0006 \u0003והכא מטמאו\u0004 \u0005[וכאן\u0006 בצרעת הבית \u0005נטמאים].\u0006","\u0003ורבי אמר: אצטריך\u0004 \u0005[נצרך]\u0006 להיאמר בכתוב גם \"וביום הראות בו\" (ויקרא יג, יד), וגם \"וצוה הכהן\" (ויקרא יד, לו), \u0003דאי כתב רחמנא\u0004 \u0005[שאילו\u0006 היתה \u0005כותבת התורה]\u0006 רק \u0003\"וביום הראות בו\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כרבי יהודה ש\u0003לדבר מצוה — אין\u0004 \u0005[כן]\u0006 ממתינים עד שייראה לכהן אבל \u0003לדבר הרשות\u0004 — \u0003לא,\u0004 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"וצוה הכהן\"\u0004 לומר שממתינים גם לדבר הרשות.","ולהיפך, \u0003ואי כתב רחמנא\u0004 \u0005[ואילו\u0006 היתה \u0005כותבת התורה]\u0006 \u0003\"וצוה הכהן\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני\u0004 \u0005[\u0006בדברים \u0005אלה]\u0006 הנמצאים בבית — \u0003אין\u0004 \u0005[כן]\u0006 אנחנו דוחים את הטומאה עד שיבא הכהן כיון \u0003דלאו\u0004 \u0005[ש\u0006זאת \u0005לא]\u0006 \u0003טומאה דגופיה\u0004 \u0005[של גופו]\u0006 של האדם ואינה מתוכו אלא בדברים אחרים, \u0003אבל טומאה דגופיה\u0004 \u0005[שבגופו]\u0006 \u0003אימא מיחזא חזיא ליה\u0004 \u0005[אמור\u0006 שמיד צריך \u0005לראות אותו]\u0006 על כן \u0003צריכא\u0004 \u0005[נצרך]\u0006 הדבר להיאמר שאף בזה ממתינים.","\u0003אמר מר\u0004 \u0005[החכם,\u0006 רבי יהודה\u0005]\u0006 בדרשת הכתוב \"וביום הראות בו\" (ויקרא יג, יד): \u0003יש יום שאתה רואה בו ויש יום שאי\u0004 (שאין) \u0003אתה רואה בו.\u0004","ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות]?\u0006 כלומר, כיצד נובע רעיון זה מלשון הכתוב? \u0003אמר אביי:\u0004 אם לא היתה כוונה זו, \u0003אם כן ליכתוב רחמנא\u0004 \u0005[\u0006ש\u0005תכתוב התורה]\u0006 רק \u0003\"ביום\u0004 הראות\", \u0003מאי\u0004 \u0005[מה]\u0006 הדיוק בלשון \u0003\"וביום\" — שמע מינה\u0004 \u0005[למד מכאן]\u0006 מ־ו' נוספת זו שאין זה דין מוחלט אלא יש תנאי בדבר: \u0003יש יום שאתה רואה בו, ויש יום שאי אתה רואה בו.\u0004","\u0003רבא אמר\u0004 באופן אחר: \u0003כולה קרא יתירא\u0004 \u0005[כל מקרא\u0006 זה, מלה זו, \u0005יתר]\u0006 \u0003הוא,\u0004 ש\u0003אם כן,\u0004 בלא כוונה זו \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \u0003\"ובהראות\", מאי\u0004 \u0005[מה\u0006 משמעות ההוספה\u0005]\u0006 \u0003\"וביום\" — שמע מינה\u0004 שהדבר תלוי בזמן, \u0003יש יום שאתה רואה בו, ויש יום שאי אתה רואה בו.\u0004","ומסבירים: \u0003ואביי\u0004 שאינו רואה במלה \"וביום\" ייתור, לדעתו \"וביום\" \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללימוד אחר — שהכהן רואה את הנגע רק \u0003ביום ולא בלילה.\u0004","ושואלים: \u0003ורבא\u0004 דין זה שהכהן רואה \u0003ביום ולא בלילה מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נובע \u0005לו]\u0006 הדבר \u0003מ\u0004מה שנאמר \u0003\"לכל מראה עיני הכהן\"\u0004 (ויקרא יג, יב), לומר שהכהן צריך לראות את הנגע ראייה שלימה וטובה, ולא בזמן שאי אפשר לראות כראוי. \u0003ואביי\u0004 יאמר שהכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[צריך לו]\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 כהן \u0003סומא\u0004 (עיור) \u0003באחת מעיניו,\u0004 שאינו רשאי לראות נגעים, שהרי נאמר \"עיני הכהן\" בלשון רבים.","ושואלים: \u0003ו\u0004הלא \u0003רבא נמי מיבעי ליה להכי\u0004 \u0005[גם כן צריך לו\u0006 הפסוק \u0005לענין זה]?\u0006 ומשיבים: \u0003אין, הכי נמי\u0004 \u0005[כן, כך גם כן\u0006 הוא סבור\u0005]\u0006 שבאמת פסוק זה הוא מקור לאותה הלכה,","ואם כן שאין הכהן רואה \u0003אלא ביום ולא בלילה מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נובע \u0005לו]\u0006 הדבר \u0003מ\u0004מה שנאמר \u0003\"כנגע נראה לי בבית\"\u0004 (ויקרא יד, לה), שיש כאן הדגשה: \u0003\"לי\" — ולא לאורי,\u0004 שאינו נזקק לנר ושאר אמצעי עזר כדי לראות.","\u0003ואביי,\u0004 מדוע נזקק הוא לראיה שהביא, כאשר לכאורה מפסוק זה יש הוכחה ברורה לכך? ומסבירים: לדעתו, \u0003אי מהתם\u0004 \u0005[אם משם]\u0006 מפסוק זה בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כך: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שיש להמתין עד אור היום אמורים בטומאת הבית שהיא \u0003טומאה דלאו דגופיה\u0004 \u0005[שאינה בגופו],\u0006 \u0003אבל טומאה דגופיה\u0004 \u0005[שבגופו]\u0006 שהיא טומאה חמורה \u0003אפילו לאורו נמי\u0004 \u0005[גם כן]\u0006 יבדקנו הכהן, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כתוב אחר \"וביום\" שצריך לראות ביום, לאור יום דווקא ולא באור מלאכותי.","\u0003ועוד אמר ר' מאיר\u0004 קולא אחרת בדיני חול המועד: \u0003מלקט אדם עצמות אביו ואמו\u0004 מן הקבר בחול המועד. שמנהג היה לפנים, שהיו קוברים את המתים בתחילה בקבר זמני ומשבלה בשר המת היו מלקטים את העצמות וחוזרים וקוברים אותן בקברי אבותיו. ומותר לעשות זאת במועד \u0003מפני ששמחה היא לו\u0004 שזוכה להביאן לקברי אבותיו.","\u0003ר' יוסי אומר:\u0004 לא ילקט כי \u0003אבל הוא לו,\u0004 שמכל מקום נזכר ומצטער במיתת הוריו.","ולדעת הכל — \u0003לא יעורר אדם\u0004 (יקרא להספד) \u0003על מתו, ולא יספידנו קודם לרגל שלשים יום.\u0004","שנינו במשנה שרבי מאיר אומר שליקוט עצמות נחשב כשמחה, \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003המלקט עצמות אביו ואמו\u0004 — \u0003הרי זה מתאבל עליהם כל היום,\u0004 אבל \u0003ולערב אין מתאבל עליהן. ואמר רב חסדא:\u0004 ו\u0003אפילו\u0004 אינו מלקטן מן הקבר אלא היו \u0003צרורין לו\u0004 העצמות \u0003בסדינו\u0004 במקום אחר, כאשר קוברן מתאבל כל אותו היום. ואם כן, נראה שליקוט עצמות דבר של עצב ואבל הוא!","\u0003אמר אביי: אימא\u0004 \u0005[אמור]\u0006 לא מפני ששמחה היא לו הקבורה, אלא \u0003מפני ששמחת הרגל עליו,\u0004 שמתוך שעוסק רבות בענייני שמחת הרגל, הרי הצער שבליקוט עצמות אביו ואמו אינו ניכר כל כך, ששמחת הרגל מבטלתו, ואינו מצטער כל כך.","שנינו במשנה: \u0003ולא יערער על מתו.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא יערער על מתו\"? אמר רב: כד הדר ספדנא במערבא\u0004 \u0005[כאשר מחזר\u0006 וסובב \u0005הספדן בארץ ישראל]\u0006 ומספיד בעיר, \u0003אמרי\u0004 \u0005[אומרים]\u0006 הספדנים: \u0003יבכון עמיה כל מרירי ליבא\u0004 \u0005[יבכו עמו כל מרי הלב],\u0006 וכשאומרים דברים אלה נזכרים גם אנשים שיש להם צער אחר, ומתאבלים גם הם עמו.","שנינו במשנה שאין מספידים \u0003קודם הרגל שלשים יום.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 מה עניינם של \u0003שלשים יום\u0004 אלה? שהרי אין מדובר כאן בביטול שמחת המועד!","\u0003אמר רב כהנא אמר רב יהודה אמר רב:\u0004 איסור זה נובע ממעשה שהיה; \u0003מעשה באדם אחד שכינס\u0004 (אסף) \u0003מעות לעלות לרגל, ובא ספדן ועמד על פתח ביתו, ונטלתן אשתו\u0004 של אותו אדם \u0003ונתנתן לו\u0004 כשכר עבור ההספד \u0003ונמנע\u0004 אותו האיש \u0003ולא עלה\u0004 לרגל מחוסר כסף, ו\u0003באותה שעה אמרו: לא יעורר על מתו ולא יספידנו קודם לרגל שלשים יום.\u0004","\u0003ושמואל אמר:\u0004"],["\u0003לפי שאין המת משתכח מן הלב שלשים יום,\u0004 ולכן כשמספידו פחות משלושים יום לפני הרגל עדיין זוכרים את הצער ברגל. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהם]\u0006 אם זה הטעם או זה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 במקרה \u0003דקעביד\u0004 \u0005[שעושה]\u0006 הספדן הספד \u0003בחנם,\u0004 שאין לחשוש להוצאת המעות שנועדו לרגל, אבל משום צער יש לחשוש.","\u0003אין חופרין כוכין\u0004 של קבורה \u0003וקברות במועד\u0004 להכין עבור אלה שימותו לאחר זמן, \u0003אבל מחנכין\u0004 (מתקנים) \u0003את הכוכין\u0004 החפורים כבר \u0003במועד. ו\u0004אגב היתר זה לחפור מוסיפים כי \u0003עושים נברכת\u0004 (חפירה בקרקע, כעין בריכה לצורך כיבוס) \u0003במועד,\u0004 שאין בזה טירחה יתירה. \u0003ו\u0004כן מותר לעשות \u0003ארון\u0004 כאשר עושה הארון נמצא \u0003עם המת בחצר\u0004 אחת, שיודעים הכל שלצורך המת הוא עושה. \u0003ר' יהודה אוסר\u0004 לעשות את הארון \u0003אלא אם כן יש עמו\u0004 כבר \u0003נסרים\u0004 חתוכים מערב החג, שצריך רק לחברם.","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003כוכין ומאי\u0004 \u0005[ומה\u0006 הם\u0005]\u0006 \u0003קברות,\u0004 ומה ההבדל ביניהם? \u0003אמר רב יהודה: כוכין\u0004 קרויים מקומות קבורה שעושים \u0003בחפירה\u0004 באדמה, \u0003וקברות\u0004 הם שעושים דרך \u0003בנין.\u0004 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אלו הן כוכין ואלו הן קברות, כוכין — בחפירה, וקברות בבנין.\u0004","שנינו במשנה: \u0003אבל מחנכין את הכוכין.\u0004 ושואלים: \u0003כיצד מחנכין?\u0004 כלומר, מהו חינוך זה? \u0003אמר רב יהודה: שאם היה\u0004 הכוך \u0003ארוך\u0004 ממידת המת — \u0003מקצרו. במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 בענין זה: \u0003מאריך בו\u0004 בכוך, \u0003ומרחיב בו\u0004 לפי צורכו של המת.","שנינו במשנה: \u0003ועושין נברכת במועד.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003נברכת זו? אמר רב יהודה: זו בקיע\u0004 שחופרים באדמה לצורך כביסה. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנברכת והבקיע\u0004 משמע שהם דברים שונים! \u0003אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב כהנא: גיהא ובר גיהא\u0004 \u0005[בריכה ובת בריכה],\u0006 כלומר, אין הבדל ביניהם במהות אלא רק בגודל, שנברכת גדולה יותר, ובקיע הוא קטן.","שנינו במשנה: \u0003ו\u0004עושים בחול המועד \u0003ארון\u0004 למת, כשבונה הארון \u0003עם המת בחצר.\u0004 ומעירים: \u0003תנינא להא דתנו רבנן\u0004 \u0005[\u0006משנה \u0005זו שנינו\u0006 ברמז \u0005מה ששנו חכמים\u0006 בברייתא\u0005]\u0006 בהרחבה בלשון זו: \u0003עושין כל צורכי המת\u0004 במועד: \u0003גוזזין לו שערו\u0004 אם היה מגודל מדי, \u0003ומכבסין לו כסותו\u0004 (תכריכין) \u0003ועושין לו ארון מנסרין המנוסרין מערב יום טוב. רבן שמעון בן גמליאל אומר: אף מביאין עצים ומנסרן בצינעא בתוך ביתו.\u0004","\u0003אין נושאין נשים במועד, לא בתולות ולא אלמנות, ו\u0004אף \u0003לא מייבמין\u0004 (את אשת האח) במועד — \u0003מפני ששמחה היא לו. אבל מחזיר הוא את גרושתו\u0004 ונושאה שנית במועד, שאין זו שמחה כל כך.","\u0003ועושה אשה תכשיטיה במועד,\u0004 כלומר: מותר לה לעשות טיפולים שונים בגופה כדי לייפות עצמה. \u0003רבי יהודה אומר: לא תסוד\u0004 (לא תשים סיד על עורה) לשם יופי, \u0003מפני ש\u0004לפי שעה \u0003ניוול הוא לה.\u0004 ועוד אמרו: \u0003ההדיוט,\u0004 מי שאיננו חייט אומן \u0003תופר כדרכו\u0004 אם צריך לכך, \u0003והאומן מכליב\u0004 (תפירה ארעית) בלבד. \u0003ומסרגין את המטות\u0004 שמים את החבלים שעליהם מניחים את המצע במיטה, \u0003ר' יוסי אומר:\u0004 רק \u0003ממתחין\u0004 את החבלים.","שנינו במשנה שאין נושאים נשים במועד מפני ששמחה היא לו. ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003שמחה היא לו, מאי הוי\u0004 \u0005[מה היה],\u0006 מה הרע בכך? והרי מצוה לשמוח במועד! \u0003אמר רב יהודה אמר שמואל, וכן אמר ר' אלעזר אמר ר' אושעיא, ואמרי לה\u0004 \u0005[\u0006ויש \u0005אומרים זאת]\u0006 אחרת: \u0003אמר ר' אלעזר אמר ר' חנינא: לפי שאין מערבין שמחה בשמחה,\u0004 וצריך לשמוח בכל אחת מהן לעצמה. \u0003רבה בר רב הונא אמר:\u0004 הטעם הוא \u0003מפני שמניח שמחת הרגל ועוסק בשמחת אשתו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 שאמר \u0003רבה בר רב הונא דרב הוא\u0004 \u0005[של רב היא],\u0006 שהמקור לדעה זו היא שיטת רב. ש\u0003אמר רב דניאל בר קטינא אמר רב: מנין שאין נושאים נשים במועד — שנאמר: \"ושמחת בחגך\"\u0004 (דברים טז, יד) להדגיש: עליך לשמוח \u0003בחגך ולא באשתך.\u0004","\u0003עולא אמר:\u0004 הטעם שאין נושאין נשים במועד הוא \u0003מפני הטורח,\u0004 שבשל ההכנות לחתונה יטרחו טירחה יתירה בחול המועד. \u0003ר' יצחק נפחא אמר: מפני ביטול פריה ורביה,\u0004 שאם יהיה מותר לשאת נשים במועד, ידחו כולם את נישואיהם עד למועד כדי לחסוך בהוצאות, ובינתים אינם מקיימים מצות פריה ורביה במשך השנה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא ששנינו בה: \u0003כל אלו שאמרו אסורין לישא במועד\u0004 —"],["\u0003מותרין לישא ערב הרגל,\u0004 ואם כן \u0003קשיא לכולהו\u0004 \u0005[קשה לכולם]\u0006 שהרי שמחת נישואין נמשכת כרגיל שבעה ימים, ורובה אפוא במועד.","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 וכך יש לתרץ; \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003משום שמחה\u0004 שלא לערב שמחה בשמחה, או שלא לדחות שמחת הרגל מפני שמחת אשתו — \u0003עיקר שמחה\u0004 של נישואין \u0003חד יומא\u0004 \u0005[יום אחד]\u0006 \u0003הוא,\u0004 ודי לה אם כן בערב הרגל.","\u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003משום טירחא\u0004 יתירה במועד — גם כאן יש לומר ש\u0003עיקר טירחא חד יומא\u0004 \u0005[יום אחד]\u0006 \u0003הוא\u0004 ואין טורחים כל כך בימים הבאים. \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003משום ביטול פריה ורביה\u0004 אין לחשוש, כי \u0003לחד יומא לא משהי איניש נפשיה\u0004 \u0005[ליום אחד\u0006 בלבד של ערב החג \u0005אין אדם משהה עצמו]\u0006 ואין לחשוש שידחו נישואין כל השנה רק ליום זה. ואם כן, לכל הטעמים אין לאסור נישואין בערב הרגל.","שואלים: ואותו עיקרון שהזכרנו ש\u0003אין מערבין שמחה בשמחה מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויעש שלמה בעת ההיא את החג וכל ישראל עמו קהל גדול מלבוא חמת עד נחל מצרים לפני ה' אלהינו שבעת ימים ושבעת ימים ארבעה עשר יום\"\u0004 (מלכים א' ח, סה), \u0003ואם איתא\u0004 \u0005[יש],\u0006 אם אכן \u0003מערבין שמחה בשמחה,\u0004 אם כן \u0003איבעי ליה למינטר\u0004 \u0005[היה לו לשמור,\u0006 להמתין\u0005]\u0006 בחנוכת המקדש \u0003עד החג\u0004 (סוכות) שחל ימים אחדים אחר כך, \u0003ומיעבד\u0004 \u0005[ולעשות]\u0006 \u0003שבעה\u0004 ימי שמחה \u0003להכא ולהכא\u0004 \u0005[לכאן ולכאן,\u0006 לזה ולזה\u0005],\u0006 וכיון שלא עשה כן משמע שאין מערבים שתי שמחות יחד.","ושואלים: \u0003ודלמא מינטר לא נטרינן\u0004 \u0005[ושמא לשמור,\u0006 להמתין ולדחות לשם כך \u0005אין אנחנו\u0006 \u0005שומרים,\u0006 ממתינים\u0005]\u0006 ומכל מקום \u0003והיכא דאתרמי\u0004 \u0005[ובמקום שמזדמן]\u0006 מעצמו שיהיו שתי שמחות באותו זמן — \u0003עבדינן\u0004 \u0005[עושים]\u0006 אותן יחד! ומשיבים: אילו היה הדבר אכן מותר, אם כן יכול היה לעשות שיזדמנו שתי השמחות יחד, וכיצד — \u0003איבעי ליה לשיורי פורתא\u0004 \u0005[היה לו לשייר מעט]\u0006 מבנין המקדש ולגמור במועד.","ודוחים: \u0003שיורי\u0004 \u0005[לשייר]\u0006 ב\u0003בנין בית המקדש לא משיירינן\u0004 \u0005[אין אנו משיירים],\u0006 שמצוה ראוי לעשותה בזריזות. ואולם עדיין יש לומר: הלא יכול היה לגמור את הבנין עצמו בשלימות, ועם זאת להשאיר לסיום דבר קטן שאינו מעצם הבנין — \u0003איבעי ליה לשיורי\u0004 \u0005[היה לו לשייר]\u0006 \u0003באמה\u0004 שבגג המקדש שהיתה נקראת \u0003\"כליא עורב\",\u0004 שעושים בגג הבית מוטות מחודדים של מתכת כדי שלא יישבו שם עורבים הנמשכים לריח הבשר, וזה אינו חלק מן הבנין עצמו.","ודוחים: אף \u0003אמה כליא עורב צורך בנין הבית הוא,\u0004 וצריך היה להזדרז לעשותו מיד. \u0003אלא\u0004 הראיה מכתוב זה היא \u0003מדמייתר קרא\u0004 \u0005[מ\u0006מה \u0005שמיותר הכתוב],\u0006 שכן \u0003מכדי כתיב\u0004 \u0005[הלא נאמר]\u0006 \u0003\"ארבעה עשר יום\",\u0004 אם כן פירוט \u0003\"שבעת ימים ושבעת ימים\" למה לי?\u0004 אלא \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003הני\u0004 \u0005[אלה]\u0006 \u0003לחוד והני\u0004 \u0005[ואלה]\u0006 \u0003לחוד,\u0004 לומר שאין לערבב שבעת ימי שמחת המקדש בשבעת ימי הרגל.","כיון שהזכרנו את ימי השמחה הללו, מביאים גם מה ש\u0003אמר ר' פרנך אמר ר' יוחנן: אותה שנה\u0004 של חנוכת המקדש בימי שלמה \u0003לא עשו ישראל את יום הכפורים.\u0004 שהרי שבעת הימים של שמחת חנוכת הבית כללו בתוכם גם את יום הכיפורים ועשו את כולם ימי שמחה. \u0003והיו דואגים ואומרים: שמא נתחייבו שונאיהן של ישראל\u0004 (בלשון נקיה, כלומר: ישראל) \u0003כלייה,\u0004 שעברו על איסור כרת ואכלו ביום הכיפורים, \u0003יצתה בת קול\u0004 מן השמים \u0003ואמרה להם: כולכם מזומנין לחיי העולם הבא.\u0004","ושואלים: בהיתר זה \u0003מאי דרוש\u0004 \u0005[מה דרשו],\u0006 על מה סמכו? \u0003אמרו: קל וחומר; ומה משכן שאין קדושתו קדושת עולם, ו\u0004בכל זאת בשמחת חנוכתו היה \u0003קרבן יחיד\u0004 של הנשיא \u0003דוחה\u0004 את ה\u0003שבת,\u0004 שהרי הקריבו בכל יום ואף בשבת, \u0003ש\u0004יש בכך \u0003איסור סקילה, מקדש,\u0004 ש\u0003קדושתו קדושת עולם ו\u0004קרבנות שהקריבו בו בחנוכת המקדש היו \u0003קרבן צבור, ו\u0004דחו בגללו רק \u0003יום הכפורים\u0004 ש\u0003ענוש כרת\u0004 שהוא נחשב כעונש קל ביחס לסקילה, \u0003לא כל שכן\u0004 שמותר?!","ושואלים: \u0003אלא,\u0004 כיון שהיתה להם ראיה לדבר, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003היו דואגים?\u0004 ומשיבים: שיש מקום לפרוך קל וחומר זה: \u0003התם\u0004 \u0005[שם]\u0006 במשכן היה חילול השבת רק \u0003לצורך גבוה\u0004 בהקרבת קרבן, אולם \u0003הכא\u0004 \u0005[כאן]\u0006 במקדש היתה אכילה ושתיה שהיא \u0003צורך הדיוט.\u0004 ושואלים: אם כן הוא, \u0003הכא נמי מיעבד ליעבדו\u0004 \u0005[כאן\u0006 במקדש \u0005גם כן שיעשו]\u0006 שמחה בהקרבת קרבנות \u0003מיכל\u0004 \u0005[לאכול]\u0006 \u0003לא ניכלו\u0004 \u0005[יאכלו]\u0006 \u0003ו\u0004לשתות \u0003לא לישתו\u0004 \u0005[ישתו]!\u0006 ומשיבים: \u0003אין שמחה\u0004 שלימה \u0003בלא אכילה ושתיה.\u0004","לגוף הראיה הזו שואלים: \u0003ומשכן דדחי\u0004 \u0005[שדוחים]\u0006 קרבנותיו את ה\u0003שבת מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003אילימא מדכתיב\u0004 \u0005[אם תאמר ממה שנאמר]\u0006 בקרבנות: \u0003\"ביום הראשון...\"\u0004(במדבר ז, יב) \u0003ו\"ביום השביעי\"\u0004 (במדבר ז, מח), \u0003דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא לא שביעי לסדר ימות השבוע אלא \u0003שביעי ל\u0004ימי הבאת ה\u0003קרבנות,\u0004 ושמא דילגו ולא הקריבו ביום השבת? \u0003אמר רב נחמן בר יצחק: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ביום עשתי עשר יום\"\u0004 (במדבר ז, עב), וחזרה זו על המלה \"יום\" באה ללמד \u0003מה יום כולו רצוף\u0004 שהוא יחידת זמן אחת, \u0003אף עשתי עשר כולן רצופין\u0004 שלא פסקו מלהקריב, אף בשבת שבתוכם.","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 נאמר שהכוונה היא רק ל\u0003ימים הראויין\u0004 שכל הימים האחרים היו רצופים, לבד מיום השבת שאינו ראוי לקרבן יחיד? ומשיבים: \u0003כתיב קרא אחרינא\u0004 \u0005[נאמר כתוב אחר]:\u0006 \u0003\"ביום שנים עשר יום\"\u0004 (במדבר ז, עח), ללמד: \u0003מה יום כולו רצוף — אף שנים עשר יום כולן רצופין.\u0004","ושואלים שוב: \u0003ודלמא הכא נמי\u0004 \u0005[ושמא כאן גם כן]\u0006 הכוונה היא ל\u0003ימים הראויין!\u0004 ודוחים: \u0003אם כן תרי קראי\u0004 \u0005[שני כתובים]\u0006 האומרים אותו דבר \u0003למה לי?\u0004 וכיון שההדגשה נשנתה פעמיים, הרי זה ללמד שכל הימים היו רצופים, ובלא הפסקה כלל.","ושואלים: \u0003ו\u0004העבודה ב\u0003מקדש\u0004 שהיא \u0003דוחה\u0004 את \u0003יום הכפורים, מנלן\u0004 \u0005[מניין לנו]\u0006 מנין אנו יודעים שכך היה מעשה, ולא צמו אז ביום הכיפורים? \u0003אילימא מדכתיב\u0004 \u0005[אם תאמר מ\u0006מה \u0005שנאמר]:\u0006 \u0003\"ארבעה עשר יום\", ודלמא\u0004 \u0005[ושמא]\u0006 הכוונה בכתוב היא רק ל\u0003ימים הראויין\u0004 ודילגו על יום הכיפורים! ומשיבים: \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"יום\" \"יום\" מהתם\u0004 \u0005[משם\u0006 מן המשכן\u0005]\u0006 שהכוונה היא לימים רצופים ללא הפסקה.","וחוזרים למה שאמר ר' יוחנן כי \u0003יצתה בת קול ואמרה להם: כולכם מזומנין לחיי העולם הבא,\u0004 ושואלים: \u0003ומנלן\u0004 \u0005[מניין לנו]\u0006 \u0003דאחיל להו\u0004 \u0005[שמחל להם\u0006 עוון זה\u0005]\u0006 ומשיבים: \u0003דתני\u0004 \u0005[ששנה\u0006 החכם\u0005]\u0006 \u0003תחליפא\u0004 בברייתא, נאמר: \u0003\"וביום השמיני שלח את העם ויברכו את המלך וילכו לאהליהם שמחים וטובי לב על כל הטובה אשר עשה ה' לדוד עבדו ולישראל עמו\"\u0004 (מלכים א' ח, סו), וכך פירושו:","\u0003\"לאהליהם\" — שהלכו ומצאו נשיהם בטהרה\u0004 (שהרי אהלו־ביתו, זו אשתו), \u0003\"שמחים\" — שנהנו מזיו השכינה,\u0004 שהיה גילוי שכינה בהקרבת הקרבנות במקדש, \u0003\"וטובי לב\" — שכל אחד ואחד נתעברה אשתו בבן זכר, \"על כל הטובה\" — שיצתה בת קול ואמרה להם: כולכם מזומנין לחיי העולם הבא\u0004 (שהיא הטובה השלימה).","נאמר: \u0003\"לדוד עבדו ולישראל עמו\"\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שנאמר \u0003\"לישראל עמו\"\u0004 — \u0003דאחיל להו\u0004 \u0005[שמחל להם]\u0006 \u0003עון יום הכפורים\u0004 שלא קיימו אותה שנה, \u0003אלא לדוד עבדו מאי היא\u0004 \u0005[מה הוא]\u0006 עניינו כאן?","\u0003אמר רב יהודה אמר רב: בשעה שביקש שלמה להכניס ארון למקדש דבקו שערים זה לזה\u0004 ולא נפתחו. \u0003אמר שלמה עשרים וארבע רננות\u0004 לשבח לה' \u0003ולא נענה, פתח ואמר \"שאו שערים ראשיכם\u0004 והנשאו פתחי עולם ויבוא מלך הכבוד\u0003\"\u0004 (תהלים כד, ז), \u0003ולא נענה\u0004 ונשארו השערים סגורים,","\u0003כיון שאמר \"\u0004ועתה קומה ה' אלהים למנוחתך אתה וארון עוזך כהניך \u0003ה' אלהים\u0004 ילבשו תשועה וחסידיך ישמחו בטוב. ה' אלהים \u0003אל תשב פני משיחך זכרה לחסדי דוד עבדך\"\u0004 (דברי הימים ב' ו, מא-מב) — \u0003מיד נענה. באותה שעה נהפכו פני שונאי דוד כשולי\u0004 (תחתית) \u0003קדירה\u0004 (שהם כרגיל שחורים מאד) \u0003וידעו הכל\u0004 על ידי כך \u0003שמחל לו הקדוש ברוך הוא על אותו עון\u0004 של בת שבע, שראו שרק בזכותו נפתחו שערי המקדש.","מתוך קשר מסויים לאותם מקראות מסופר: \u0003ר' יונתן בן עסמיי ור' יהודה בן גרים תנו\u0004 \u0005[שנו]\u0006 \u0003פרשת נדרים בי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שמעון בן יוחי,\u0004 לאחר שסיימו את הלימוד הזה \u0003איפטור מיניה באורתא\u0004 \u0005[נפרדו ממנו\u0006 לשלום \u0005בערב]?\u0006 אבל לא יצאו מן העיר, \u0003לצפרא הדור וקא מפטרי מיניה\u0004 \u0005[לבוקר חזרו\u0006 ושוב \u0005נפרדו ממנו].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ולאו איפטריתו מיני באורתא\u0004 \u0005[והאם לא נפרדתם\u0006 כבר \u0005ממני בערב]?\u0006","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003למדתנו רבינו\u0004 ש\u0003תלמיד שנפטר מרבו\u0004 ומוסיף אחר הפרידה \u0003ולן באותה העיר, צריך ליפטר ממנו פעם אחרת, שנאמר\u0004 לאחר גמר שמחת חנוכת הבית: \u0003\"ביום השמיני שלח את העם ויברכו את המלך\"\u0004 (מלכים א' ח, סו), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וביום עשרים ושלשה לחדש השביעי שלח את העם\"\u0004 (דברי הימים ב', ז, י) והרי היום השמיני הוא יום שמיני עצרת, עשרים ושנים בתשרי, ונאמר ששלח את העם למחרת ביום עשרים ושלושה!","\u0003אלא מכאן לתלמיד הנפטר מרבו ולן באותה העיר\u0004 (שהרי ודאי לא יצאו מן העיר ביום החג עצמו ונשארו ללון) \u0003צריך ליפטר ממנו פעם אחרת\u0004 כפי שעשו ישראל ביום שלאחר החג (ביום העשרים ושלושה).","\u0003אמר לו\u0004 רבי שמעון \u0003לבריה\u0004 \u0005[לבנו]:\u0006 \u0003בני\u0004 ה\u0003אדם הללו\u0004 שני חכמים אלה \u0003אנשים של צורה הם,\u0004 כלומר, אנשים חכמים ונבונים, \u0003זיל גביהון דליברכוך\u0004 \u0005[לך אליהם שיברכו אותך].\u0006 \u0003אזל אשכחינהו דקא רמו קראי אהדדי\u0004 \u0005[הלך\u0006 ו\u0005מצא אותם שהם מקשים כתובים זה על זה]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בפסוק אחד: \u0003\"פלס מעגל רגלך וכל דרכיך יכנו\"\u0004 (משלי ד, כו), משמע שאדם צריך לפלס, כלומר למדוד ולחשב איזו מצוה חשובה יותר לעשותה, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"ארח חיים פן תפלס\u0004 נעו מעגלותיה לא תדע\u0003\"\u0004(משלי ה, ו), משמע, שצריך אדם לעשות כל מצוה הבאה לידו ולא לבחור בין דבר לדבר!","ותירצו: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 בפסוק הראשון שמשמע שיש להדר לקיים את המצוה החשובה יותר, הרי זה כשהמצוה שחשובה פחות היא \u0003מצוה שאפשר לעשותה על ידי אחרים,\u0004"],["\u0003כאן\u0004 בפסוק השני שמשמע שאין לו לבחור בין המצוות, הרי זה \u0003במצוה שאי אפשר לעשותה על ידי אחרים\u0004 וכיון שכן, עליו לעשותה בעצמו אף אם היא חשובה פחות.","\u0003הדר יתבי וקא מבעי להו\u0004 \u0005[חזרו\u0006 ו\u0005ישבו ונסתפק להם]\u0006 בשאלה זו: \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד בשבח התורה: \u0003\"יקרה היא מפנינים וכל חפציך לא ישוו בה\"\u0004 (משלי ג, טו), ומכאן נדייק: אמנם חפציך שלך לא ישוו בה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003חפצי שמים — ישוו בה,\u0004 משמע שמצוות (\"חפצי שמים\") חשובות כמו התורה, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"\u0004כי טובה חכמה מפנינים \u0003וכל חפצים לא ישוו בה\"\u0004 (משלי ח, יא), ומפסוק זה משמע שנאמר הדבר בהכללה ש\u0003אפילו חפצי שמים לא ישוו בה!\u0004","ותירצו: \u0003כאן במצוה שאפשר לעשותה על ידי אחרים\u0004 אז כל חפצים, ואפילו חפצי שמים, לא ישוו לתורה, ואדם הלומד תורה יעדיף אותה, והמצוה תיעשה על ידי אחרים, \u0003כאן במצוה שאי אפשר לעשותה על ידי אחרים\u0004 אז התורה חשובה רק מחפציו, ולא מחפצי שמים.","בינתיים הבחינו בבנו של רבי שמעון \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי בעית הכא\u0004 \u0005[מה רצונך כאן]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 ש\u0003אמר לי אבא: זיל גבייהו דליברכוך\u0004 \u0005[לך אליהם שיברכוך].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 ברכה זו: \u0003יהא רעוא\u0004 \u0005[יהי רצון]\u0006 ש\u0003תזרע ולא תחצד\u0004 \u0005[תקצור],\u0006 \u0003תעייל\u0004 \u0005[תכניס]\u0006 \u0003ולא תיפוק\u0004 \u0005[תוציא],\u0006 \u0003תיפוק\u0004 \u0005[תוציא]\u0006 \u0003ולא תעייל\u0004 \u0005[תכניס],\u0006 \u0003ליחרוב ביתך וליתוב אושפיזך,\u0004 \u0005[שיחרב ביתך ויתיישב מלונך],\u0006 \u0003לבלבל פתורך\u0004 \u0005[שיתבלבל שולחנך],\u0006 \u0003ולא תחזי שתא חדתא\u0004 \u0005[תראה שנה חדשה].\u0006","\u0003כי אתא לגבי אבוה\u0004 \u0005[כאשר בא אל אביו]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא מבעיא דברוכי\u0004 \u0005[די שלברך]\u0006 \u0003לא בירכן\u0004 \u0005[בירכו אותי]\u0006 \u0003אבל צעורי צעורן\u0004 \u0005[אלא\u0006 אף \u0005ציערו אותי]\u0006 בדברים רעים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביו: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמרו לך?\u0004 ענה לו: \u0003הכי והכי\u0004 \u0005[כך וכך]\u0006 \u0003אמרו לי, אמר ליה\u0004 \u0005[לו]\u0006 אביו: \u0003הנך כולהו ברכתא נינהו\u0004 \u0005[אלה כולן ברכות הן]\u0006 ואמרו בלשון חכמה, וכך פירושן: \u0003תזרע ולא תחצד\u0004 \u0005[תקצור]\u0006 כוונתם: \u0003תוליד בנים ולא ימותו. תעייל\u0004 \u0005[תכניס]\u0006 \u0003ולא תיפוק\u0004 \u0005[תוציא]\u0006 כוונתם: \u0003תעייל כלתא\u0004 \u0005[תכניס כלות]\u0006 לבניך \u0003ולא לימותו בנך דליפקון\u0004 \u0005[ימותו בניך שייצאו\u0006 הכלות בגלל זה ממך\u0005].\u0006 \u0003תיפוק\u0004 \u0005[תוציא]\u0006 \u0003ולא תעייל\u0004 \u0005[תכניס]\u0006 כוונתם: \u0003תוליד בנתא\u0004 \u0005[בנות]\u0006 \u0003ולא ימותו גוברייהו\u0004 \u0005[בעליהן]\u0006 \u0003וליהדרו לותיך\u0004 \u0005[ו\u0006כתוצאה מכך \u0005יחזרו\u0006 הבנות \u0005אליך].\u0006","\u0003ליחרוב ביתך וליתוב אושפיזך\u0004 \u0005[\u0006ש\u0005ייחרב ביתך ויתיישב מלונך]\u0006 — \u0003דהאי עלמא אושפיזך וההיא עלמא ביתך\u0004 \u0005[שעולם זה\u0006 הוא \u0005בית המלון שלך, והעולם הבא\u0006 הוא \u0005ביתך],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"קרבם בתימו לעולם\"\u0004 (תהלים מט, יב), ואמרו חכמים: \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"קרבם\" אלא \"קברם\",\u0004 כלומר, הקבר הוא בית קבוע לעולם, ובירכו אותו שלא ישב בביתו הקבוע, אלא דווקא במלונו, כלומר: יאריך ימים.","\u0003לבלבל פתורך\u0004 \u0005[שיתבלבל שולחנך],\u0006 כוונתם: \u0003בבני ובנתא\u0004 \u0005[בבנים ובנות]\u0006 מרובים, ויהיה רעש ובלבול בשולחן. \u0003ולא תיחזי שתא חדתא\u0004 \u0005[תראה שנה חדשה],\u0006 כוונתם ש\u0003לא תמות אנתך\u0004 \u0005[אשתך]\u0006 \u0003ולא תנסב אינתתא אחריתי\u0004 \u0005[תישא אשה אחרת],\u0006 שעליה נאמר: \"כי יקח איש אשה חדשה לא ייצא בצבא ולא יעבר עליו לכל דבר נקי יהיה לביתו שנה אחת\" (דברים כד, ה).","אגב מעשה זה מספרים עוד מעשה בברכה סתומה: \u0003ר' שמעון בן חלפתא אפטר מיניה\u0004 \u0005[נפרד ממנו]\u0006 מ\u0003רב, אמר ליה אבוה\u0004 \u0005[לו אביו]:\u0006 \u0003זיל לגביה דליברכך\u0004 \u0005[לך אליו שיברך אותך].\u0006 הלך אליו להתברך, וברכו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יהא רעוא\u0004 \u0005[יהי רצון]\u0006 ש\u0003לא תבייש ולא תתבייש. אתא גבי אבוה\u0004 \u0005[בא אל אביו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 האב: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמר לך? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מילין בעלמא\u0004 \u0005[דברים סתם]\u0006 \u0003הוא\u0004 ש\u0003אמר לי,\u0004 כלומר, דברים בלתי חשובים.","משפירט לו את הדברים \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ברכך ברכתא דברכן קודשא בריך הוא\u0004 \u0005[בירך אותך ברכה שבירך הקדוש ברוך הוא]\u0006 \u0003לישראל\u0004 וחזר \u0003ותנא\u0004 \u0005[ושנה]\u0006 \u0003בה,\u0004 שנאמר: \u0003\"ואכלתם אכול ושבוע והללתם\u0004 את שם ה' אלהיכם אשר עשה עמכם להפליא \u0003ולא יבשו עמי לעולם. וידעתם כי בקרב ישראל אני\u0004 ואני ה' אלהיכם ואין עוד \u0003ולא יבשו עמי לעולם\"\u0004 (יואל ב, כו-כז), משמע שברכה זו גדולה היא מאוד.","שנינו במשנה ש\u0003עושה אשה תכשיטיה\u0004 במועד. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אלו הן תכשיטי נשים\u0004 שדובר בהם: \u0003כוחלת\u0004 (שמה כחול על עיניה) \u0003ופוקסת\u0004 (מסירה שיער מיותר) \u0003ומעבירה שרק\u0004 (צבע אדום) \u0003על פניה. ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 \u0003מעברת סרק על פניה של מטה\u0004 (לשון נקיה, וכוונתו שמסירה שערות הערוה).","מסופר: \u0003דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003רב חסדא מקשטא באנפי\u0004 \u0005[היתה מתקשטת\u0006 בחול המועד \u0005בפני]\u0006 \u0003כלתה,\u0004 שאף שכבר היו לה בנים גדולים נשואים היתה מתקשטת בחול המועד. \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב הונא בר חיננא\u0004 באותו זמן \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חסדא ויתיב וקאמר\u0004 \u0005[וישב ואמר]:\u0006 \u0003לא שנו\u0004 שמותר לאשה לעשות תכשיטים אלה בחול המועד \u0003אלא\u0004 ב\u0003ילדה\u0004 (צעירה) שאצלה זה שמחה במועד \u0003אבל זקנה — לא,\u0004 שאינה צריכה לכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003האלהים!\u0004 (לשון קריאה והדגשה) \u0003אפילו אמך\u0004 מותר לה להתקשט \u0003ואפילו\u0004 ה\u0003אימא\u0004 של \u0003אימך, ואפילו\u0004 אשה זקנה הנראית כזו ה\u0003עומדת על קברה,\u0004 כולן מותרות. \u0003דאמרי אינשי\u0004 \u0005[שאומרים אנשים]\u0006 פתגם ידוע: \u0003בת שיתין כבת שית, לקל טבלא רהטא\u0004 \u0005[בת שישים כבת שש, לקול התוף\u0006 היא \u0005רצה],\u0006 כלומר, נשים נשארות צעירות ברוחן בכל גיל, וכיון שיש להן הנאה בקישוט אין הדבר תלוי בגיל.","שנינו במשנה, \u0003ר' יהודה אומר: לא תסוד\u0004 אשה במועד, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יהודה אומר: אשה לא תסוד\u0004 במועד \u0003מפני שניוול הוא לה\u0004 לפי שעה, כל עוד הסיד שעל גופה. \u0003ומודה ר' יהודה\u0004 אם מורחת \u0003סיד שיכולה לקפלו\u0004 (להסירו) \u0003במועד, שטופלתו\u0004 (מורחתו) \u0003במועד, שאף על פי שמצירה\u0004 (מצטערת) \u0003היא עכשיו\u0004 בסיד הזה המכער אותה לפי שעה, מכל מקום \u0003שמחה היא לאחר זמן\u0004 על התוצאה כשמסירה את הסיד.","ושואלים: \u0003ומי אית ליה\u0004 \u0005[האם יש לו,\u0006 מקבל\u0005]\u0006 \u0003ר' יהודה האי סברא\u0004 \u0005[סברה זו]\u0006 שמתחשבים בשמחה שלאחר זמן? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 שאין עושים מסחר עם גויים בימי חגיהם, כדי שלא לגרום להם להודות לעבודה זרה על הצלחתם, ואין פורעים להם חוב, ואף אין נפרעים מהם לקבל חובותיהם.","\u0003ר' יהודה אומר: נפרעין מהן\u0004 בחגיהם \u0003מפני שמצר\u0004 הגוי כשהוא משלם ואין זו שמחה לו בחגו. \u0003אמרו לו: אף על פי שמצר עכשיו — שמח הוא לאחר זמן,\u0004 שנפטר מעול החוב, ולכן אף אין נפרעין ממנו. הרי שרבי יהודה איננו מתחשב בשמחה שלאחר זמן!","\u0003אמר רב נחמן בר יצחק: הנח להלכות מועד\u0004 שאין להשוותן להלכות אחרות \u0003דכולהו\u0004 \u0005[שכולן]\u0006 כל העבודות המותרות הטעם בהן שהוא \u0003מצר עכשיו ושמח לאחר זמן נינהו\u0004 \u0005[הם],\u0006 וכגון בישול ואפיה, שאף על פי שהכנת האוכל כרוכה בטירחה ובצער, מכל מקום יש שמחה מאוחר יותר בשעת האכילה.","\u0003רבינא אמר\u0004 תירוץ אחר: יש לחלק בין הנושאים, שלדעת רבי יהודה \u0003גוי לענין פרעון לעולם מצר\u0004 וגם לאחר מעשה הוא מצטער על כך. אבל בכלל מקבל רבי יהודה את העיקרון של שמח לאחר זמן.","בהסברת ענין זה של מריחת הגוף בסיד \u0003אמר ר' יהודה: בנות ישראל שהגיעו לפירקן,\u0004 כלומר, שהן מתבגרות ושערן צומח הרבה, \u0003ולא הגיעו\u0004 עדיין \u0003לשנים\u0004 הראויות לשיער, ומתביישות בכך, \u0003עניות\u0004 שבהן \u0003טופלות\u0004 (מורחות) \u0003אותן\u0004 את שערותיהן \u0003בסיד\u0004 כדי שישיר את השיער, \u0003עשירות טופלות אותן בסולת\u0004 לשם מטרה זו, ו\u0003בנות מלכים\u0004 טופלות \u0003בשמן המור,\u0004 והוא \u0003שנאמר\u0004 בנשים שבאו אל המלך אחשורוש: \u0003\"ששה חדשים בשמן המר\"\u0004 (אסתר ב, יב).","ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003\"שמן המור\"? רב הונא בר חייא אמר:\u0004 הוא שמן הבושם הקרוי \u0003סטכת, רב ירמיה בר אמי אמר: שמן זית שלא הביא שליש,\u0004 שעוצרים מזיתים שלא הבשילו, שהוא חריף, ויפה למטרה זו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: אנפיקינון\u0004 שנזכר במשנה הוא \u0003שמן זית שלא הביא שליש. ולמה סכין אותו — שמשיר את השער ומעדן את הבשר.\u0004","בענין זה של טפילה בסיד מסופר: \u0003רב ביבי הוה ליה ברתא\u0004 \u0005[היתה לו בת],\u0006 \u0003טפלה\u0004 (מרחה) על עצמה סיד \u0003אבר\u0004 אחר \u0003אבר\u0004 בהדרגה, ונשרו שערותיה והלבין עורה, והתייפתה כל כך עד אשר \u0003שקל\u0004 \u0005[נטל]\u0006 \u0003בה,\u0004 בכתובתה \u0003ארבע מאה זוזי\u0004 \u0005[מאות זוז],\u0006 שכל כך התייפתה. \u0003הוה ההוא גוי בשבבותיה דהוה ליה ברתא\u0004 \u0005[היה גוי אחד בשכנותו שהיתה\u0006 גם \u0005לו בת]\u0006 ורצה גם הוא לעשות כן \u0003טפלה\u0004 (מרח אותה) בסיד בכל גופה \u0003בחד זמנא\u0004 \u0005[בפעם אחת]\u0006 \u0003ומתה, אמר\u0004 אותו גוי: \u0003קטלא\u0004 \u0005[הרג]\u0006 \u0003ביבי לברתי\u0004 \u0005[את בתי],\u0006 שהרי בגללו עשה מה שעשה. \u0003אמר רב נחמן\u0004 באותו ענין: \u0003רב ביבי דשתי שיכרא\u0004 \u0005[ש\u0006נוהג היה \u0005לשתות שיכר]\u0006 — \u0003בעיין בנתיה טפלא\u0004 \u0005[צריכות בנותיו טפילה],\u0006 משום שהשיכר גורם לגידול שיער, אבל \u0003אנן דלא שתינן שיכרא\u0004 \u0005[אנחנו שאין אנו שותים שיכר]\u0006 — \u0003לא בעיין בנתין טפלא\u0004 \u0005[אין בנותינו צריכות טפילה זו],\u0006 ששערן מועט גם בלא טיפול זה."],["שנינו במשנה כי \u0003ההדיוט תופר כדרכו\u0004 בחול המועד. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד זה\u0006 בדיוק\u0005]\u0006 \u0003הדיוט\u0004 לענין זה? \u0003אמרי\u0004 \u0005[אומרים]\u0006 החכמים \u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: כל שאינו יכול להוציא מלא מחט בבת אחת,\u0004 שמי שיכול לתפור כמה תפירות במלוא אורך המחט ולהוציא את החוט במשיכה אחת בלא תקלה — אומן הוא לענין זה. \u0003ר' יוסי בר חנינא אמר: כל שאינו יכול לכוין אימרא\u0004 (לתפור את כפל הבד) \u0003בחפת\u0004 (בקצה) \u0003חלוקו,\u0004 ותופרה שלא בקו ישר הוא הקרוי הדיוט.","שנינו שם עוד: \u0003והאומן מכליב.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מכליב? ר' יוחנן אמר: מפסיע\u0004 שאינו תופר את כל התפרים בקו ישר, והריהן כשיני הכלב שרחוקות זו מזו. \u0003רבה בר שמואל אמר: שיני כלבתא\u0004 \u0005[\u0006כ\u0005שיני כלבה]\u0006 ולכן קרוי מכליב, שאין התפירות סמוכות זו לזו כמעשה אומן, אלא תופר תפירה אחת ומדלג ותופר עוד אחת ומדלג, והרי זה כשיני כלב שאינן רצופות.","במשנה שנינו ש\u0003מסרגין את המטות\u0004 ור' יוסי אמר שממתחים. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מסרגין\" ומאי\u0004 \u0005[ומה\u0006 הפירוש\u0005]\u0006 \u0003\"ממתחין\"? כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: פליגי בה\u0004 \u0005[חלקו בכך]\u0006 \u0003ר' חייא בר אבא ורב אסי, ותרוייהו משמיה\u0004 \u0005[ושניהם משמם]\u0006 של \u0003חזקיה ור' יוחנן. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \"\u0003מסרגין\"\u0004 פירושו — שמניחים וקושרים את חבלי המיטה \u0003שתי וערב, ו\u0004אילו \u0003\"ממתחין\"\u0004 פירושו שמותחים רק \u0003שתי בלא ערב. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: \"מסרגין\"\u0004 פירושו שמניחים רק \u0003שתי בלא ערב, ו\"ממתחין\"\u0004 פירושו \u0003שאם היה רפוי — ממתחו\u0004 ומחזקו. אבל לא עושה סירוג חדש.","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003רב תחליפא בר שאול\u0004 ברייתא זו: \u0003ושוין\u0004 ר' מאיר ור' יוסי \u0003שאין מפשילין\u0004 (גודלים, מייצרים) \u0003חבלים לכתחלה\u0004 בחול המועד. ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003\"מסרגין\"\u0004 פירושו \u0003שתי וערב, \"ממתחין\" — שתי בלא ערב, היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003רב תחליפא בר שאול: ושוין שאין מפשילין חבלים לכתחלה,\u0004 שאף שהתירו לשים את חבלי המיטה, לא התירו לייצרם.","\u0003אלא למאן דאמר\u0004 \u0005נל\u0006 שיטת \u0005מי שאומר]\u0006 כי \u0003\"מסרגין\"\u0004 הוא \u0003שתי בלא ערב, ו\"ממתחין\"\u0004 פירושו \u0003שאם היה רפוי היה ממתחו. השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003שתי וערב אמרת לא,\u0004 שאסור לעשות, אף אם יש בידו חבלים מוכנים — לעשות \u0003חבלים לכתחלה מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאסור?! ומעירים, אכן, \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לר' חייא בר אבין: מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 ש\u0003\"מסרגין\"\u0004 פירושו \u0003שתי בלא ערב? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' מאיר אומר: המטה\u0004 מקבלת טומאה (שנחשבת כבר ככלי ראוי לשימוש) \u0003משיסרוג בה שלשה בתים,\u0004 כלומר, שלוש פעמים ערב על השתי. ומכאן ברור שסירוג המיטה הוא עשיית שתי וערב!","\u0003אלא\u0004 עלינו לחזור מן הנוסח הקודם, ומסופר, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר\u0004 מסורת אחרת: \u0003ב\"מסרגין\" כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שזה \u0003שתי וערב, אלא כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה בפירוש הביטוי \u0003\"ממתחין\". מר סבר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 \u0003סבר\u0004 ש\u0003\"ממתחין\"\u0004 פירושו עשיית \u0003שתי בלא ערב, ומר\u0004 \u0005[וחכם\u0006 זה\u0005]\u0006 \u0003סבר: שאם היה רפוי — ממתחו.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך מברייתא ששנינו בה: \u0003מסרגין את המטה ואין צריך לומר שממתחין,\u0004 אלו \u0003דברי ר' מאיר. ר' יוסי אומר: ממתחין אבל לא מסרגין. ויש אומרים: אין ממתחין כל עיקר.\u0004","ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003\"ממתחין\"\u0004 הוא \u0003שתי בלא ערב, היינו דאתו\u0004 \u0005[זהו שבאו]\u0006 \u0003יש אומרים לאיפלוגי\u0004 \u0005[לחלוק]\u0006 ולומר שאין ממתחים כל עיקר, שאסור לעשות אפילו שתי, אבל מתיחת חבלים רפויים מותרת לדעת הכל. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\"ממתחין\" פירושו \u0003שאם היה רפוי ממתחו,\u0004 אם כן \u0003ליש אומרים ממתחו נמי לא\u0004 \u0005[גם כן לא]\u0006 וכיצד יישן על מיטה כזו?","ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 אכן כך סבור הוא שאף אסור למתח, והטעם — \u0003כיון\u0004 ש\u0003אפשר לממלייה במאני\u0004 \u0005[למלא את\u0006 המיטה \u0005בבגדים]\u0006 ויתמלא השקע שבה ואפשר יהיה לישון עליה — \u0003לא טרחינן\u0004 \u0005[אין אנו טורחים]\u0006 בתיקון כלי.","\u0003מעמידין\u0004 כלומר בונים \u0003תנור וכירים וריחים במועד, ר' יהודה אומר: אין מכבשין את הריחים בתחילה\u0004 במועד.","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מכבשין\u0004 ריחיים? \u0003רב יהודה אמר: מנקר ריחיא\u0004 \u0005[ניקור הריחיים]\u0006 לפי שאבן הריחיים נשחקת במשך הזמן, ונעשית חלקה מאד, וכדי לתקנה שתוכל לטחון היטב צריך לעשות בה שוב נקבים וחריצים. \u0003רב יחיאל אמר: בת עינא\u0004 \u0005[בת עין],\u0006 נקב שעושים מתחילה באבן הרכב של הריחיים, שתוכל התבואה להכנס דרכו בין אבני הריחיים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003מעמידין תנור וכירים במועד ובלבד שלא יגמור מלאכתן\u0004 עד סופה. אלו \u0003דברי ר' אליעזר, וחכמים אומרים: אף יגמור. ר' יהודה אומר משמו\u0004 של ר' אליעזר: \u0003מעמידין את\u0004 אבן הריחיים \u0003החדשה, ומכבשין את הישנה. ויש אומרים: אין מכבשין כל עיקר,\u0004 ומעתה:","\u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003מכבשין\u0004 פירושו \u0003מנקר ריחיא\u0004 \u0005[ניקור הריחיים],\u0006 \u0003היינו דמשכחת לה\u0004 \u0005[זהו שאתה מוצא אותה\u0006 את הדבר\u0005]\u0006 \u0003בישנה,\u0004 שהרי אף אבן ריחיים ישנה צריכה ניקור מחודש, \u0003אלא למאן דאמר בת עינא\u0004 \u0005[אלא ל\u0006שיטת \u0005מי שאומר\u0006 שהכוונה ל\u0005בת עין]\u0006 של ריחיים — אבן ריחיים \u0003ישנה, בת עינא\u0004 \u0005[בת עין]\u0006 \u0003למה לה?\u0004 הלא אבן ישנה ודאי יש לה בת עין זה מכבר! ומשיבים: אפשר לפרש \u0003כגון דקא בעי לארווחי טפי פורתא\u0004 \u0005[שהוא רוצה לרווח,\u0006 להגדיל את החור, \u0005קצת יותר].\u0006","מסופר: \u0003רב הונא שמעיה לההוא גברא דקא מנקר ריחיא בחולא דמועדא\u0004 \u0005[שמע אדם אחד שהיה מנקר ריחיים בחול המועד],\u0006 \u0003אמר: מאן האי\u0004 \u0005[מי זה]?\u0006 \u0003איתחיל גופיה דקא מחיל חולא דמועדא\u0004 \u0005[שיתחלל גופו\u0006 על \u0005שהוא מחלל את חול המועד]\u0006 ומעירים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 רב הונא שהלכה \u0003כ\u0004דעת \u0003יש אומרים\u0004 שאסור לכבש כל עיקר.","\u0003דרש רב חמא: נוקרין ריחים במועד. משום ר' מאיר אמר: אפילו סוס שרוכב עליו וחמור שרוכב עליו מותר ליטול צפרנים\u0004 שלהם (לחתוך קצת את פרסותיהם) \u0003בחולו של מועד\u0004 כדי שלא יצטערו בהליכתם,"],["\u0003אבל חמרא דריחיא\u0004 \u0005[החמור ש\u0006מסובב ב\u0005ריחיים]\u0006 — \u0003לא\u0004 ואסור ליישר פרסותיו, לפי שאין זה לצורך המועד, שהרי אין טוחנים טחינה רבה במועד.","בכל זאת נמסר כי \u0003רב יהודה שרי למישקל טופריה לחמרא דריחיא\u0004 \u0005[התיר ליטול\u0006 את \u0005הצפורנים לחמור של ריחיים],\u0006 \u0003ולאוקומי ריחיא\u0004 \u0005[ולהעמיד\u0006 אבני \u0005ריחיים\u0006 במקומן\u0005],\u0006 \u0003ולמיבני ריחיא\u0004 \u0005[ולבנות\u0006 את בסיס \u0005הריחיים],\u0006 \u0003ולמיבני\u0004 \u0005[ולבנות]\u0006 את \u0003אמת ריחיא\u0004 \u0005[הריחיים],\u0006 אמת המים שבה זורמים המים המניעים את הריחיים, \u0003ולמיבני אוריא\u0004 \u0005[ולבנות אורווה\u0006 לבהמות\u0005].\u0006 \u0003רבא שרא לסרוקי סוסיא\u0004 \u0005[התיר לסרק סוס]\u0006 \u0003ולמיבני אקרפיטא\u0004 \u0005[ולבנות מעקה]\u0006 \u0003ולמיבני איצטבא\u0004 \u0005[ולבנות ספסל].\u0006","\u0003רבא שרא למישקל דמא\u0004 \u0005[התיר להקיז דם]\u0006 \u0003לבהמה בחולא דמועדא\u0004 \u0005[בחול המועד]\u0006 כדי לרפאה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: תניא דמסייע לך\u0004 \u0005[שנוייה\u0006 ברייתא \u0005שמסייעת לך],\u0006 ששנינו: \u0003מקיזין דם לבהמה, ואין מונעין רפואה לבהמה בחולו של מועד.\u0004","\u0003רבא שרא לכסכוסי קירמי\u0004 \u0005[התיר לשפשף בגדים]\u0006 בתהליך כיבוסם, \u0003מאי טעמא\u0004 \u0005[\u0006ו\u0005מה טעם]\u0006 — \u0003מעשה הדיוט הוא\u0004 שאין זו מלאכת אומן האסורה במועד. \u0003אמר רב יצחק בר אמי אמר רב חסדא: קיטורי בירי\u0004 \u0005[קישור\u0006 קפלים \u0005בשרוולים] —\u0006 \u0003אסיר\u0004 \u0005[אסור],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 — \u0003מעשה אומן הוא,\u0004 ומלאכת אומנות גמורה לא התירו במועד.","\u0003אמר רבא: מאן דמתקיל ארעא\u0004 \u0005[מי שמסקל קרקע]\u0006 אם עשה זאת \u0003אדעתא דבי דרי\u0004 \u0005[על דעת\u0006 לפנות הקרקע לעשות \u0005מקום גורן] —\u0006 \u0003שרי\u0004 \u0005[מותר]\u0006 הדבר, \u0003אדעתא דארעא\u0004 \u0005[על דעת קרקע]\u0006 אם לצורך זריעה — \u0003אסיר\u0004 \u0005[אסור].\u0006","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק\u0006 הדבר\u0005]\u0006 כיצד יודעים מה כוונתו? — אם הוא זורק \u0003מוליא במוליא ונצא בנצא\u0004 \u0005[\u0006לוקח \u0005רגב\u0006 גבוה ושם \u0005על רגב\u0006 גבוה אחר או שלוקח \u0005מחריץ\u0006 ממקום נמוך ומחזיר \u0005לחריץ\u0006 אחר\u0005]\u0006 מוכח שעושה זאת \u0003אדעתא דבי דרי\u0004 \u0005[על דעת\u0006 לעשות \u0005גורן],\u0006 שכוונתו רק לפנות שטח ישר באמצע ואיננו מעונין באדמה שמסביב, אולם אם הוא \u0003שקל מוליא ושדא בנצא\u0004 \u0005[לוקח ממקום גבוה וזורק בחריץ,\u0006 במקום נמוך\u0005] —\u0006 מן הסתם \u0003אדעתא דארעא\u0004 \u0005[על דעת קרקע],\u0006 והריהו כחורש.","\u0003ואמר רבא: האי מאן דזכי זיכי\u0004 \u0005[מי שמקושש עצים],\u0006 אם עושה כן \u0003אדעתא דציבי\u0004 \u0005[על דעת\u0006 ליטול את \u0005העצים\u0006 לשימושו\u0005]\u0006 — \u0003שרי\u0004 \u0005[מותר],\u0006 אולם אם עושה כן \u0003אדעתא דארעא\u0004 \u0005[על דעת\u0006 לתקן \u0005הקרקע]\u0006 — \u0003אסיר\u0004 \u0005[אסור],\u0006 שדומה לחורש ומכשיר את הקרקע לזריעה ביום טוב. \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק\u0005]\u0006 מבחינים? \u0003שקיל רברבי ושביק זוטרי\u0004 \u0005[נוטל\u0006 עצים \u0005גדולים ומניח קטנים]\u0006 — \u0003אדעתא דציבי\u0004 \u0005[\u0006משמע ש\u0005על דעת העצים],\u0006 אולם אם \u0003שקל רברבי וזוטרי\u0004 \u0005[נוטל גדולים וקטנים]\u0006 — מן הסתם \u0003אדעתא דארעא\u0004 \u0005[על דעת,\u0006 לשם תיקון \u0005הקרקע]\u0006 הוא עושה כן ואסור.","\u0003ואמר רבא: האי מאן דפתח מיא לארעיה\u0004 \u0005[מי שפותח\u0006 את אמת \u0005המים לאדמתו],\u0006 אם עושה כן \u0003אדעתא דכוורי\u0004 \u0005[על דעת\u0006 לצוד \u0005דגים]\u0006 הבאים עם המים — \u0003שרי\u0004 \u0005[מותר],\u0006 ואם עושה כן \u0003אדעתא דארעא\u0004 \u0005[על דעת\u0006 להשקות את \u0005האדמה] —\u0006 \u0003אסיר\u0004 \u0005[אסור].\u0006","\u0003היכי דמי\u0004 \u0005[כיצד זה\u0006 בדיוק\u0005]\u0006 ההבחנה בכך? אם \u0003פתח תרי בבי\u0004 \u0005[שני שערים,\u0006 פתחים\u0005]\u0006 באמת המים, \u0003חד מעילאי וחד מתתאי\u0004 \u0005[אחד מלמעלה ואחד מלמטה]\u0006 שיכנסו המים ויצאו ממנה, הריהו מוכיח בזה כי \u0003אדעתא דכוורי\u0004 \u0005[על דעת\u0006 לצוד \u0005דגים]\u0006 הוא עושה כן, שהמים זורמים החוצה, ורק הדגים נשארים בשדהו, אולם אם \u0003פתח חד בבא\u0004 \u0005[שער,\u0006 פתח, \u0005אחד]\u0006 בלבד — ודאי \u0003אדעתא דארעא\u0004 \u0005[על דעת הקרקע]\u0006 הוא עושה, שרצונו שתתמלא האמה ויעלו המים על גדותיה וישקו את השדה.","\u0003ואמר רבא: האי מאן דפשח דיקלא\u0004 \u0005[מי שמחתך\u0006 את ענפי \u0005הדקל]\u0006 אם עושה כן \u0003אדעתא דחיותא\u0004 \u0005[על דעת\u0006 להאכיל את \u0005הבהמות] —\u0006 \u0003שרי\u0004 \u0005[מותר],\u0006 אולם אם עושה כן \u0003אדעתא דדיקלא\u0004 \u0005[על דעת\u0006 לתקן את \u0005הדקל] —\u0006 \u0003אסיר\u0004 \u0005[אסור].\u0006 \u0003היכי דמי\u0004 \u0005[כיצד זה\u0006 בדיוק\u0005]\u0006 מבחינים בהבדל? אם \u0003שקיל כוליה מחד גיסא\u0004 \u0005[לוקח,\u0006 קוצץ, \u0005הכל מצד אחד] — ודאי\u0006 \u0003אדעתא דחיותא\u0004 \u0005[על דעת\u0006 האכלת \u0005הבהמות]\u0006 הוא עושה כן, שהרי רואים שאינו מקפיד אם יפסיד את הדקל, אולם אם הוא קוצץ \u0003מהאי גיסא ומהאי גיסא\u0004 \u0005[מצד זה ומצד זה]\u0006 — ודאי \u0003אדעתא דדיקלא\u0004 \u0005[על דעת הדקל]\u0006 הוא עושה כן \u0003ואסיר\u0004 \u0005[ואסור].\u0006","\u0003ואמר רבא: הני תמרי תוחלני\u0004 \u0005[תמרים אלה\u0006 שהם עדיין \u0005בוסר] —\u0006 \u0003מיגזרינהו\u0004 \u0005[לחתוך אותם]\u0006 כדי להכשירם לאכילה — \u0003שרי\u0004 \u0005[מותר],\u0006 אולם \u0003מייצינהו\u0004 \u0005[לכבוש אותם]\u0006 — \u0003אסיר\u0004 \u0005[אסור],\u0006 לפי שאין כוונתו לאוכלם במועד אלא להכשירם לשימוש לאחר החג. \u0003רב פפא אמר: כיון דמתלעי\u0004 \u0005[שמתליעים]\u0006 אם לא יטפלו בהם — הרי \u0003כפרקמטיא\u0004 (מסחר) \u0003האבד דמי, ושרי\u0004 \u0005[נחשבים, ומותר],\u0006 ככל מלאכה אחרת שהיא בבחינת דבר האבד שמותר לעשותה בחול המועד.","\u0003ואמר רבא: פרקמטיא כל שהוא, אסור\u0004 בחול המועד. \u0003אמר ר' יוסי בר אבין: ובדבר האבד\u0004 אם לא יעשנו במועד — \u0003מותר.\u0004 אף מסופר: \u0003רבינא הוה ליה ההוא עיסקא דהוה מזדבן בשיתא אלפי\u0004 \u0005[היה לו עסק\u0006 שותפות \u0005שהיה נמכר,\u0006 היה שוה למוכרו \u0005בששת אלפים\u0006 דינרים\u0005],\u0006 \u0003שהייה לזבוניה בתר חולא דמועדא וזבניה בתריסר אלפי\u0004 \u0005[שהה מלמוכרו\u0006 עד \u0005לאחר חול המועד ומכרו בשנים עשר אלפים].\u0006","מסופר: \u0003רבינא הוה מסיק זוזי בבני אקרא דשנואתא\u0004 \u0005[היה נושה זוזים,\u0006 כספים \u0005בבני מבצר שנוואתא],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב אשי אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מהו למיזל האידנא עלייהו\u0004 \u0005[ללכת עכשיו,\u0006 בחול המועד, \u0005עליהם]\u0006 לגבות את החוב? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003כיון דהאידנא\u0004 \u0005[שעכשיו]\u0006 \u0003הוא דמשכחת להו\u0004 \u0005[שאתה מוצא אותם],\u0006 ואילו \u0003ביומי אחריני לא משכחת להו\u0004 \u0005[בימים אחרים אין אתה מוצא אותם],\u0006 שהיו אנשים אלה נודדים במשך השנה למסחרם — הרי זה \u0003כפרקמטיא האבד דמי, ושרי\u0004 \u0005[נחשב, ומותר].\u0006","ומעירים: \u0003תניא נמי גבי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן לענין]\u0006 \u0003עבודה זרה כי האי גוונא\u0004 \u0005[כגון זה],\u0006 ששנינו: \u0003הולכין\u0004"],["\u0003ליריד\u0004 (יום שוק שנקבע ביום המוקדש לפולחן אלילי) \u0003של גוים, ולוקחים\u0004 (קונים) מהם \u0003בהמה, עבדים ושפחות, בתים, שדות וכרמים, וכותב\u0004 שטרות \u0003ומעלה\u0004 אותם \u0003בערכאות שלהן\u0004 מקיים ומאשר את השטרות בבתי המשפט שלהם, ואף שאפשר לראות בכל אלה נתינת כבוד להם ולאלוהיהם, הותר הדבר \u0003מפני שהוא כמציל מידן,\u0004 שהרי בהזדמנות אחרת לא יוכל להשיג את הדברים הללו. משמע שדבר התלוי בזמן קבוע נחשב כדבר האבד.","מסופר: \u0003רב שרא\u0004 \u0005[התיר]\u0006 \u0003לחייא בר אשי למיגדל אוהרי בחולא דמועדא\u0004 \u0005[לקלוע רשתות בחול המועד].\u0006 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003מעשה הדיוט הוא,\u0004 שקליעה זו איננה מלאכת אומנות, אלא דבר שכל אדם יכול לעשות, \u0003אבל איזלי\u0004 \u0005[מכמורות מורכבות]\u0006 — \u0003אסור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003מעשה אומן הוא.\u0004","מסופר: \u0003רב יהודה שרא\u0004 \u0005[התיר]\u0006 \u0003לאמי תנורא\u0004 \u0005[עושה התנורים]\u0006 \u0003למיגדל תנורי\u0004 \u0005[לקלוע,\u0006 לייצר \u0005תנורים],\u0006 \u0003ולרבה בר עשבי\u0004 התיר \u0003למיגדל מהולתא\u0004 \u0005[לקלוע נפות].\u0006 ושואלים: \u0003איני\u0004 \u0005[וכן הוא]?\u0006 \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003רבה בר שמואל\u0004 ברייתא זו: \u0003ושוין שאין גודלין תנור לכתחילה!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה];\u0006 \u0003כאן בימות החמה\u0004 בחול המועד פסח, שהתנור יכול להתייבש עוד בתוך הרגל ויוכלו לאפות בו פת לצורך הרגל — מותר לעשותו בחול המועד, \u0003כאן בימות הגשמים\u0004 בחול המועד סוכות, שהתנור ודאי לא יתייבש ולא יהיה מוכן לאפיה בתוך הרגל — אסור לעשותו בחול המועד.","\u0003עושין מעקה לגג ולמרפסת\u0004 כאשר הוא \u0003מעשה הדיוט\u0004 לא מלאכה מקצועית, אלא עבודה גסה שכל אחד יכול לעשותה, \u0003אבל לא מעשה אומן. שפין את הסדקין\u0004 שבתנור \u0003ומעגילין אותן במעגילה\u0004 שהוא כלי עץ שבו מחליקים חימר, ומעגלים \u0003ביד וברגל אבל לא במחלצים\u0004 (כף סיידים), שהיא הכלי המיוחד להחלקה זו.","\u0003הציר\u0004 של דלת, \u0003והצינור\u0004 (החור שהציר נכנס בו), \u0003והקורה\u0004 המחזיקה את הדלת, \u0003והמנעול והמפתח שנשברו — מתקנן במועד\u0004 משום שכולם דברים נחוצים ביותר ואי אפשר לדחותם, \u0003ובלבד שלא יתכוין\u0004 מראש \u0003לעשות מלאכתו במועד\u0004 וידחה תיקונים אלה עד לאותה שעה.","\u0003וכל כבשין\u0004 (מאכלים כבושים) שזמן כבישתם קצר, \u0003שהוא יכול\u0004 יכול להספיק ו\u0003לאכול מהן במועד — כובשן\u0004 אף בימי חול המועד.","שואלים: \u0003היכי דמי\u0004 \u0005[כיצד זה בדיוק]\u0006 \u0003מעשה הדיוט\u0004 בבניה? \u0003רב יוסף אמר: בהוצא ודפנא\u0004 \u0005[ב\u0006ענפי \u0005דקל ודפנה]\u0006 שאיננו עושה מבנה של ממש. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003צר בצרור ואינו טח בטיט\u0004 שמסדר את האבנים (הצרורות), אבל אינו טח אותן בטיט.","שנינו במשנה: \u0003שפין את הסדקין ומעגילין אותן במעגילה\u0004 ביד וברגל אבל לא במחלציים. ותוהים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003במעגילה\u0004 הרי \u0003אמרת\u0004 כי \u0003שרי\u0004 \u0005[מותר]\u0006 — \u0003ביד וברגל מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שמותר? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003שפין את הסדקין ומעגילין אותן כעין מעגילה\u0004 ולא במעגילה ממש, אלא בעבודה משוכללת \u0003ביד וברגל, אבל לא במחלצים\u0004 שהוא כלי אומנות המיוחד לכך.","שנינו במשנה ש\u0003הציר והצינור והקורה והמנעול והמפתח שנשברו מתקנן במועד. ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003עד ימיו\u0004 של יוחנן כהן גדול \u0003היה פטיש מכה בירושלים\u0004 בחול המועד, שהיו עובדים בנפחות בדבר האבד, והוא אסר וביטל מלאכה זו. ונדייק: \u0003עד ימיו — אין\u0004 \u0005[כן],\u0006 אולם \u0003מכאן ואילך\u0004 — \u0003לא,\u0004 משמע שכל מלאכת אומנות כעין זו אסורה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 שאסרו, הרי זה \u0003בדנפחי\u0004 \u0005[ב\u0006מלאכת \u0005נפחים],\u0006 שקולם נשמע ביותר, \u0003כאן\u0004 שהותר, הרי זה \u0003בדנגרי\u0004 \u0005[ב\u0006מלאכת \u0005נגרים]\u0006 שאין משמיעים קול גדול\u0005.\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חסדא: יאמרו\u0004 איפוא, \u0003קלא רבה\u0004 \u0005[קול גדול] —\u0006 \u0003אסיר\u0004 \u0005[אסור],\u0006 \u0003קלא זוטר\u0004 \u0005[קול קטן] —\u0006 \u0003שרי\u0004 \u0005[מותר]\u0006 אפילו כשאין צורך! \u0003אלא אמר רב חסדא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שהתירו — הרי זה \u0003במגלי\u0004 \u0005[במגלים],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאסרו — הרי זה \u0003בחציני\u0004 \u0005[במפסלות],\u0006 שכיון שהמגלים אינם עושים רעש כלל התירו. \u0003רב פפא אמר: כאן\u0004 במשנתנו — הרי זה \u0003קודם גזירה\u0004 שגזר יוחנן כהן גדול, \u0003כאן\u0004 בברייתא — הרי זה \u0003לאחר גזירה.\u0004","\u0003רב אשי אמר: הא\u0004 \u0005[זו]\u0006 ששנו שיש בכך איסור — הרי זה כדעת \u0003ר' יהודה. הא\u0004 \u0005[זו]\u0006 משנתנו — כדעת \u0003ר' יוסי.\u0004 ש\u0003אמר ר' יצחק בר אבדימי: מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 \u0003תנא\u0004 זה הסבור כי צריך לעשות \u0003שינוי\u0004 בכל מלאכה הנעשית \u0003ב\u0004חול ה\u0003מועד\u0004 אפילו \u0003בדבר האבד — דין זה הוא\u0004 ש\u0003לא\u0004 כשיטת \u0003ר' יוסי,\u0004 שכן ר' יוסי מתיר במלאכת דבר האבד לעשותה כדרכה (להלן מועד קטן דף יב,א).","\u0003אמר רבינא: כמאן מדלינן האידנא קביותא דדשא בחולא דמועדא\u0004 \u0005[כ\u0006שיטת \u0005מי אנחנו מגביהים עתה את המשקוף ש\u0006מעל \u0005הדלת\u0006 ותוקעים בו מסמרים שיצאו בלי שינוי \u0005בחול המועד],\u0006 \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 — \u0003כר' יוסי\u0004 שהתיר בדבר האבד.","שנינו במשנה: \u0003כבשין שהוא יכול לאכול במועד — כובשן.\u0004 מסופר: הנהר \u0003בדיתא לבאי כוורי\u0004 \u0005[גרף\u0006 ממימיו \u0005דגים]\u0006 בחול המועד, \u0003אזיל כולי עלמא צוד אייתו כוורא\u0004 \u0005[הלכו כל העולם,\u0006 הכל, \u0005צדו והביאו דגים],\u0006 \u0003שרא להו\u0004 \u0005[התיר להם]\u0006 \u0003רבא למימלח מינייהו\u0004 \u0005[למלוח מהם].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כבשין שהוא יכול לאכול מהן במועד — כובשן,\u0004 והלא דגים מרובים אלו לא יוכלו להיאכל במועד ואין איפוא להתיר את כבישתם! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003כיון דמעיקרא\u0004 \u0005[שמתחילה]\u0006 דגים אלו \u0003אדעתא דאכילה אייתינהו\u0004 \u0005[על דעת לאכול\u0006 מהם מיד \u0005הביאום]\u0006 אלא שנתברר שהביאו יותר מכדי צורך אכילה, ועוד, \u0003ואי שביק להו פסדי\u0004 \u0005[ואם נניח להם\u0006 בלא מליחה \u0005ייפסדו],\u0006 אם כן \u0003כפרקמטיא האבד דמי, ושרי\u0004 \u0005[כסחורה האבודה\u0006 הם \u0005נחשבים, ומותרים].\u0006","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שלא כך היה המעשה, אלא \u0003שרי להו\u0004 \u0005[התיר להם]\u0006 \u0003רבא מיצד מיזל אייתויי ומימלח\u0004 \u0005[לצוד\u0006 את הדגים \u0005להביא\u0006 אותם \u0005ולמלוח\u0006 אותם\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003כבשין שהוא יכול לאכול מהן\u0004 במועד \u0003כובשן תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 ודגים אלו שנמלחו הרבה אינם ראויים לאכילה עד שיתייבשו היטב! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני נמי מיתאכלי אגב איצצא\u0004 \u0005[אלה גם כן\u0006 אשר מלחו כעת \u0005נאכלים,\u0006 יכולים להיאכל \u0005על ידי סחיטה\u0006 ולחיצה\u0005]\u0006 שיוציאו מהם את המלח והציר ויאכלם, ואם כן ראויים אף הם במועד. \u0003כי הא\u0004 \u0005[כמו\u0006 המעשה \u0005הזה]\u0006 ש\u0003שמואל עבדו ליה שיתין איצצי\u0004 \u0005[עשו לו\u0006 על ידי \u0005שישים סחיטות]\u0006 \u0003ואכל\u0004 דגים מלוחים שנכבשו זה עתה. מסופר: \u0003רבא איקלע לבי ריש גלותא עבדי ליה שיתין איצצי\u0004 \u0005[נזדמן לבית ראש הגולה\u0006 ו\u0005עשו לו שישים סחיטות]\u0006 \u0003ואכל.\u0004","","כיון שדובר בענין אכילת דגים בצורות שונות, מספרים: \u0003רב איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב שפיר, אייתו לקמייהו ההוא כוורא תילתא בישולא תילתא מילחא ותילתא טוויא\u0004 \u0005[הביאו לפניהם דג שהיה שליש מבושל שליש מלוח ושליש צלוי].\u0006","\u0003אמר רב: אמר לי אדא ציידא\u0004 \u0005[הצייד],\u0006 \u0003כוורא סמוך למיסרחיה מעלי\u0004 \u0005[דג סמוך לסרחונו\u0006 כאשר שהה זמן מסויים \u0005הוא מעולה].\u0006 \u0003ואמר רב: אמר לי אדא ציידא: כוורא, טווייא באחוה\u0004 \u0005[דג, צלה אותו באחיו\u0006 במלח, שאף הוא בא מן המים\u0005],\u0006 \u0003אסוקיה באבוה\u0004 \u0005[העלהו באביו\u0006 במים שמהם הוא בא\u0005],\u0006 \u0003מיכלי בבריה\u0004 \u0005[אכול אותו עם בנו]\u0006 עם ציר דגים, \u0003אשתי עליה אבוה\u0004 \u0005[ושתה עליו\u0006 מ\u0005אביו,\u0006 שתה מים לאחריו\u0005].\u0006 \u0003ואמר רב, אמר לי אדא ציידא: כוורא תחלי וחלבא\u0004 \u0005[דגים שחליים וחלב]\u0006 \u0003ליטעון גופא ולא ליטעון פוריא\u0004 \u0005[שיטען אותם הגוף ושלא תטען אותם המיטה],\u0006 כלומר, טוב להלך קצת לאחר אכילתם ולא ללכת מיד לישון. \u0003ואמר רב, אמר לי אדא ציידא:\u0004 אחרי אכילת \u0003כוורא תחלי וחלבא\u0004 \u0005[דגים שחליים וחלב]\u0006 מוטב לשתות \u0003מיא\u0004 \u0005[מים]\u0006 \u0003ולא שיכרא\u0004 \u0005[שיכר],\u0006 ואם אין לו מים ישתה \u0003שיכרא\u0004 \u0005[שיכר]\u0006 \u0003ולא חמרא\u0004","",""],["\u0003מי שהפך את זיתיו,\u0004 שלפני כבישת הזיתים בבית הבד מניחים אותם בערימה זמן מסויים כדי שיתרככו, והופכים אותם, ואחר כך צריך להביאם מהר ככל האפשר לכבישה, \u0003ו\u0004אם \u0003אירעו אבל\u0004 שאינו רשאי לעשות מלאכה בזמן אבלותו, \u0003או\u0004 שאירעו \u0003אונס\u0004 כלשהו שלא יכול לעשות את הדבר לפני החג, \u0003או שהטעוהו פועלים\u0004 שאמרו שיבואו ולא באו — \u0003טוען קורה ראשונה\u0004 שרשאי הוא להכניס את הזיתים לבית הבד ולטעון את הקורה במשקולות, כדי שיצא השמן מן הזיתים בכבישה ראשונה \u0003ומניחה\u0004 לגמור מלאכתה \u0003לאחר המועד,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' יוסי אומר: זולף\u0004 (סוחט) \u0003וגומר, ו\u0004אחר כך \u0003גף\u0004 (שם את המגופה על חביות השמן) \u0003כדרכו,\u0004 שכיון שהוא דבר האבד לא הצריכו חכמים לעשות בו אף שינויים אלה.","תחילה תוהים על הצירוף: \u0003פתח\u0004 התנא \u0003באבל וסיים במועד\u0004 שהרי משנתנו פותחת במקרה של אבל ומסיימת בדיני מועד ולא מובן מה היחס בין הדינים הללו. \u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי:\u0004 כל המשנה עוסקת בדיני חול המועד, ומסבירה שאם לא יכול אדם לעשות את מלאכתו לפני המועד, מפני אבילות או אונס אחר, הרי זה רשאי לסיימה במועד כדי שלא יהא בכך הפסד מרובה. \u0003זאת אומרת: דברים המותרין במועד, אסורים בימי אבלו,\u0004 ולכן נחשב לו האבל שלפני המועד כאונס, שאינו יכול לעשות בו כל מלאכה, אבל עושה אותה במועד.","\u0003רב אשי אמר:\u0004 לא כך פירוש המשנה אלא בסגנון \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003קאמר\u0004 \u0005[נאמרה\u0006 משנתנו\u0005],\u0006 והיא מדברת בשתי הלכות שונות. וכך יש להבין את הדברים: בקטע ראשון מדובר בדין אבילות (ללא קשר עם המועד) \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003בימי אבלו\u0004 שאיסור מלאכה בהם \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003הוא ושרי\u0004 \u0005[ומותר]\u0006 לעשות מלאכה של דבר האבד, \u0003אלא אפילו במועד\u0004 ש\u0003איסור מלאכה\u0004 שבו הוא \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 בכל זאת \u0003במקום פסידא\u0004 \u0005[הפסד]\u0006 \u0003שרו רבנן\u0004 \u0005[התירו חכמים].\u0006","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי,\u0004 וזו לשונה: \u0003אלו דברים העושין לאבל בימי אבלו:\u0004 היו \u0003זיתיו הפוכין — טוענין לו\u0004 אותם אחרים בבית הבד, \u0003ו\u0004כך \u0003כדו\u0004 שצריך \u0003לגוף\u0004 במגופה \u0003ופשתנו\u0004 כשצריך \u0003להעלות\u0004 אותו \u0003מן המשרה\u0004 ששורים אותו במים לפני ניפוצו, ואם לא יוציאוהו יירקב, \u0003וצמרו להעלות מן היורה\u0004 שהכניסו אותו כדי לצבוע אותו, \u0003ומרביצים\u0004 (משקים מעט) את \u0003שדהו משתגיע עונת המים שלו,\u0004 שבמקומות רבים היה שדה אחר שדה לפי תור מקבל מים מן המעין או הנהר, ואם לא ישתמש במים יפסיד את התור להשקאה. ומכאן ראיה לרב שישא שאפילו דבר האבד אסור לאבל לעשות בעצמו אלא על ידי אחרים בלבד.","\u0003ר' יהודה אומר: אף זורעין לו שדה ניר\u0004 (שדה שהיה כבר חרוש) \u0003ו\u0004כן \u0003שדה העומדת לפשתן\u0004 כאשר זמן הזריעה הוא חשוב ביותר, ואם יזרע השדה במאוחר יהיה בכך הפסד. \u0003אמרו לו\u0004 חכמים: \u0003אם לא תזרע\u0004 אותה שדה ניר \u0003בבכיר\u0004 (בעונה מוקדמת) \u0003תזרע באפל\u0004 (בעונה מאוחרת יותר), וכן \u0003אם לא תזרע פשתן — תזרע ממין אחר,\u0004 ולכן אין זה נחשב הפסד מרובה ולא התירו לו.","\u0003רבן שמעון בן גמליאל אומר:\u0004 היו \u0003זיתיו הפוכין ואין שם אומן\u0004 היודע לכבוש אותם \u0003אלא הוא, כדו\u0004 צריך \u0003לגוף ואין שם אומן אלא הוא, פשתנו להעלות מן המשרה, וצמרו להעלות מן היורה ואין שם אומן אלא הוא — הרי זה יעשה\u0004 בעצמו \u0003בצינעא.\u0004","\u0003יתר על כן אמר רבן שמעון בן גמליאל: אם היה\u0004 אותו אבל \u0003אומן לרבים\u0004 במלאכה הנחוצה להם, או \u0003ספר\u0004 או \u0003בלן לרבים, והגיע עת הרגל\u0004 ערב יום טוב, \u0003ואין שם אומן\u0004 באותה מלאכה \u0003אלא הוא — הרי זה יעשה\u0004 מלאכתו אפילו בפרהסיא, שצורך הרבים דוחה את אבלו של אדם פרטי.","\u0003האריסין\u0004 המעבדים שדה תמורת אחוז מסויים מן היבול \u0003והחכירין\u0004 החוכרים שדה עבור כמות תבואה ידועה, \u0003והקבלנין\u0004 המקבלים על עצמם עבודה מסויימת בסכום קצוב בשדות אחרים — \u0003הרי אלו יעשו אחרים בשבילן\u0004 את מלאכתם בימי האבל. \u0003החמרין הגמלין והספנין — הרי אלו לא יעשו\u0004 מלאכתם בזמן האבל, \u0003ואם היו\u0004 הם או בהמותיהם \u0003מוחכרין או מושכרין אצל אחרים — הרי אלו יעשו\u0004 לפי ששכירה זו היתה אישית ואין אחר יכול למלא את מקומם. \u0003שכיר יום אפילו\u0004 היה \u0003בעיר אחרת\u0004 שאין יודעים בה שהוא בימי אבלו, מכל מקום \u0003לא יעשה. היתה מלאכת אחרים בידו, אף על פי שבקיבולת\u0004 (שעובד בקבלנות, ולא בימים ידועים, אלא מקבל שכר על המלאכה הגמורה) — \u0003לא יעשה.\u0004","על משפט אחרון זה תוהים מיד: \u0003אף על פי שבקיבולת, ולא מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 \u0003שאינה קיבולת\u0004 שהיא אסורה?! \u0003אדרבה\u0004 (להיפך), \u0003קיבולת כדידיה דמי\u0004 \u0005[כשלו\u0006 היא \u0005נחשבת],\u0006 שהרי אינו מחוייב לגומרה בזמן מסויים והוא מקבל אותה לפי שכרו בעבודה ויש לאסור, ואם אינה בקיבולת יש להתיר! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן את הלשון כך: \u0003בין קיבולת בין שאינה קיבולת — לא יעשה.\u0004","\u0003היתה מלאכתו ביד אחרים\u0004 והם צריכים לעשות עבורו, אם היה הדבר \u0003בביתו — לא יעשו\u0004 מלאכה, \u0003בבית אחר — יעשו.\u0004","מסופר: \u0003מריון בריה\u0004 \u0005[בנו]\u0006 של \u0003רבין, ומר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא הוה להו ההוא גמלא דתורא בהדי הדדי\u0004 \u0005[היה להם צמד שוורים יחד\u0006 בשותפות\u0005],\u0006 שור לכל אחד, \u0003איתרעא ביה מילתא\u0004 \u0005[אירע בו דבר]\u0006 של אבילות \u0003במר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא ופסקיה לגמליה\u0004 \u0005[והוציא את צמדו]\u0006 את השור שלו מן הצמד, שלא רצה שתיעשה מלאכה ברכושו בימי אבלו ונמצא שאי אפשר היה עוד לחרוש באותו צמד. \u0003אמר רב אשי\u0004 בתמיהה: \u0003גברא רבה\u0004 \u0005[אדם גדול]\u0006 \u0003כמר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אחא עביד הכי\u0004 \u0005[עושה כך]?\u0006 \u0003נהי דלפסידא דידיה לא חייש, אדאחרים לא חייש\u0004 \u0005[אם אמנם להפסד של עצמו אינו חושש,\u0006 הגם להפסד \u0005של אחרים אינו חושש]?!\u0006 והרי נמצא שותפו מפסיד על ידי כך! \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אם היו מושכרין או מוחכרין אצל אחרים — הרי אלו יעשו!\u0004 ומדוע לא ימשיך השותף לעבוד בבהמתו של מר בר רב אחא?","ומעירים, \u0003הוא\u0004 מר בנו של רב אחא \u0003סבר: אדם חשוב שאני\u0004 \u0005[שונה]\u0006 שמעיקר הדין מותר הדבר, אבל אדם חשוב צריך לדקדק יותר, שלא ילמדו ממנו לזלזל בהלכה."],["\u0003אמר שמואל: מקבלי קיבולת\u0004 (שעובדים בקבלנות, ולא בימים ידועים, אלא מקבלים שכר על המלאכה הגמורה) גוים, שעושים עבודה עבור ישראל, ורצונם לעשותה ביום שאסור במלאכה, אם היו עושים \u0003בתוך התחום\u0004 (תחום שבת) — \u0003אסור\u0004 להניח להם לעבוד, שכן אנשים רואים שעושים מלאכתו של ישראל זה ביום אסור, וחושדים בו שבו ביום נתן להם. \u0003חוץ לתחום\u0004 שאין ישראל הולכים לשם — \u0003מותר.\u0004","\u0003אמר רב פפא: ואפילו חוץ לתחום לא אמרן\u0004 \u0005[אמרנו]\u0006 שמותר \u0003אלא דליכא מתא דמקרבא להתם\u0004 \u0005[שאין עיר\u0006 אחרת \u0005שקרובה לשם],\u0006 \u0003אבל\u0004 אם \u0003איכא מתא דמקרבא להתם\u0004 \u0005[יש עיר שקרובה לשם]\u0006 — \u0003אסור,\u0004 שהרי הישראלים באותה עיר עלולים לראות זאת.","\u0003אמר רב משרשיא: וכי ליכא מתא דמקרבא להתם\u0004 \u0005[וכאשר אין עיר שקרובה לשם]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שמותר \u0003אלא בשבתות ובימים טובים, דלא שכיחי אינשי דאזלי להתם\u0004 \u0005[שאין מצויים אנשים שהולכים לשם]\u0006 ומשום כך לא יראו בעשיית המלאכה ולא יבואו לידי חשד, \u0003אבל בחולו של מועד, דשכיחי אינשי דאזלי ואתו להתם\u0004 \u0005[שמצויים אנשים שהולכים ובאים לשם]\u0006 ויראו שנעשית מלאכתו — \u0003אסור.\u0004","מסופר: \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן בנו ליה\u0004 \u0005[לו]\u0006 \u0003אפדנא\u0004 \u0005[ארמון]\u0006 גוים שהיו \u0003מקבלי קיבולת,\u0004 והיה זה \u0003חוץ לתחום\u0004 ועבדו גם בשבתות. לאחר זמן \u0003איקלע\u0004 \u0005[הזדמן]\u0006 לשם \u0003רב ספרא ורב הונא בר חיננא, ולא עלו לגביה\u0004 \u0005[נכנסו אליו],\u0006 מפני שלא רצו להשתמש בדבר שנעשה באיסור. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ש\u0003הוא\u0004 עצמו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא על בגוויה\u0004 \u0005[נכנס לתוכו].\u0006","ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: מקבלי קיבולת, בתוך התחום אסור, חוץ לתחום מותר,\u0004 וארמון זה הלא נבנה מחוץ לתחום! ומשיבים: \u0003אדם חשוב שאני\u0004 \u0005[שונה]\u0006 וצריך להקפיד יותר. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003סיועי סייע בתיבנא בהדייהו\u0004 \u0005[היה, מסייע\u0006 מספק \u0005תבן\u0006 יחד \u0005אתם]\u0006 לצורך עשיית הלבנים לבנין, וכיון שכך לא היו מקבלי הקיבולת עצמאיים לגמרי אלא היו כשכירים, ולכן יש בכך איסור.","מסופר: \u0003רב חמא שרא להו לאבונגרי דבי ריש גלותא למיעבד להו עבידתא בחולא דמועדא\u0004 \u0005[התיר להם למלצרים של בית ראש הגולה לעשות להם עבודה בחול המועד],\u0006 \u0003אמר\u0004 בנימוק להיתר זה: \u0003כיון דאגר לא קא שקלי\u0004 \u0005[ששכר\u0006 העבודה \u0005אינם לוקחים],\u0006 \u0003שרשויי\u0004 \u0005[\u0006רק \u0005רווח וטובת\u0006 הנאה\u0005]\u0006 \u0003הוא דקא משרשו ליה\u0004 \u0005[שהם נהנים],\u0006 שמלצרים אלה היו באים ומסייעים בעבודה תמורת מזונם, ולכן אין לראות זאת כמלאכה של ממש, \u0003ולית לן\u0004 \u0005[ואין לנו]\u0006 \u0003בה\u0004 איסור.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מקבלין קיבולת במועד,\u0004 כלומר, מותר לקבוע ולהזמין עבודה קבלנית במועד על מנת \u0003לעשותה לאחר המועד, ובמועד\u0004 עצמו \u0003אסור. כללו של דבר: כל שהוא\u0004 מותר להיות \u0003עושה\u0004 בעצמו — \u0003אומר לגוי ועושה, וכל שאינו עושה\u0004 בעצמו — \u0003אינו אומר לגוי ועושה. תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003מקבלין קיבולת במועד לעשותה לאחר המועד, ובלבד שלא ימדוד, ושלא ישקול, ושלא ימנה,\u0004 כדי לתכנן את העבודה, \u0003כדרך שהוא עושה בחול.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מרביעין\u0004 (כלומר, מחזיקים ומסייעים בהרבעה) של \u0003בהמה בחולו של מועד\u0004 שהדבר דומה למלאכה. \u0003כיוצא בו אין מרביעין בבכור ולא בפסולי המוקדשין\u0004 (בהמות שהוקדשו לקרבן ונפל בהן מום) שנראה כאילו עושים בהן עבודה.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אין מרביעין בהמה בחולו של מועד, ר' יהודה אומר: חמורה שתבעה\u0004 (שהגיע זמן היחום שלה) — \u0003מרביעין עליה זכר בשביל שלא תצטנן\u0004 (תעבור תקופת היחום שלה), ואם לא הורבעה בזמנה יש בכך הפסד מרובה, \u0003ושאר כל הבהמות\u0004 שנתייחמו — \u0003מכניסין אותן לבקרות\u0004 (מקומות מגודרים) שיש בהם זכרים ושם אין צורך שיסייע אדם בכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מדיירין\u0004 אין מוליכים בהמות ממקום למקום בשדה כדי שאגב כך תוזבל השדה \u0003לא בשבתות, ולא בימים טובים, ולא בחולו של מועד. ואם באו מאליהן — מותר\u0004 ואינו צריך לגרשן, אף שנמצא נהנה מן הזבל.","\u0003ו\u0004אולם \u0003אין מסייעין אותן\u0004 את הרועים הגוים, \u0003ואין מוסרין להם שומר לנער\u0004 (להסיע, להזיז) \u0003את צאנם\u0004 ממקום למקום. \u0003היה\u0004 הפועל הגוי \u0003שכיר שבת\u0004 (שבוע), \u0003שכיר חדש, שכיר שנה, שכיר שבוע\u0004 (שבע שנים) — \u0003מסייעין אותן, ומוסרין להם שומר לנער את צאנם\u0004 כיון שנשכר לזמן מרובה אינו כעושה מלאכה ביום זה בלבד. \u0003רבי אומר: בשבת\u0004 עושים זאת \u0003בטובה,\u0004 כלומר, רק עבור טובה, אבל בלא לקבל שכר אחר, \u0003ביום טוב\u0004 מותר לעשות זאת גם אם מקבל \u0003מזונות\u0004 עבור כך, ואילו \u0003במועד\u0004 אפילו \u0003בשכר. אמר רב יוסף: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרבי\u0004 בענין זה.","\u0003וכן מי שהיה יינו בתוך הבור\u0004 לאחר שנדרכו הענבים בגת וצריך כבר להוציאו משם \u0003ואירעו אבל, או אונס, או שהטעוהו\u0004 הפועלים, שאמרו שיבואו לעשות מלאכתו ולא באו, ולא הספיק להוציאם בחזרה בערב החג — \u0003זולף\u0004 מוציא את היין \u0003וגומר, וגף\u0004 (סותם את החביות במגופה) \u0003כדרכו,\u0004 אלו \u0003דברי ר' יוסי. ר' יהודה אומר:\u0004 אינו סותם כדרכו אלא \u0003עושה לו\u0004 לבור היין \u0003לימודים\u0004 (כיסוי של קרשים) \u0003בשביל שלא יחמיץ\u0004 היין.","ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכה]\u0006 גם משנה זאת וגם המשנה הקודמת למרות שלכאורה עניינן אחד. \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק \u0005את הראשונה],\u0006 היינו אומרים כי \u0003ב\u0004משנה \u0003ההיא,\u0004 הראשונה \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' יוסי\u0004 שמותר \u0003משום דמישחא נפיש פסידיה\u0004 \u0005[ששמן מרובה הפסדו]\u0006 אם לא יוציאנו בזמן, שדמי השמן מרובים, \u0003אבל חמרא דלא נפיש פסידיה\u0004 \u0005[יין שאין הפסדו מרובה],\u0006 \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לר' יהודה\u0004 שיש לעשות בשינוי, \u0003ואי אשמעינן בתרייתא\u0004 \u0005[ואילו היה משמיע לנו\u0006 רק את המשנה \u0005האחרונה]\u0006 היינו אומרים: \u0003ב\u0004משנה \u0003ההיא\u0004 האחרונה \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' יהודה\u0004 שיש להחמיר, \u0003אבל בהך\u0004 \u0005[בזו]\u0006 הראשונה \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה\u0004 רבי יהודה \u0003לר' יוסי\u0004 שיש להקל, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שתיהן.","\u0003אמר רב יצחק בר אבא: מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 \u0003תנא\u0004 זה הסבור שעושים \u0003שינוי במועד\u0004 אפילו \u0003בדבר האבד —\u0004 שיטתו היא ש\u0003לא כ\u0004שיטת \u0003ר' יוסי. אמר רב יוסף: הלכה כר' יוסי.\u0004","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 \u0003מרב נחמן בר יצחק: מהו למישע חביתא דשיכרא בחולא דמועדא\u0004 \u0005[לטוח חבית שיכר בחול המועד]?\u0006 שכן אם אין טחים אותה השיכר שותת מדפנות הכלי. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003סיני\u0004 (כינוי לרב יוסף שהיה גדול בבקיאותו בתורה ולכן נקרא \"סיני\") \u0003אמר: הלכה כר' יוסי.\u0004 ותוהים: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' יוסי בחמרא\u0004 \u0005[ביין],\u0006 אבל \u0003בשיכרא מי\u0004 \u0005[בשיכר האם]\u0006 \u0003אמר,\u0004 שהרי השיכר זול בהרבה מן היין!","ודוחים: \u0003חמרא טעמא מאי\u0004 \u0005[יין מה טעם]\u0006 התירו לעשות בו מלאכה — \u0003משום דנפיש פסידיה\u0004 \u0005[שמרובה הפסדו],\u0006 \u0003שיכרא נמי אית בה פסידא\u0004 \u0005[שיכר גם כן יש בו הפסד]\u0006 אם אין הכלי ניטוח כראוי. כפי ש\u0003אמר אביי: אמרה לי אם\u0004 (אמי, אומנתי): טוב כד \u0003בר שית סאוי ושייע\u0004 \u0005[בן שש סאים ש\u0006הוא \u0005משוח],\u0006 \u0003מבר תמני ולא שייע\u0004 \u0005[מבן שמונה\u0006 סאים \u0005שאינו משוח],\u0006 שבסופו של דבר בגלל המשיחה ישאר בכד הקטן יותר שיכר מאשר בכד הגדול.","\u0003אמר רב חמא בר גוריא אמר רב: הלכות מועד\u0004 הן \u0003כהלכות כותים\u0004 (השומרונים) \u0003בהלכה.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה],\u0006 כלומר, מהו צד הדמיון בין הלכות הנוגעות בכותים, ובין הלכות חול המועד? \u0003אמר רב דניאל בר קטינא: לומר שהן עקורות\u0004 (עקרות, שאינן עושות פירות), כלומר \u0003ואין למידות זו מזו\u0004 שיש לראות את ההלכות הללו כגזירות בודדות, שכל אחת נידונה לגופה, ואין ללמוד זו מזו. ודוגמה לדבר, ש\u0003אמר\u0004","\u0003שמואל: זופתין\u0004 (מושחים בזפת) \u0003כוזתא\u0004 \u0005[כד קטן]\u0006 כדי שלא ישתות, \u0003ואין זופתין חביתא\u0004 \u0005[חבית\u0006 גדולה\u0005].\u0006 ואילו \u0003רב דימי מנהרדעא אמר: זופתין חביתא ואין זופתין כוזתא.\u0004 ומסבירים את הטעמים \u0003מר חייש לפסידא\u0004 \u0005[חכם זה\u0006 רב דימי \u0005חשש להפסד]\u0006 יותר ולכן התיר לזפת כלי גדול שהפסדו מרובה ולא קטן, \u0003ומר חייש לטירחא\u0004 \u0005[וחכם זה\u0006 שמואל \u0005חשש לטירחה]\u0006 יותר ולכן התיר בקטן שטירחתו מועטה ולא בגדול, הרי שני עניינים דומים מאוד, שבכל זאת אין משוים אותם זה לזה.","כלל אחר \u0003אמר אביי: נקטינן\u0004 \u0005[מוחזקים אנו]\u0006 \u0003הלכות מועד כהלכות שבת;\u0004"],["\u0003יש מהן פטור אבל אסור, ויש מהן מותר לכתחלה.\u0004","מסופר: \u0003רב הונא חצדו ליה חצדא במועדא\u0004 \u0005[קצרו לו קציר בחול המועד].\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבה בר רב הונא ל\u0004אביו \u0003רב הונא:\u0004 שנינו, \u0003טוחנין קמח במועד לצורך המועד, ושלא לצורך המועד — אסור,\u0004 וכן \u0003דבר שאבוד במועד — מותר לעשותו במועד, דבר שאינו אבוד במועד — אסור.\u0004","\u0003במה דברים אמורים ב\u0004דברים ה\u0003תלושין מן הקרקע, אבל\u0004 דבר ה\u0003מחובר לקרקע — אפילו כולו אבוד אסור. ואם אין לו מה יאכל\u0004 אז מותר הכל: \u0003קוצר ומעמר, ודש, וזורה\u0004 התבואה ברוח \u0003ובורר\u0004 החיטים מן המוץ \u0003וטוחן\u0004 אותם לקמח, \u0003ובלבד שלא ידוש בפרות\u0004 שהיא הדרך שבה עושים דישה גדולה בימות החול. הרי שכשיש לו מה לאכול, אסור לקצור אף בדבר האבוד לגמרי, ומדוע אם כן הורה רב הונא לקצור במועד והרי בודאי היה לו מה לאכול!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: שיטה זו דעת \u0003יחידאה\u0004 \u0005[יחיד]\u0006 \u0003היא, ולא סבירא לן כוותיה\u0004 \u0005[ואין אנו סבורים כמותו],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003כלל אמר רבן שמעון בן גמליאל משום\u0004 (בשם) \u0003ר' יוסי: דבר התלוש מן הקרקע, אפילו מקצתו אבוד — מותר, והמחובר לקרקע אפילו כולו אבוד — אסור.\u0004 ואם כן רואים אנו שדעה זו, שכל מלאכה במחובר לקרקע אסורה לגמרי, הובאה כדעת יחיד — כדעתו של ר' יוסי בלבד, ולא הודו לו חכמים.","על הסברו זה של רב הונא שואלים: \u0003ואי\u0004 \u0005[ואם\u0006 שיטת\u0005]\u0006 \u0003ר' יוסי\u0004 היא הברייתא המתירה עבודה במחובר לקרקע רק אם אין לו מה לאכול, אם כן כשאין לו מה לאכול והותר לו \u0003ידוש נמי\u0004 \u0005[גם כן]\u0006 \u0003בפרות?! הא\u0004 \u0005[הרי]\u0006 \u0003אמר רב יצחק בר אבא: מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 \u0003תנא\u0004 זה הסבור שיש לעשות \u0003שינוי במועד בדבר האבד —\u0004 ש\u0003לא כ\u0004שיטת \u0003ר' יוסי,\u0004 הרי שלשיטת רבי יוסי אין צורך בשינוי ומדוע אם כן אמר התנא שישנה ולא ידוש בפרות?","ודוחים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]:\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0003כיון דכל יומא לאו\u0004 \u0005[שבכל יום לא]\u0006 \u0003בפרות דיישי\u0004 \u0005[דשים],\u0006 \u0003האידנא נמי לאו\u0004 \u0005[עכשיו גם כן לא]\u0006 \u0003שינוי הוא,\u0004 וכיון שרגילים לדוש גם באופן זה, אין צורך לעשות במועד דווקא בפרסום גדול.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003טוחנין במועד לצורך המועד, ושלא לצורך המועד — אסור. ואם טחן\u0004 במועד לצורך, \u0003והותיר — הרי זה מותר\u0004 לאוכלו לאחר המועד. וכן \u0003קוצצין עצים במועד לצורך המועד, ושלא לצורך המועד — אסור, ואם קצץ והותיר — הרי זה מותר\u0004 לשימוש אחר החג.","\u0003מטילין שכר\u0004 (מכניסים את הפירות למים כדי שיתססו וייעשה מהם שיכר) \u0003במועד לצורך המועד, ושלא לצורך המועד — אסור, ואם הטיל והותיר — הרי זה מותר. ובלבד שלא יערים,\u0004 שלא יעשה מתחילה ביודעין יותר מכדי הצורך, לנצל את היתר העבודה במועד.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003מטילין שכר במועד לצורך המועד, ושלא לצורך המועד — אסור, אחד שכר תמרים, ואחד שכר שעורים. ואף על פי שיש לו\u0004 שיכר \u0003ישן, מערים ושותה מן החדש.\u0004 כלומר, רשאי הוא להערים ולומר שרצונו לשתות שיכר חדש, ולעשות שיכר במועד. משמע שמותר להערים בכגון זה! ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מערימין בכך, ר' יוסי בר יהודה אומר: מערימין.\u0004","מסופר: \u0003רב חצדו ליה חצדא בחולא דמועדא\u0004 \u0005[קצרו לו קציר בחול המועד]\u0006 \u0003שמע שמואל\u0004 על כך \u0003איקפד\u0004 \u0005[\u0006ו\u0005הקפיד].\u0006 ושואלים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003שמואל כיחידאה סבירא ליה\u0004 \u0005[כ\u0006דעת \u0005יחיד סבור הוא],\u0006 כשיטת רבי יוסי האוסר כל מלאכה, אפילו בדבר האבד, במחובר לקרקע? ומשיבים: \u0003לא\u0004 אלא \u0003חצדא דחיטי הוה, דלא הוה פסיד\u0004 \u0005[קציר חיטים היה\u0006 זה, \u0005שאיננו נפסד]\u0006 אם דוחים את קצירתו, ולכן הקפיד.","שואלים: אם כן, \u0003ורב מאי טעמא עביד הכי\u0004 \u0005[מה טעם עשה כך]?\u0006 ומשיבים: \u0003אין לו מה יאכל הוה\u0004 \u0005[היה]\u0006 והיה נזקק למזון ולכן היה מותר לקצור לו. ושואלים: אם כן, \u0003ושמואל\u0004 מדוע הקפיד? ומסבירים: \u0003לא סיימוה קמיה\u0004 \u0005[סיימו\u0006 את הדבר \u0005לפניו]\u0006 לספר לו שרב עשה זאת מחמת דוחקו. \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 \u0003אדם חשוב שאני\u0004 \u0005[שונה]\u0006 וצריך היה לדעתו להחמיר אפילו בכגון זה.","מסופר: \u0003ר' יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 \u0003נפק בחומרתא דמדושא\u0004 \u0005[יצא\u0006 בשבת \u0005בחותמת של אלמוג\u0006 שהיתה על גבי טבעתו\u0005],\u0006 \u0003ואשתי מיא דאחים קפילא ארמאה\u0004 \u0005[ושתה מים שחימם טבח גוי].\u0006 \u0003שמע ר' אמי\u0004 על כך \u0003איקפד\u0004 \u0005[\u0006ו\u0005הקפיד]\u0006 על שני הדברים. \u0003אמר רב יוסף: מאי טעמא איקפד\u0004 \u0005[מה טעם הקפיד]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום חומרתא דמדושא\u0004 \u0005[חותמת האלמוג]\u0006 \u0003הא תניא\u0004 \u0005[הרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003השירין\u0004 (הצמידים), \u0003הנזמים והטבעות — הרי הן ככל הכלים הניטלין\u0004 (שמותר לטלטלם) \u0003בחצר,\u0004 ואם כן נשאם ר' יהודה הנשיא כדין.","\u0003אי\u0004 \u0005[אם]\u0006 \u0003משום דאישתי מיא דאחים קפילא ארמאה\u0004 \u0005[ששתה מים שחימם טבח גוי],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר שמואל בר יצחק אמר רב: כל\u0004 דבר \u0003שנאכל כמות שהוא חי,\u0004 גם אם בישלו אותו גויים \u0003אין בו משום\u0004 איסור \u0003בישולי גויים\u0004 ומים ודאי בכללם. ומותר! ומשיבים על שתי השאלות: \u0003אדם חשוב שאני\u0004 \u0005[שונה]\u0006 וצריך להקפיד יותר משאר אנשים.","\u0003אמר רב חננאל אמר רב: קוצץ אדם דקל במועד, אף על פי שאינו צריך אלא לנסורת שלו\u0004 היוצאת עם ניסור העץ, ולא יותר. ומעירים: \u0003לייט עלה\u0004 \u0005[קילל על כך]\u0006 \u0003אביי\u0004 מי שעושה מלאכה רבה כזאת רק לצורך זה.","מסופר: \u0003רב אשי הוה ליה אבא\u0004 \u0005[היה לו יער]\u0006 \u0003ב\u0004מקום \u0003שלנייא, אזל למיקצייה בחולא דמועדא\u0004 \u0005[הלך לקצוץ אותו בחול המועד\u0006 לצורך מסויים\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שילא משלנייא לרב אשי: מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 במה שאתה עושה, האם סומך אתה על מה \u0003דקאמר\u0004 \u0005[שאמר]\u0006 \u0003רב חננאל אמר רב: קוצץ אדם דקל במועד אף על פי שאינו צריך אלא לנסורת שלו — הא לייט עלה\u0004 \u0005[הרי קילל על כך]\u0006 \u0003אביי\u0004 ומדוע אתה עושה זאת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא שמיע\u0004 \u0005[נשמע]\u0006 \u0003לי,\u0004 לא שמעתי זאת, \u0003כלומר,\u0004 רצה לומר בלשון עדינה \u0003לא סבירא לי\u0004 \u0005[אינני סבור כן].\u0006 \u0003אישתמיט נרגא בעי למיפסקיה לשקיה\u0004 \u0005[נשמט\u0006 הברזל של ה\u0005גרזן מידו\u0006 של רב אשי \u0005ורצה,\u0006 עמד \u0005לקטוע את רגלו],\u0006 \u0003שבקיה\u0004 \u0005[הניחו,\u0006 את היער\u0005]\u0006 ולא קצצו \u0003והדר אתא\u0004 \u0005[וחזר\u0006 ו\u0005בא]\u0006 לאחר המועד לקוצצו, משום שהבין שאירע לו הדבר משום שעבר על דברי אביי.","מסופר: \u0003רב יהודה שרא למיעקר כיתנא, ולמיקטל כשותא, ולמיעקר שומשמי\u0004 \u0005[התיר לעקור פשתן, ולהרוג,\u0006 לקצץ \u0005כשות, ולעקור שומשומים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: בשלמא כיתנא\u0004 \u0005[נניח\u0006 לגבי \u0005הפשתן]\u0006 \u0003חזי\u0004 \u0005[ראוי]\u0006 הוא אפילו בחול המועד \u0003לחפיפה\u0004 \u0005[לכסות]\u0006 בו דברים, \u0003כשותא חזי לשיכרא\u0004 \u0005[כשות ראויה ל\u0006עשיית \u0005שיכר],\u0006 להשתמש בה מיד, \u0003אלא שומשמי למאי חזי\u0004 \u0005[השומשומים למה\u0006 הם \u0005ראויים],\u0006 שהרי הגבעולים קצרים ואינם ראויים לכיסוי, וגרעיני השומשומים צריכים זמן רב לייבוש עד שיהיה ניתן לעצור מהם שמן. אמר לו: \u0003חזי לנזיי דאית בהו\u0004 \u0005[ראויים\u0006 הם לפחות לשימוש \u0005לכוספא היוצאת מהם]\u0006 לאחר סחיטת השמן מהשומשומים.","מסופר: \u0003ר' ינאי הוה ליה ההוא פרדיסא דמטא זמניה בחולא דמועדא\u0004 \u0005[היה לו פרדס אחד שהגיע זמנו\u0006 לקטיפה בדיוק \u0005בחול המועד],\u0006 \u0003קטפיה\u0004 \u0005[קטף אותו]\u0006 באותו זמן, כיון שאי אפשר היה לאחר הרבה. \u0003לשנה\u0004 הבאה \u0003שהיוה כולי עלמא לפרדיסייהו לחולא דמועדא\u0004 \u0005[השהו הכל את פרדסיהם\u0006 מלקטפם עד \u0005חול המועד]\u0006 כדי שיוכלו לעשות את קטיפם במועד. \u0003אפקריה\u0004 \u0005[הפקירו]\u0006 \u0003ר' ינאי לפרדיסיה ההוא שתא\u0004 \u0005[\u0006את הכסף שהרויח מ\u0005פרדסו\u0006 שבאותה \u0005שנה],\u0006 משום שגרם על ידי קציצתו מכשול לרבים, שלמדו ממנו להקל שלא כדין.","\u0003מכניס אדם פירותיו\u0004 מן השדה הביתה \u0003מפני\u0004 שחושש מן \u0003הגנבים, ושולה\u0004 (מוציא) \u0003פשתנו מן המשרה\u0004 (המים ששורים אותו בהם) לפני ניפוצו \u0003בשביל שלא תאבד\u0004 ותירקב במים, \u0003ובלבד שלא יכוין\u0004 מתחילה \u0003את מלאכתו\u0004 לעשותה \u0003ב\u0004חול ה\u0003מועד. וכולן\u0004 בכל המלאכות \u0003אם כוונו מלאכתן במועד\u0004 — \u0003יאבדו,\u0004 אם אנשים התכוונו וקבעו מראש לעשות את המלאכה דווקא במועד, ילכו הפירות הללו לאיבוד.","על מה שנאמר במשנה שמכניס אדם פירותיו מפני הגנבים, \u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003ובלבד שיכניסם בצנעא לתוך ביתו\u0004 ולא יעשה בפרהסיא.","מסופר: \u0003רב יוסף הוה ליה כשורי\u0004 \u0005[היו לו קורות],\u0006 \u0003עיילינהו ביממא\u0004 \u0005[הכניס אותן\u0006 לבית \u0005ביום,\u0006 בחול המועד\u0005],\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ובלבד שיכניסם בצנעא בתוך ביתו! אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003צנעא דהני\u0004 \u0005[הצינעה של אלה] —\u0006 \u0003יממא\u0004 \u0005[יום]\u0006 \u0003הוא,\u0004 ומדוע, \u0003כיון דבליליא בעו גברא יתירי\u0004 \u0005[שבלילה צריכים\u0006 ל\u0005אנשים יתרים],\u0006 שכאשר אנשים רואים פחות דרושים יותר אנשים לעשות את אותה עבודה, \u0003ובעו מדוכרי דנורא\u0004 \u0005[ו\u0006גם \u0005צריכים לפידי אש],\u0006 ממילא \u0003אוושא מילתא\u0004 \u0005[\u0006יעשה \u0005הדבר רעש]\u0006 גדול בלילה מביום.","שנינו במשנה: \u0003ושולה פשתנו מן המשרה\u0004 ו\u0003כו',\u0004 ושנינו שאם כיוון מלאכתו במועד — צריך לאבד מה שעשה. \u0003בעי מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' ירמיה מר' זירא:\u0004 מי ש\u0003כוון מלאכתו\u0004 מלכתחילה כדי לעשותה \u0003במועד ומת, מהו שיקנסו בניו אחריו,\u0004 האם גם הם צריכים לאבד את מה שעשה אביהם במועד?","וצדדי השאלה; \u0003אם תימצי\u0004 \u0005[תמצא,\u0006 תרצה\u0005]\u0006 \u0003לומר\u0004 לפי ההלכה בדיני בכורות"],["מי ש\u0003צרם אזן בכור\u0004 שחתך מעט מאוזנו של בכור, כדי שיהיה בעל מום ויהיה מותר לאכילה, ולאחר מכן מת — \u0003קנסו בנו אחריו,\u0004 שאף הוא אסור לאכול מבשר בכור זה, אפשר לדחות ולומר ששם החמירו \u0003משום\u0004 שהוא \u0003איסורא דאורייתא\u0004 \u0005[איסור של תורה],\u0006","\u0003ואם תמצי\u0004 \u0005[תמצא,\u0006 תרצה\u0005]\u0006 \u0003לומר\u0004 ולהוכיח מדין מי ש\u0003מכר עבדו לגוי\u0004 שקונסים אותו שייחשב העבד כמשוחרר ולא ישוב לעבוד את אדונו זה \u0003ומת\u0004 המוכר ש\u0003קנסו\u0004 גם \u0003בנו אחריו,\u0004 אפשר לדחות ולומר שיש שם טעם מיוחד \u0003משום דכל יומא מפקע ליה\u0004 \u0005[שבכל יום מפקיע אותו]\u0006 הגוי \u0003ממצות\u0004 ונמצא שגרם הרבה עבירות על ידי מעשהו ולכן החמירו חכמים,","\u0003הכא מאי\u0004 \u0005[כאן מה\u0006 הדין\u0005]\u0006 במכוון מלאכתו בחול המועד, האם נאמר כי \u0003גברא קניס רבנן והא ליתיה\u0004 \u0005[\u0006את \u0005האיש קנסו חכמים והרי איננו,\u0006 שמת\u0005],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003ממונא קניס רבנן והא איתיה\u0004 \u0005[\u0006את \u0005הממון קנסו חכמים והרי נמצא\u0006 עדיין\u0005]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לר' ירמיה: \u0003תניתוה\u0004 \u0005[שניתם אותה],\u0006 כלומר, יש פתרון לבעיה זו ממה ששנינו במשנה הידועה לכול; \u0003שדה שנתקווצה\u0004 (שהוציאו ממנה את הקוצים) \u0003בשביעית — תזרע למוצאי שביעית,\u0004 שאין עקירת הקוצים מלאכה גמורה האוסרת את השדה, אבל \u0003נטייבה\u0004 (הושבחה בזבל), \u0003או נדיירה\u0004 שהביא לשם בהמות שיהלכו בשדה וימלאוהו זבל — \u0003לא תזרע למוצאי שביעית,\u0004 שקנסוהו שלא ייהנה ממלאכת איסור. \u0003ואמר ר' יוסי בר חנינא: נקטינן\u0004 \u0005[מוחזקים אנו],\u0006 אם \u0003הטיבה\u0004 באיסור \u0003ומת — בנו\u0004 מותר לו ל\u0003זורעה, אלמא\u0004 \u0005[מכאן]\u0006 נסיק מסקנה כללית ש\u0003לדידיה\u0004 \u0005[לו,\u0006 אותו\u0005]\u0006 \u0003קנסו רבנן\u0004 \u0005[חכמים],\u0006 אולם \u0003לבריה\u0004 \u0005[לבנו]\u0006 \u0003לא קנסו רבנן\u0004 \u0005[חכמים],\u0006 \u0003הכא נמי\u0004 \u0005[כאן\u0006 במועד \u0005גם כן],\u0006 \u0003לדידיה\u0004 \u0005[לו,\u0006 אותו\u0005]\u0006 \u0003קנסו רבנן\u0004 \u0005[חכמים],\u0006 אולם \u0003לבריה\u0004 \u0005[לבנו]\u0006 \u0003לא קנסו רבנן\u0004 \u0005[חכמים].\u0006","\u0003אמר אביי: נקטינן\u0004 \u0005[מוחזקין אנו]\u0006 בהלכות קנסות חכמים: מי ש\u0003טימא טהרותיו\u0004 של אחר, שחייב לשלם לו את הנזק שנגרם על ידי כך, \u0003ומת\u0004 ולא הספיק לשלם — \u0003לא קנסו בנו אחריו\u0004 שישלם זאת. ו\u0003מאי טעמא\u0004 \u0005[מה טעמו\u0006 של דבר\u0005] —\u0006 \u0003היזק שאינו ניכר\u0004 שמעשה ההיזק איננו עושה שינוי חומרי הנראה בעין, מדין התורה \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003היזק,\u0004 אלא כיון שבכל זאת גרם המטמא לנזק קנסוהו חכמים, וכיון שהוא רק מגדר קנס \u0003לדידיה\u0004 \u0005[לו,\u0006 אותו\u0005]\u0006 \u0003קנסו רבנן\u0004 \u0005[חכמים],\u0006 אולם \u0003לבריה\u0004 \u0005[לבנו]\u0006 \u0003לא קנסו רבנן\u0004 \u0005[חכמים].\u0006","\u0003אין לוקחין\u0004 (קונים) \u0003בתים, עבדים ובהמה\u0004 בחול המועד \u0003אלא לצורך המועד, או לצורך המוכר שאין לו מה יאכל.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן: שכר פעולה\u0004 (עבודה) של פועל \u0003שאין לו מה יאכל, מהו?\u0004 המותר למסור עבודה לפועל עני בחול המועד? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה, שהרי שנינו במשנה: \u0003או לצורך המוכר שאין לו מה יאכל.\u0004 תוספת זו \"שאין לו מה יאכל\" \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף את \u0005מה]\u0006 היא באה? שהרי לענין המוכר כבר נאמר ש\"לצורך המוכר\" מותר! \u0003לאו לאתויי\u0004 \u0005[\u0006האם \u0005לא להביא,\u0006 לרבות\u0005]\u0006 \u0003שכר פעולה\u0004 שמותר גם במקרה כזה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 ואין הדבר מוכרח, כי שמא \u0003פרושי קא מפרש\u0004 \u0005[פירוש הוא שמפרש],\u0006 שמפרש מה שאמר \"לצורך המוכר\", ומסביר — שאין לו מה יאכל.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי,\u0004 שנינו: \u0003אין כותבין שטרי חוב ב\u0004חול ה\u0003מועד, ואם\u0004 המלווה \u0003אינו מאמינו\u0004 ללווה, וחושש שבלא שטר לא יוכל לגבות חובו, \u0003או שאין לו מה יאכל — הרי זה יכתוב.\u0004 ונברר: \u0003\"שאין לו מה יאכל\" לאתויי מאי\u0004 \u0005[להביא\u0006 לרבות, \u0005מה]\u0006 \u0003לאו לאתויי\u0004 \u0005[\u0006האם \u0005לא להביא]\u0006 \u0003שכר פעולה\u0004 של הלבלר, כותב השטר? \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמותר לשכור פועל הנזקק לפרנסה לעשות אף מלאכה האסורה בחול המועד.","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003רב ששת\u0004 על דברי רב נחמן ממה ששנינו, שאסרו חכמים לעשות מלאכה בערב פסח, ודינו לענין זה כחול המועד, אבל \u0003וחכמים אומרים: שלש\u0004 (בעלי) \u0003אומניות עושין מלאכה בערבי פסחים עד חצות\u0004 והם: \u0003החייטין והספרין והכובסין.\u0004 ומסבירים בברייתא מפני מה הותרו מלאכות אלה. \u0003החייטין\u0004 מותרים — \u0003שכן הדיוט\u0004 (שאיננו בעל מלאכה) \u0003תופר כדרכו\u0004 אפילו \u0003בחולו של מועד, הספרין והכובסין — שכן הבאין ממדינת הים והיוצא מבית האסורין\u0004 שלא הספיקו לספר ולכבס לפני כן \u0003מותרין לספר ולכבס\u0004 אף \u0003בחולו של מועד,\u0004 שמלאכה המותרת באופן כלשהו בחול המועד מותרת גם בערב פסח.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003שכר פעולה\u0004 כאשר הפועל \u0003אין לו מה יאכל שרי\u0004 \u0005[מותר]\u0006 בחול המועד, אם כן \u0003כל\u0004 ה\u0003מלאכות\u0004 האחרות \u0003נמי לישתרו\u0004 \u0005[גם כן תהיינה מותרות]\u0006 מטעם זה בערב פסח, \u0003דהא איכא\u0004 \u0005[שהרי יש]\u0006 כיוצא בהן בחול המועד \u0003שכר פעולה כשאין לו מה יאכל,\u0004 וכיון שלא נאמר הדבר — משמע שאסורה מלאכה לפועל גם אם אין לו מה שיאכל!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: אלא מעתה\u0004 שלמדים מחול המועד לערב פסח מאותו טעם \u0003בנין\u0004 בערב פסח \u0003לישתרי\u0004 \u0005[יותר],\u0006 \u0003שכן כותל הגוהה\u0004 (הנוטה ליפול) \u0003לרשות הרבים — סותר ובונה\u0004 בחול המועד \u0003כדרכו מפני הסכנה!\u0004","וכן \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: אלא מעתה לבלר\u0004 (כותב שטרות) \u0003לישתרי\u0004 \u0005[יותר]\u0006 לעשות מלאכתו בערב פסח, \u0003שכן כותבין\u0004 במועד \u0003קידושי נשים, גיטין ושוברין!\u0004","\u0003אלא אמר רב אשי:\u0004 כל הקושיות הללו אין להן בסיס, כי מדין חול ה\u0003מועד\u0004 על דין יום \u0003ארבעה עשר\u0004 בניסן \u0003קא רמית\u0004 \u0005[אתה משליך,\u0006 מראה סתירה\u0005]?\u0006 יש הבדל יסודי ביניהם; חול ה\u0003מועד\u0004 איסורו במלאכה \u0003משום טירחא הוא, ובמקום פסידא\u0004 \u0005[הפסד]\u0006 \u0003שרו רבנן\u0004 \u0005[התירו חכמים],\u0006 ואילו \u0003ארבעה עשר\u0004 בניסן שנאסר במלאכה \u0003משום צורך יום טוב הוא\u0004 כדי שיהיו הכל פנויים להכין ליום טוב, בפרט לקרבן פסח. ולכן \u0003מידי\u0004 \u0005[דבר]\u0006 שהוא ל\u0003צורך יום טוב שרו רבנן\u0004 \u0005[התירו חכמים]\u0006 כמלאכת החייטים והספרים, אולם \u0003מידי דלאו\u0004 \u0005[דבר שאינו]\u0006 ל\u0003צורך יום טוב לא שרו רבנן\u0004 \u0005[התירו חכמים].\u0006","\u0003אין מפנין\u0004 כלים \u0003מבית לבית, אבל מפנה הוא\u0004 מן הבית \u0003לחצרו\u0004 אם זקוק לכך. \u0003אין מביאין כלים מבית האומן\u0004 לאחר שסיים מלאכתם, אבל \u0003אם חושש להם\u0004 שמא ייגנבו — \u0003מפנן לחצר אחרת.\u0004","שנינו במשנה: אבל מפנה הוא לחצרו, ולכאורה הכוונה שמפנה מחצר אחרת לחצרו. ותוהים: \u0003והאמרת רישא\u0004 \u0005[והרי אמרת בתחילה]\u0006 \u0003אין מפנין כלל\u0004 אף מבית לבית, וכיצד חוזרים ואומרים שמפנים? \u0003אמר אביי: סיפא אתאן\u0004 \u0005[בסוף באנו]\u0006 לדון במקרה כשמפנים מבית \u0003לבית שבחצר,\u0004 שאין מפנה מחצר אחרת, אלא מוציא מן הבית שבחצר לאותה חצר.","עוד שנינו במשנה: \u0003ואין מביאין כלים מבית האומן. אמר רב פפא: בדיק לן\u0004 \u0005[בדק,\u0006 בחן, \u0005אותנו]\u0006 \u0003רבא\u0004 בשאלה הבאה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מביאין כלים מבית האומן, ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממשנה אחרת שנאמר בה: \u0003מוליכין ומביאין כלים מבית האומן, ואף על פי שאינן לצורך המועד!\u0004","\u0003ושנינן ליה\u0004 \u0005[ותירצנו לו]:\u0006 \u0003כאן\u0004 במשנה המתירה מדובר \u0003בארבעה עשר\u0004 בניסן בערב חג הפסח, ו\u0003כאן\u0004 במשנתנו האוסרת, מדובר \u0003בחולו של מועד. איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר, \u0003הא והא\u0004 \u0005[זו וזו]\u0006 מדובר \u0003בחולו של מועד, כאן\u0004 במשנתנו האוסרת, הרי זה מדובר \u0003בשמאמינו\u0004 לאומן, ואינו חושש לכליו, ולכן אינו רשאי להוציאם. \u0003כאן\u0004 במשנה המתירה, הרי זה \u0003בשאינו מאמינו\u0004 שאינו סומך על האומן ולכן התירו לו להוציא ממנו את הכלים."],["\u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מביאין כלים מבית האומן, כגון כד מבית הכדר\u0004 (עושה הכדים) \u0003וכוס מבית הזגג,\u0004 שהרי משתמשים בהם במועד עצמו. \u0003אבל לא\u0004 יביא \u0003צמר מבית הצבע ולא כלים מבית האומן,\u0004 כיון שאינם צורך המועד. \u0003ואם אין לו\u0004 לאומן \u0003מה יאכל — נותן לו\u0004 לאומן \u0003שכרו\u0004 במועד \u0003ומניחו\u0004 את הכלי \u0003אצלו. ואם אינו מאמינו\u0004 לאומן בשמירת כלי זה \u0003מניחו בבית הסמוך לו. ואם חושש להם שמא יגנבו — מפנן לחצר אחרת, ואם אינו מאמינו\u0004 לבעל החצר — \u0003מביאן בצנעה בתוך ביתו.\u0004","ומעירים: \u0003תרצת\u0004 ענין זה של \u0003מביאין\u0004 כלים מבית האומן, שאפשר לפרש אותו שמדובר באופן שאינו מאמינו, אבל בענין \u0003מוליכין\u0004 האמור בברייתא \u0003קשיא\u0004 \u0005[קשה],\u0006 \u0003דקתני\u0004 \u0005[ששנינו]\u0006 במשנה: \u0003\"אין מביאין\", וכל שכן שאין מוליכין! אלא\u0004 יש לדחות מה שאמרנו: \u0003מחוורתא כדשניין מעיקרא\u0004 \u0005[מחוור,\u0006 ברור, \u0005כפי שתירצנו קודם]\u0006 שיש להבדיל בין ערב פסח לחול המועד.","\u0003מחפין\u0004 (מכסים) \u0003את הקציעות\u0004 (התאנים העומדות להתייבש) \u0003בקש\u0004 שלא יירטבו. \u0003ר' יהודה אומר: אף מעבין\u0004 מניחים אותן בערימה צפופה יותר. \u0003מוכרי פירות, כסות וכלים — מוכרים בצנעה לצורך המועד. הציידין והדשושות\u0004 (האומנים הדשים תבואה) \u0003והגרוסות\u0004 (הכותשים את גרגירי הפול לעשותם גרוסים) — \u0003עושין בצנעה לצורך המועד. ר' יוסי אומר: הם החמירו על עצמן\u0004 שלא לעשות מלאכה אפילו לצורך זה.","\u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בשאלה זו \u0003ר' חייא בר אבא ור' אסי, ותרוייהו\u0004 \u0005[ושניהם]\u0006 אמרו זאת \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003חזקיה ור' יוחנן. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: \"מחפין\"\u0004 פירושו \u0003אקלושי\u0004 \u0005[\u0006לכסות בצורה \u0005קלושה]\u0006 את התאנים, \u0003\"מעבין\" — אסמוכי\u0004 \u0005[\u0006כיסוי \u0005סמיך,\u0006 צפוף\u0005].\u0006 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: \"מחפין\"\u0004 פירושו \u0003בין אקלושי\u0004 \u0005[\u0006בצורה \u0005קלושה]\u0006 \u0003בין אסמוכי\u0004 \u0005[\u0006בצורה \u0005צפופה],\u0006 אבל \u0003\"מעבין\"\u0004 פירושו ש\u0003עושה אותו כמין כרי,\u0004 שעורמים כעין ערימה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003\"מעבין\" — עושה אותו כמין כרי,\u0004 אלו \u0003דברי ר' יהודה.\u0004","שנינו במשנה ש\u0003מוכרי פירות כסות וכלים מוכרין בצנעה\u0004 וכן הציידים הדשושות והגרוסות עושים בצינעה לצורך המועד, ורבי יוסי אמר שהם החמירו על עצמם. \u0003אבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003\"הן החמירו על עצמן\"\u0004 פירושו \u0003דלא הוו עבדי\u0004 \u0005[שלא היו עושים]\u0006 \u0003כלל\u0004 מלאכה בחול המועד, \u0003או דלמא\u0004 \u0005[שמא]\u0006 החמירו על עצמם \u0003דהוו עבדי\u0004 \u0005[שהיו עושים]\u0006 \u0003בצנעה,\u0004 אף שמעיקר הדין מותר אפילו בפרהסיה? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו, ממה ששנינו: \u0003מוכרי פירות כסות וכלים\u0004 — \u0003מוכרין בצנעה לצורך המועד, ר' יוסי אומר: תגרי טבריא\u0004 \u0005[טבריה]\u0006 \u0003הן\u0004 ש\u0003החמירו על עצמן שלא יהו מוכרין כל עיקר\u0004 אפילו בצינעה. וכן \u0003צדי חיות ועופות ודגים\u0004 — \u0003צדין בצנעה לצורך המועד, ר' יוסי אומר: צדי עכו הן\u0004 ש\u0003החמירו על עצמן שלא יהו צדין כל עיקר. דשושי חילקא טרגיס וטיסני\u0004 (הכותשים את החיטים לגריסים קטנים) — \u0003דוששין בצנעה לצורך המועד, ר' יוסי אומר: דשושי ציפורי הן\u0004 ש\u0003החמירו על עצמן שלא יהו דוששין כל עיקר.\u0004 הרי שרבי יוסי בא להחמיר ולא להקל.","","\u0003אמר אביי: \"חילקא\"\u0004 פירושו שכותשים את התבואה \u0003חדא לתרתי\u0004 \u0005[\u0006גרעין \u0005אחד לשניים]\u0006 \u0003\"טרגיס\" — חדא לתלת\u0004 \u0005[אחד לשלושה]\u0006 \u0003\"טיסני\"\u0004 — \u0003חדא\u0004 \u0005[אחד]\u0006 \u0003לארבעה. כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר:\u0004 \"חילקא\" פירושו \u0003כונתא\u0004 \u0005[כוסמת].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003חילקא טרגיס וטיסני טמאין בכל מקום\u0004 משום שהם נחשבים לאוכל גמור. ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שכל אלה כוונתם \u0003חדא לתרתי לתלת\u0004 \u0005[אחד לשניים לשלושה]\u0006 \u0003ולארבעה, משום הכי\u0004 \u0005[כך]\u0006 הם \u0003טמאין בכל מקום, דאתכשור\u0004 \u0005[שהוכשרו]\u0006 לקבל טומאה על ידי מים בתוך תהליך עשייתם, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהיא \u0003כונתא\u0004 \u0005[כוסמת],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 הם \u0003טמאין בכל מקום, הא\u0004 \u0005[הרי]\u0006 \u0003לא איתכשור\u0004 \u0005[הוכשרו\u0006 לקבל טומאה\u0005]?\u0006","ומשיבים: \u0003כגון דמיקלפן\u0004 \u0005[ש\u0006היו \u0005קלופות],\u0006 \u0003דאי לאו דשרא להו במיא לא הוה מיקלפא\u0004 \u0005[שאם לא היה שורה אותן\u0006 קודם \u0005במים לא היתה נקלפת].\u0006 \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קוראים לה]\u0006 \u0003\"חילקא\"\u0004 — משום \u0003דשקל חלקיהו\u0004 \u0005[שנטל\u0006 מהם \u0005קליפתם],\u0006 ועכשיו הן חלקות.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך, ממה ששנינו: \u0003הנודר\u0004 ואוסר על עצמו לאכול \u0003מן הדגן\u0004 — \u0003אסור אף בפול המצרי יבש\u0004 שהוא נכלל בגדר דגן בפי בני אדם, \u0003ומותר ב\u0004פול \u0003לח, ומותר באורז בחילקא וטרגיס וטיסני.\u0004 ועתה שואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שהוא חיטים שנחלקו \u0003חדא לתרתי חדא לתלת\u0004 \u0005[אחת לשתיים אחת לשלושה]\u0006 \u0003וחדא\u0004 \u0005[ואחת]\u0006 \u0003לארבעה\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 \u0003דנפקו להו\u0004 \u0005[שיוצאים להם]\u0006 על ידי גריסתם \u0003מתורת \"דגן\"\u0004 והם קרויים מעתה \"מיני מזונות\", \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שהיא \u0003כונתא\u0004 \u0005[כוסמת],\u0006 הלא \u0003דגן מעליא\u0004 \u0005[מעולה,\u0006 חשוב\u0005]\u0006 \u0003הוא!\u0004 שהלא הכוסמת היא מחמשת מיני דגן. ומעירים, אכן \u0003קשיא\u0004 \u0005[קשה].\u0006","מסופר: \u0003רב הונא שרא להו להנהו כרופייתא למיזל לזבוני כי אורחייהו בשוקא\u0004 \u0005[התיר להם למוכרי תבלינים ללכת למכור כדרכם בשוק].\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב כהנא\u0004 ממה ששנינו: אם היתה \u0003חנות פתוחה לסטיו\u0004 (שדרת העמודים ברחוב שלפני החנות) — \u0003פותח ונועל\u0004 בחול המועד \u0003כדרכו\u0004 בחול, משום שאין זה גלוי לרבים, אבל אם היתה \u0003פתוחה לרשות הרבים\u0004 — \u0003פותח\u0004 דלת \u0003אחת ונועל אחת,\u0004 אבל ב\u0003ערב יום טוב האחרון של חג מוציא\u0004 את הדברים מן החנות \u0003ומעטר את שוקי העיר בפירות בשביל כבוד יום טוב האחרון.\u0004 ומעתה נדייק: \u0003מפני כבוד יום טוב האחרון — אין\u0004 \u0005[כן]\u0006 התירו לפתוח חנות כדרכה, אבל \u0003שלא מפני כבוד יום טוב — לא!\u0004 ואיך אם כן התיר רב הונא לאותם מוכרי בשמים למכור כדרכם בחול המועד?","","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאסרו למוכרם בפרהסיה, הרי זה \u0003בפירי\u0004 \u0005[בפירות]\u0006 שקונים מהם כמות גדולה ויכולים לקנותם לפני החג, ויחשדו שקונה לאחר המועד, \u0003הא\u0004 \u0005[זה]\u0006 שלא אסר רב הונא, היה זה \u0003ב\u0004מכירת \u0003תבלין,\u0004 שאין לאוסרם משום שהאדם לוקח מהם דבר מועט לצורך המועד.","","\u0003ואלו מגלחין\u0004 בהיתר \u0003ב\u0004חול ה\u0003מועד: הבא ממדינת הים\u0004 בחול המועד, או היוצא \u0003מבית השביה, והיוצא מבית האסורין ו\u0004כן \u0003המנודה שהתירו לו חכמים\u0004 את הנידוי בחול המועד, שרק אז הותר לו להסתפר. \u0003וכן מי\u0004 שנדר נדר שלא להסתפר ו\u0003נשאל לחכם\u0004 על נדרו \u0003והותר\u0004 בחול המועד. \u0003ו\u0004כן \u0003הנזיר\u0004 שנגמר זמן נזירותו בחול המועד, \u0003ו\u0004כן \u0003המצורע\u0004 הצריך לגלח \u0003מטומאתו לטהרתו\u0004 במועד, כל אלה, כיון שלא יכלו לגלח בערב החג מותר להם לגלח בחול המועד.","\u0003ואלו מכבסין\u0004 בהיתר \u0003במועד: הבא ממדינת הים, ומבית השביה, והיוצא מבית האסורין,\u0004"]]};
